import{d as at,C as u,o as et,c as it,j as d,a as e,E as a,a3 as i,k as r}from"./chunks/framework.Q4yG9rk_.js";const ot=JSON.parse('{"title":"庄子·列御寇","description":"从列子惊返与他人依附开始，辨析显能、身份、自是、言说与技巧如何形成牵累，并追问知识是否通向生命与精神的安顿。","frontmatter":{"title":"庄子·列御寇","description":"从列子惊返与他人依附开始，辨析显能、身份、自是、言说与技巧如何形成牵累，并追问知识是否通向生命与精神的安顿。","category":"庄子精读","aliases":["列御寇","庄子列御寇","庄子·列御寇精读"],"source":["《庄子·杂篇·列御寇》","用户提供的原文与分段整理材料"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-32.md","filePath":"daoism/zhuang-zi/chapter-32.md","lastUpdated":1792641266000}'),nt={name:"daoism/zhuang-zi/chapter-32.md"},st=at({...nt,setup(rt){const y=[{id:"lyk1-lieyukou",term:"列御寇",pinyin:"",meaning:"列子，御寇为名。"},{id:"lyk1-zhiqi",term:"之齐",pinyin:"",meaning:"到齐国去。“之”为往、到。"},{id:"lyk1-fan",term:"反",pinyin:"",meaning:"返回，通“返”。"},{id:"lyk1-bohun",term:"伯昏瞀人",pinyin:"瞀：通常读 mào",meaning:"本段中的教诲者；不在此补定人物生平与历史身份。"},{id:"lyk1-xifang",term:"奚方而反",pinyin:"",meaning:"为什么、因何而返回？“方”的具体训释有差异。"},{id:"lyk1-wuhu",term:"恶乎惊",pinyin:"wū hū jīng",meaning:"因什么而惊？“恶”在此为疑问词。"},{id:"lyk1-shijiang-a",term:"十浆",pinyin:"shí jiāng",meaning:"十家卖浆之肆。「吾尝食于十浆而五浆先馈」，写他处受到的优待。"},{id:"lyk1-shijiang-b",term:"五浆",pinyin:"wǔ jiāng",meaning:"五家卖浆者先送食。与「十浆」并举，写超出常情的优待。"},{id:"lyk1-xiankui",term:"先馈",pinyin:"",meaning:"优先给食；是否包含馈赠意味，有解释空间。"},{id:"lyk1-neicheng",term:"内诚不解",pinyin:"",meaning:"通常联系内在真实、诚实之气尚未消解理解；“解”的确切所指有训释差异。"},{id:"lyk1-xingdie",term:"形谍成光",pinyin:"",meaning:"大意联系内在状态显露于形貌，形成光采理解；“谍”为疑难用字，不强定逐字译法。"},{id:"lyk1-zhen",term:"镇人心",pinyin:"",meaning:"镇服、震慑他人的心，使人受到感动或影响。"},{id:"lyk1-guilao",term:"贵老",pinyin:"",meaning:"尊贵者与年长者。"},{id:"lyk1-ji",term:"赍其所患",pinyin:"赍：jī",meaning:"带来、招致自己所担忧的患累；具体句法有解释空间。"},{id:"lyk1-te",term:"特",pinyin:"",meaning:"只是、不过。"},{id:"lyk1-shigeng",term:"食羹之货",pinyin:"",meaning:"饮食、羹汤一类商品。"},{id:"lyk1-ying",term:"赢",pinyin:"yíng",meaning:"盈余、赢利。"},{id:"lyk1-wansheng",term:"万乘之主",pinyin:"wàn shèng",meaning:"大国君主，以兵车数量表示权势。"},{id:"lyk1-zhijin",term:"知尽于事",pinyin:"",meaning:"智力、心智耗尽于事务。“知”联系“智”理解。"},{id:"lyk1-xiaogong",term:"效我以功",pinyin:"",meaning:"根据功效考核、责求我。"},{id:"lyk1-ru",term:"女",pinyin:"rǔ",meaning:"通“汝”，你。"},{id:"lyk1-chuyi",term:"处已",pinyin:"",meaning:"安处、止居吧；“已”联系语气理解。"},{id:"lyk1-baoru",term:"保汝",pinyin:"",meaning:"聚集、亲附、依附于你；不宜直接译为现代的保护或担保。"},{id:"lyk1-wujihe",term:"无几何",pinyin:"",meaning:"没过多久。"},{id:"lyk1-ju",term:"屦",pinyin:"jù",meaning:"鞋。"},{id:"lyk1-beimian",term:"北面而立",pinyin:"",meaning:"面向北方站立；先按方位记述，不据此强定完整礼位。"},{id:"lyk1-dunzhang",term:"敦杖蹙之乎颐",pinyin:"",meaning:"大意为立杖，以杖抵近或支住下颏；“敦”“蹙”的具体动作有训释差异。"},{id:"lyk1-youjian",term:"有间",pinyin:"",meaning:"过了一会儿。"},{id:"lyk1-binzhe",term:"宾者",pinyin:"",meaning:"接待、通报来客的人。"},{id:"lyk1-xian",term:"跣",pinyin:"xiǎn",meaning:"赤脚。"},{id:"lyk1-jiyu",term:"暨",pinyin:"jì",meaning:"到、及。"},{id:"lyk1-zengbu",term:"曾不",pinyin:"",meaning:"竟不、难道不。"},{id:"lyk1-fayao",term:"发药",pinyin:"",meaning:"发出如药石般的教诲、规劝。"},{id:"lyk1-ganyu",term:"感豫出异",pinyin:"",meaning:"通常联系感动他人、使人悦服、显出异于常人的表现理解；具体字义与句法有疑难。"},{id:"lyk1-yao",term:"摇而本性",pinyin:"",meaning:"摇动、扰动你的本性。“而”通“尔”。"},{id:"lyk1-wuwei",term:"无谓",pinyin:"",meaning:"没有意义、无益。"},{id:"lyk1-jinrendu",term:"尽人毒",pinyin:"",meaning:"通常联系使人受到损害、陷入害处理解；不只按现代“毒物”义解释。"},{id:"lyk1-xiangshu",term:"何相孰也",pinyin:"",meaning:"通常联系相互亲熟、交游何益理解；具体句法有差异。"},{id:"lyk1-qiaozhi-a",term:"巧者",pinyin:"qiǎo zhě",meaning:"以巧见长者。「巧者劳而知者忧」，与「无能者无所求」对举。"},{id:"lyk1-qiaozhi-b",term:"知者",pinyin:"zhī zhě",meaning:"以智见长者。劳、忧并举，写才能本身也带来牵累。"},{id:"lyk1-wuneng",term:"无能者",pinyin:"",meaning:"与“巧者”“知者”对举，可联系不以能巧自居、不凭显能求取理解，不简单等同于什么都不会。"},{id:"lyk1-aoyou",term:"敖游",pinyin:"áo yóu",meaning:"遨游，自在游行。"},{id:"lyk1-fanfu",term:"汎",pinyin:"fàn",meaning:"泛，漂浮。"},{id:"lyk1-buxizhou",term:"不系之舟",pinyin:"",meaning:"没有被绳索系住的船。"},{id:"lyk1-xu",term:"虚",pinyin:"",meaning:"结合本段，可联系不被求取、显能及自我执持填满的状态理解；不只是空无一物。"},{id:"lyk2-huan",term:"缓",pinyin:"",meaning:"郑人的名字，不在此按性情迟缓解释。"},{id:"lyk2-shenyin",term:"呻吟",pinyin:"",meaning:"此处通常联系吟诵、诵读理解，不是痛苦呻吟。"},{id:"lyk2-qiushi",term:"裘氏之地",pinyin:"",meaning:"裘氏所在之处，通常理解为学习场所；人物与地点细节不在此补定。"},{id:"lyk2-zhisan",term:"祗三年",pinyin:"",meaning:"仅三年。“祗”联系“只”理解。"},{id:"lyk2-weiru",term:"为儒",pinyin:"",meaning:"成为儒者、习儒学。"},{id:"lyk2-herun",term:"河润九里",pinyin:"",meaning:"以河水润泽比拟影响扩展；“九里”不宜当作需要精确测量的地理记载。"},{id:"lyk2-sanzu",term:"泽及三族",pinyin:"",meaning:"恩泽、影响扩及亲族；“三族”的具体范围有不同说法。"},{id:"lyk2-dimo",term:"使其弟墨",pinyin:"",meaning:"使、促使其弟成为墨者；与前句如何衔接有解释空间。"},{id:"lyk2-rumo",term:"儒墨",pinyin:"",meaning:"儒者与墨者，此处落实于缓与其弟的争辩。"},{id:"lyk2-zhudi",term:"助翟",pinyin:"",meaning:"支持墨的一方。“翟”为墨翟之名，不据此认定墨子本人到场。"},{id:"lyk2-shinian",term:"十年",pinyin:"",meaning:"故事中的时间记述，具体起算点不在此强定。"},{id:"lyk2-mengzhi",term:"其父梦之",pinyin:"",meaning:"其父梦见他，即梦见已死的缓；引语通常读作缓在梦中对父亲说话，仍保留句法讨论空间。"},{id:"lyk2-erzi",term:"而子",pinyin:"",meaning:"你的儿子。“而”通“尔”。"},{id:"lyk2-yu",term:"予",pinyin:"",meaning:"我，梦中说话者的自称。"},{id:"lyk2-hechang",term:"阖尝",pinyin:"",meaning:"通常联系“何尝”“曾否”等疑问语气理解，具体训释有差异。"},{id:"lyk2-liang",term:"良",pinyin:"",meaning:"常联系坟墓等解释，也有不同理解，属于本段疑难字。"},{id:"lyk2-qiubai",term:"秋柏之实",pinyin:"",meaning:"秋日柏树的果实；梦中语境里通常联系死后变化理解，不作写实或超自然事实的证明。"},{id:"lyk2-zaowu",term:"造物者",pinyin:"",meaning:"使万物生成、变化的力量或过程，不必等同于有人格意志的神。"},{id:"lyk2-baoren",term:"报人",pinyin:"",meaning:"对人发生作用、回应或回报；不宜径直限定为道德奖惩。"},{id:"lyk2-renzhitian",term:"人之天",pinyin:"",meaning:"人天然所受的性分、生命根据，与人为标举的身份相区别。"},{id:"lyk2-bigu",term:"彼故使彼",pinyin:"",meaning:"大意联系各依其天然所受而如此理解；代词所指与句法有解释空间。"},{id:"lyk2-yiyuren",term:"有以异于人",pinyin:"",meaning:"自认为有某种优于、不同于他人的凭据。"},{id:"lyk2-jianqin",term:"贱其亲",pinyin:"",meaning:"轻贱、看低自己的亲近者或亲属。"},{id:"lyk2-jingyin",term:"井饮者",pinyin:"",meaning:"从井取水而饮的人。"},{id:"lyk2-xiangzuo",term:"相捽",pinyin:"zuó",meaning:"相互揪扯、扭打。"},{id:"lyk2-zishi",term:"自是",pinyin:"",meaning:"自以为是、自认正确。“自是有德者以不知也”的具体句法有解释差异。"},{id:"lyk2-buzhi",term:"不知",pinyin:"",meaning:"不明白、缺乏真正认识；不直接等同于第一份的“无能”。"},{id:"lyk2-duntian",term:"遁天",pinyin:"",meaning:"逃离、背离天然所受及其根据。"},{id:"lyk2-xing",term:"刑",pinyin:"",meaning:"刑罚、伤害；此处不必限于国家施加的刑罚。"},{id:"lyk2-an",term:"安",pinyin:"",meaning:"安处、以之为安、安于其中，不只是没有动作；“所安”的具体对象须结合语境讨论。"},{id:"lyk3-zhidao",term:"知道",pinyin:"",meaning:"知道、认识道，不是现代口语泛指知道一件事情。"},{id:"lyk3-wuyan",term:"勿言",pinyin:"",meaning:"不言说、不急于把所知说出。"},{id:"lyk3-zhitian",term:"所以之天",pinyin:"",meaning:"由此趋向天、天然。“之”联系往、至理解。"},{id:"lyk3-zhiren",term:"所以之人",pinyin:"",meaning:"由此趋向人为、人的言说与经营。"},{id:"lyk3-tianburen",term:"天而不人",pinyin:"",meaning:"取天然而不以人为经营为主；不宜直译成不是人。"},{id:"lyk3-zhupengman",term:"朱泙漫",pinyin:"泙：通常读 pēng",meaning:"故事中的学技者。"},{id:"lyk3-zhiliyi",term:"支离益",pinyin:"",meaning:"传授屠龙之技的人物。"},{id:"lyk3-dan",term:"单",pinyin:"",meaning:"耗尽、用尽，联系“殚”理解。"},{id:"lyk3-qianjin",term:"千金之家",pinyin:"",meaning:"价值千金的家产，突出学习付出的巨大代价。"},{id:"lyk3-wusuoyong",term:"无所用其巧",pinyin:"",meaning:"没有地方、对象可以使用所学技巧。"},{id:"lyk3-bibi",term:"必不必",pinyin:"",meaning:"必要、必然、认定非如此不可，与不必如此相对；“以必不必”的具体训释有差异。"},{id:"lyk3-bing",term:"兵",pinyin:"",meaning:"本有兵器、争战等义；此处也有联系争竞、对抗的手段或心态理解的读法。"},{id:"lyk3-shunbing",term:"顺于兵",pinyin:"",meaning:"顺从、随顺于兵或争竞；不未经说明理解成赞许使用兵器。"},{id:"lyk3-youqiu",term:"行有求",pinyin:"",meaning:"行动有所求取、追逐。"},{id:"lyk3-shi",term:"恃",pinyin:"shì",meaning:"倚赖、以之为凭据。"},{id:"lyk3-xiaofu",term:"小夫之知",pinyin:"",meaning:"见识狭小者的知识、智虑；“小夫”不只按社会地位理解。"},{id:"lyk3-baoju",term:"苞苴",pinyin:"bāo jū",meaning:"包裹、馈赠物；语境中可涉及馈赠交际及其利害经营。"},{id:"lyk3-gandu",term:"竿牍",pinyin:"gān dú",meaning:"书简、书札，联系往来文书理解。"},{id:"lyk3-bijing",term:"敝精神",pinyin:"",meaning:"耗损、困疲精神。"},{id:"lyk3-jianqian",term:"蹇浅",pinyin:"jiǎn qiǎn",meaning:"局促、浅陋、狭小。"},{id:"lyk3-jianji",term:"兼济道物",pinyin:"",meaning:"广泛通达、济理道与物等；“济”的具体侧重有解释空间。"},{id:"lyk3-taiyi",term:"太一形虚",pinyin:"",meaning:"涉及太一、形与虚的疑难语句；通常联系广大根本或虚寂境界理解，不强定唯一句法。"},{id:"lyk3-xinglei",term:"形累",pinyin:"",meaning:"为形体及形迹等所牵累；具体范围须结合训释。"},{id:"lyk3-taichu",term:"太初",pinyin:"",meaning:"原初、根本的起始，不必限定为可计算的时间点。"},{id:"lyk3-wushi",term:"无始",pinyin:"",meaning:"无可限定的起始、超出特定起点的根本境域。"},{id:"lyk3-ganming",term:"甘冥",pinyin:"",meaning:"安然、甘于幽深冥寂，不是苦于昏暗。"},{id:"lyk3-wuheyou",term:"无何有之乡",pinyin:"",meaning:"无可具体指认、无所执有的境域，是庄子式表达，不是实际地址。"},{id:"lyk3-shuiliu",term:"水流乎无形，发泄乎太清",pinyin:"",meaning:"以水流、流注呈现不固守形状与清虚舒展；具体主语与句法有解释空间。"},{id:"lyk3-haomao",term:"毫毛",pinyin:"",meaning:"极细微之物，比拟狭小、枝末的范围。"},{id:"lyk3-daning",term:"大宁",pinyin:"",meaning:"广大的安宁、生命与精神的安顿，不只是暂时安静。"},{id:"lyk4-caoshang",term:"曹商",pinyin:"",meaning:"宋人，故事中的出使者。"},{id:"lyk4-shiqin",term:"为宋王使秦",pinyin:"",meaning:"替宋王出使秦国。"},{id:"lyk4-shucheng",term:"得车数乘",pinyin:"乘：shèng",meaning:"得到数辆车；结合出使语境，可理解为获得出行所用之车。"},{id:"lyk4-yuezhi",term:"王说之",pinyin:"说：yuè",meaning:"秦王喜欢、赏识他。"},{id:"lyk4-yiche",term:"益车百乘",pinyin:"",meaning:"又增加百乘之车，突出赏赐丰厚。"},{id:"lyk4-fan",term:"反于宋",pinyin:"",meaning:"返回宋国。“反”通“返”。"},{id:"lyk4-qionglu",term:"穷闾厄巷",pinyin:"",meaning:"贫困、偏僻狭窄的里巷。“闾”为里巷。"},{id:"lyk4-kunjiong",term:"困窘",pinyin:"kùn jiǒng",meaning:"生活困顿、贫乏。"},{id:"lyk4-zhiju",term:"织屦",pinyin:"zhī jù",meaning:"编织鞋履，语境中指以此谋生。"},{id:"lyk4-gaoxiang",term:"槁项",pinyin:"gǎo xiàng",meaning:"颈项枯瘦，形容困顿憔悴。"},{id:"lyk4-huangguo",term:"黄馘",pinyin:"huáng guó",meaning:"面色枯黄。“馘”在此通常联系面部理解，不按割耳记功义解释。"},{id:"lyk4-suoduan",term:"所短",pinyin:"",meaning:"不擅长之处；此处借自述长短，带出对庄子处境的贬低。"},{id:"lyk4-yiwu",term:"一悟",pinyin:"",meaning:"一次便使君主领悟、悦服；“悟”的具体侧重有解释空间。"},{id:"lyk4-wansheng",term:"万乘之主",pinyin:"wàn shèng",meaning:"大国君主，突出政治权势。"},{id:"lyk4-congche",term:"从车百乘",pinyin:"",meaning:"有百乘之车随从，或获得百乘车辆相随的排场。"},{id:"lyk4-suochang",term:"所长",pinyin:"",meaning:"擅长之处。"},{id:"lyk4-poyong",term:"破痈溃痤",pinyin:"痈：yōng；痤：cuó",meaning:"使痈疮、小肿疮等破溃，进行相应治疗；古代病名不强与现代医学一一对应。"},{id:"lyk4-shizhi",term:"舐痔",pinyin:"shì zhì",meaning:"用舌头舔痔疾所在之处；在本段中构成带有羞辱意味的极端譬喻。"},{id:"lyk4-yuxia",term:"所治愈下",pinyin:"",meaning:"所治疗的部位越向下；在整个反讽语境中，又带出行为愈卑下的意味。"},{id:"lyk4-ziqi",term:"子岂治其痔邪",pinyin:"",meaning:"你莫非……吗？反问语气，不直接构成对实际行为的确认。"},{id:"lyk4-zixing",term:"子行矣",pinyin:"",meaning:"你走吧。逐客，结束交谈。"},{id:"lyk5-aigong",term:"鲁哀公",pinyin:"",meaning:"鲁国君主。"},{id:"lyk5-yanhe",term:"颜阖",pinyin:"yán hé",meaning:"本段中的答问者，不是颜回。"},{id:"lyk5-zhongni",term:"仲尼",pinyin:"",meaning:"孔子的字。"},{id:"lyk5-zhengan",term:"贞幹",pinyin:"",meaning:"正干、主干，联系治国的支柱、骨干理解。"},{id:"lyk5-chou",term:"瘳",pinyin:"chōu",meaning:"病愈；此处以治病比拟国家弊病有所改善。"},{id:"lyk5-daiji",term:"殆哉圾乎",pinyin:"殆：dài",meaning:"发出危险的警告。“圾”为疑难用字，通常联系危殆、岌岌的语势理解。"},{id:"lyk5-shiyu",term:"饰羽而画",pinyin:"",meaning:"装饰羽毛、加以绘饰，形容重于外在修饰。"},{id:"lyk5-huaci",term:"华辞",pinyin:"",meaning:"华美的言辞。"},{id:"lyk5-zhizhi",term:"以支为旨",pinyin:"",meaning:"常联系把枝节当作主旨、根本理解；具体字义有差异。"},{id:"lyk5-renxing",term:"忍性",pinyin:"",meaning:"克制、压抑本性；本段语境中带有使本性受损的批评意味，不等于所有必要的自我克制。"},{id:"lyk5-shimin",term:"视民",pinyin:"",meaning:"常联系示范、教示百姓理解，“视”与“示”相关。"},{id:"lyk5-buzhibuxin",term:"而不知不信",pinyin:"",meaning:"疑难语句，“而”的联系及“知”“信”的具体所指存在解释空间，不在此强定逐字译法。"},{id:"lyk5-xinshen",term:"受乎心，宰乎神",pinyin:"",meaning:"通常联系受心智支配、使精神受制理解，具体句法有解释空间。"},{id:"lyk5-shangmin",term:"上民",pinyin:"",meaning:"居于民上、领导治理百姓。"},{id:"lyk5-ru",term:"女",pinyin:"rǔ",meaning:"通“汝”，你。"},{id:"lyk5-lishi",term:"离实学伪",pinyin:"",meaning:"离开真实，学习人为造作的表现；“伪”不只指蓄意撒谎。"},{id:"lyk5-xiuzhi",term:"休之",pinyin:"",meaning:"停止这一做法、用人安排，不直接扩大为取消一切治理。"},{id:"lyk5-shiyu-b",term:"施于人而不忘",pinyin:"",meaning:"施惠后仍记取所施之惠；结合语境，重点在执功、计报，不是只要有记忆便失德。"},{id:"lyk5-tianbu",term:"天布",pinyin:"",meaning:"如天、自然般的布施，不以人为记功与索报为重。"},{id:"lyk5-shanggu",term:"商贾",pinyin:"shāng gǔ",meaning:"商人。"},{id:"lyk5-chi",term:"齿",pinyin:"",meaning:"列入、并列、认可；“不齿”为不愿列入同类、看不起。"},{id:"lyk5-shichi",term:"以事齿之",pinyin:"",meaning:"从事务、办事的层面加以认可、列入。"},{id:"lyk5-shenzhe",term:"神者",pinyin:"",meaning:"通常联系精神修养深妙者或神妙的层面理解，不必解作神灵。"},{id:"lyk5-jinmu",term:"金与木",pinyin:"",meaning:"金属、木制的刑具或刑罚工具。"},{id:"lyk5-dongguo",term:"动与过",pinyin:"",meaning:"行动、心神活动与过失、过度；具体范围有训释差异。"},{id:"lyk5-xiaoren",term:"宵人",pinyin:"",meaning:"小人、见识或修养不足者。"},{id:"lyk5-li",term:"离",pinyin:"",meaning:"通“罹”，遭受。"},{id:"lyk5-xun",term:"讯",pinyin:"",meaning:"拷问、刑讯。"},{id:"lyk5-yinyang",term:"阴阳食之",pinyin:"",meaning:"以阴阳变化侵蚀、耗损生命作说明，不直接对应某一种现代疾病或病因。"},{id:"lyk5-zhenren",term:"真人",pinyin:"",meaning:"与真相应、修养达到高度的人，是本段的理想参照；不构成现实中绝不会受害的保证。"},{id:"lyk6-xian",term:"险于山川",pinyin:"",meaning:"比山川更难测度；“险”兼有不可轻易把握的意味。"},{id:"lyk6-zhitian",term:"难于知天",pinyin:"",meaning:"比认识天时、天象更难。"},{id:"lyk6-qi",term:"期",pinyin:"",meaning:"有规律的时序、周期。"},{id:"lyk6-houmao",term:"厚貌深情",pinyin:"",meaning:"外貌有遮蔽，内情深藏；“情”主要指内在实情，不只指情感。"},{id:"lyk6-maoyuan",term:"貌愿",pinyin:"",meaning:"外貌显得谨厚、诚实。"},{id:"lyk6-yi",term:"益",pinyin:"",meaning:"此处常联系骄溢理解，不按现代“有益”解释。"},{id:"lyk6-chang",term:"长",pinyin:"",meaning:"常联系长者、长厚者理解，具体句法有差异。"},{id:"lyk6-shunxuan",term:"顺懁而达",pinyin:"",meaning:"疑难对照语，涉及外在表现与内情不一致，不强作唯一译解。"},{id:"lyk6-jianman",term:"坚而缦",pinyin:"",meaning:"常联系外表坚实、内里松缓的对照理解。"},{id:"lyk6-huanhan",term:"缓而釬",pinyin:"",meaning:"常联系外表舒缓、内里急躁或刚急的对照理解。"},{id:"lyk6-jiuyi",term:"就义",pinyin:"",meaning:"趋向、接近合宜或义的行为。"},{id:"lyk6-quyi",term:"去义",pinyin:"",meaning:"离开、背离义。"},{id:"lyk6-ruosike-a",term:"若渴",pinyin:"ruò kě",meaning:"如渴求饮，形容急于赴义。「其就义若渴者，其去义若热」。"},{id:"lyk6-ruosike-b",term:"若热",pinyin:"ruò rè",meaning:"如避热，形容急于离义。与「若渴」对举，写去就之急。"},{id:"lyk6-yuanjin-a",term:"远使之",pinyin:"yuǎn shǐ zhī",meaning:"派到远处任职，以观其是否尽忠。"},{id:"lyk6-yuanjin-b",term:"近使之",pinyin:"jìn shǐ zhī",meaning:"留在近处任用，以观其是否恭敬。"},{id:"lyk6-fanshi",term:"烦使",pinyin:"",meaning:"交付繁杂事务。"},{id:"lyk6-curan",term:"卒然",pinyin:"cù rán",meaning:"突然。“卒”通“猝”。"},{id:"lyk6-zhi",term:"知",pinyin:"zhì",meaning:"智识、应对与辨别能力。"},{id:"lyk6-jiqi",term:"急与之期",pinyin:"",meaning:"与之约定紧迫的期限。"},{id:"lyk6-weicai",term:"委之以财",pinyin:"",meaning:"将财物交付其管理、处置。"},{id:"lyk6-jie",term:"节",pinyin:"",meaning:"操守、在危难中的坚持。"},{id:"lyk6-ze",term:"则",pinyin:"",meaning:"法度、行为的分寸。"},{id:"lyk6-zachu",term:"杂之以处",pinyin:"",meaning:"使其处于混杂的交往环境；具体场景有不同解释。"},{id:"lyk6-se",term:"色",pinyin:"",meaning:"神色、表现，也有联系对色欲的态度理解的读法。"},{id:"lyk6-jiuzheng",term:"九徵",pinyin:"",meaning:"九种征验、观察方式。"},{id:"lyk6-de",term:"不肖人得矣",pinyin:"",meaning:"不贤者的实情可以被察知；“得”不是获得人才之意。"},{id:"lyk6-zhengkaofu",term:"正考父",pinyin:"",meaning:"宋国人物，传统记载中以谦恭著称。"},{id:"lyk6-ming-a",term:"一命",pinyin:"yī mìng",meaning:"第一次受命。「一命而伛」，与再命、三命并举，写位愈高而身愈下。"},{id:"lyk6-ming-b",term:"再命",pinyin:"zài mìng",meaning:"第二次受命。「再命而偻」。"},{id:"lyk6-ming-c",term:"三命",pinyin:"sān mìng",meaning:"第三次受命。「三命而俯」，姿态愈来愈低。"},{id:"lyk6-yulvfu-a",term:"伛",pinyin:"yǔ",meaning:"弯背，表谦下。「一命而伛」。"},{id:"lyk6-yulvfu-b",term:"偻",pinyin:"lǚ",meaning:"曲身。「再命而偻」。"},{id:"lyk6-yulvfu-c",term:"俯",pinyin:"fǔ",meaning:"低头俯身。「三命而俯」，一命至三命姿态递降。"},{id:"lyk6-xunqiang",term:"循墙而走",pinyin:"",meaning:"沿墙而行，突出谦退、不居显处。"},{id:"lyk6-gui",term:"轨",pinyin:"",meaning:"法度、合宜的规范。"},{id:"lyk6-rufu",term:"如而夫者",pinyin:"",meaning:"像那种人、像一般凡夫那样；“而”可联系“尔”理解。"},{id:"lyk6-lvju",term:"吕钜",pinyin:"",meaning:"常联系骄张、自大之态理解，用字与训释较为疑难。"},{id:"lyk6-mingzhufu",term:"名诸父",pinyin:"",meaning:"直呼父辈、叔伯之名，表现失去敬重。"},{id:"lyk6-tangxu",term:"唐、许",pinyin:"",meaning:"通常指唐尧与许由，作为古代理想人物参照。"},{id:"lyk6-zei",term:"贼",pinyin:"",meaning:"伤害、祸害。"},{id:"lyk6-deyouxin",term:"德有心",pinyin:"",meaning:"在德行上有所计较与自我标举，不宜理解为有意识地行善皆错。"},{id:"lyk6-xinjie",term:"心有睫",pinyin:"",meaning:"以心有眼睫作譬喻，联系自我观看；所提供材料亦提示另有作“眼”的版本，本次未作版本对勘。"},{id:"lyk6-neishi",term:"内视",pinyin:"",meaning:"结合下文，联系回看并自赏自身之德，不泛指所有内省。"},{id:"lyk6-zhongde",term:"中德",pinyin:"",meaning:"疑难术语，下文以自好并贬斥他人说明；不按现代“中等品德”或折中之德理解。"},{id:"lyk6-zihao",term:"自好",pinyin:"",meaning:"自爱、自赏；此处着重自满于己之所长。"},{id:"lyk6-pi",term:"吡",pinyin:"",meaning:"诋毁、贬斥；此处不强定读音。"},{id:"lyk6-suobuwei",term:"其所不为者",pinyin:"",meaning:"自己不做、不采取的行为或做法。"},{id:"lyk7-baji",term:"八极",pinyin:"",meaning:"八种达到突出、过人程度的条件。"},{id:"lyk7-sanbi",term:"三必",pinyin:"",meaning:"下文列出的三类状态；“必”的具体意味须结合句义理解。"},{id:"lyk7-liufu",term:"形有六府",pinyin:"",meaning:"涉及形体与六府的简短语句；六府通常联系身体脏腑理解，与前句关系有解释空间。"},{id:"lyk7-meiran",term:"美、髯",pinyin:"",meaning:"容貌美好、须髯出众等。"},{id:"lyk7-changda",term:"长、大、壮、丽",pinyin:"",meaning:"身形高长、魁大、强壮、仪容显著等，彼此的具体区分不强定。"},{id:"lyk7-yonggan",term:"勇、敢",pinyin:"",meaning:"勇力、敢于行动。"},{id:"lyk7-guoren",term:"八者俱过人",pinyin:"",meaning:"所列条件超过常人，却反而因此受困；不据此建立所有出众者必然受困的定律。"},{id:"lyk7-yuanxun",term:"缘循",pinyin:"",meaning:"常联系随顺、循物而行理解。"},{id:"lyk7-yanyang",term:"偃佒",pinyin:"",meaning:"常联系舒缓、不矜张的状态理解，用字与训释有疑难，不强定读音。"},{id:"lyk7-kunwei",term:"困畏不若人",pinyin:"",meaning:"常联系困弱、畏慎、不争先于人理解；具体句读与义界有解释空间。"},{id:"lyk7-zhihui",term:"知慧",pinyin:"",meaning:"智慧、智识。"},{id:"lyk7-waitong",term:"外通",pinyin:"",meaning:"向外通达、发挥作用，不只按现代社交能力理解。"},{id:"lyk7-yuanze",term:"勇动多怨，仁义多责",pinyin:"",meaning:"凭勇行动可能招致怨尤，仁义可能伴随要求、责求或责任；具体侧重有解释差异。"},{id:"lyk7-dasheng",term:"达生之情",pinyin:"",meaning:"通达生命的实际情状，与只在智识上通达作对照。"},{id:"lyk7-guixiao-a",term:"傀",pinyin:"guī",meaning:"有解释为「大」「伟」，与「肖」对举；训释有异，不作定论。"},{id:"lyk7-guixiao-b",term:"肖",pinyin:"xiào",meaning:"有解释为「小」「相似」，与「傀」对举。"},{id:"lyk7-daxiaoming-a",term:"大命",pinyin:"dà mìng",meaning:"与「小命」对举，指根本的、大的命分或趋势。"},{id:"lyk7-daxiaoming-b",term:"小命",pinyin:"xiǎo mìng",meaning:"与「大命」对举，指具体的、局部的遭际。"},{id:"lyk7-suizao-a",term:"随",pinyin:"suí",meaning:"随顺。「达大命者随」，与「遭」对举。"},{id:"lyk7-suizao-b",term:"遭",pinyin:"zāo",meaning:"遭逢。「达小命者遭」，随与遭各有所指。"},{id:"lyk7-xi",term:"锡",pinyin:"cì",meaning:"通“赐”，赏赐。"},{id:"lyk7-shicheng",term:"十乘",pinyin:"乘：shèng",meaning:"十辆车。"},{id:"lyk7-jiaozhi",term:"骄稚",pinyin:"",meaning:"骄傲地轻视；“稚”常联系视对方如幼稚者理解。"},{id:"lyk7-weixiao",term:"纬萧",pinyin:"",meaning:"编织蒿草一类材料，常解释为制作草帘等以谋生。"},{id:"lyk7-moyuyuan",term:"没于渊",pinyin:"没：mò",meaning:"潜入深水。"},{id:"lyk7-qianjinzhu",term:"千金之珠",pinyin:"",meaning:"极珍贵的珠子，“千金”突出价值。"},{id:"lyk7-duanzhi",term:"锻之",pinyin:"",meaning:"用石击碎它，不按现代金属锻造义理解。"},{id:"lyk7-jiuzhong",term:"九重之渊",pinyin:"",meaning:"极深的水渊，不必理解为可实测的九层。"},{id:"lyk7-lilong",term:"骊龙",pinyin:"lí lóng",meaning:"黑龙，故事中守有珍珠的危险存在。"},{id:"lyk7-hanxia",term:"颔下",pinyin:"颔：hàn",meaning:"下颌、下巴下面。"},{id:"lyk7-wu",term:"寤",pinyin:"wù",meaning:"醒来；回指宋王时属于譬喻，不是睡眠中赐车的事实记录。"},{id:"lyk7-xiwei",term:"奚微之有",pinyin:"",meaning:"还能剩下什么细微之物？突出毁灭之彻底。"},{id:"lyk7-feizhi",term:"非直",pinyin:"",meaning:"不只是、不仅相当于。"},{id:"lyk7-jifen",term:"齑粉",pinyin:"jī fěn",meaning:"碎末、粉末，比喻被彻底毁灭。"},{id:"lyk7-fu",term:"夫",pinyin:"",meaning:"句末语气词。"},{id:"lyk8-huo",term:"或",pinyin:"",meaning:"有人、某人；本段没有交代姓名与国别。"},{id:"lyk8-pin",term:"聘",pinyin:"pìn",meaning:"以礼征聘、延请；结合譬喻可联系政治任用理解。"},{id:"lyk8-yingshi",term:"应其使",pinyin:"",meaning:"回答聘请者派来的使者。"},{id:"lyk8-xiniu",term:"牺牛",pinyin:"xī niú",meaning:"用作祭祀牺牲的牛，不只是一般受重视的动物。"},{id:"lyk8-wenxiu",term:"衣以文绣",pinyin:"衣：yì",meaning:"给它披上有纹饰的绣衣，“衣”作动词。"},{id:"lyk8-chushu",term:"食以刍菽",pinyin:"食：sì；刍菽：chú shū",meaning:"用草料、豆类饲养它；所提供材料提示另有“刍叔”的写法，本次未作版本对勘。"},{id:"lyk8-qian",term:"牵",pinyin:"",meaning:"被牵引、带往某处，突出去向由他者安排。"},{id:"lyk8-damiao",term:"大庙",pinyin:"",meaning:"通常联系太庙理解，祭祀祖先的重要庙宇。"},{id:"lyk8-gudu",term:"孤犊",pinyin:"gū dú",meaning:"孤单的小牛；对照中指未被选作祭祀牺牲的普通小牛，不保证完全没有危险与依赖。"},{id:"lyk8-kede",term:"其可得乎",pinyin:"",meaning:"难道还能获得那种处境吗？强调此时退出或恢复原状可能已不可得。"},{id:"lyk9-jiangsi",term:"将死",pinyin:"",meaning:"即将死亡，交代对话的处境。"},{id:"lyk9-houzang",term:"厚葬",pinyin:"",meaning:"以丰厚、隆重的葬具与安排下葬，不只指棺木较厚。"},{id:"lyk9-guanguo",term:"棺椁",pinyin:"guān guǒ",meaning:"棺与棺外的套棺，合指葬具。"},{id:"lyk9-lianbi",term:"连璧",pinyin:"lián bì",meaning:"相连、成对的玉璧；此处以日月比拟贵重葬物。"},{id:"lyk9-zhuji",term:"珠玑",pinyin:"zhū jī",meaning:"珍珠与珠类饰物，泛指珍贵珠玉。"},{id:"lyk9-jisong",term:"赍送",pinyin:"jī sòng",meaning:"送葬所用、随葬的资物，具体范围有解释差异。"},{id:"lyk9-zangju",term:"葬具",pinyin:"",meaning:"丧葬所需的器物、安排。"},{id:"lyk9-bei",term:"备",pinyin:"",meaning:"完备、齐全。"},{id:"lyk9-jiaci",term:"何以加此",pinyin:"",meaning:"还要用什么增加于此？反问增益的必要。"},{id:"lyk9-wuyuan",term:"乌鸢",pinyin:"wū yuān",meaning:"乌鸦与鸢等鸟类，语境中指可能取食遗体的鸟。"},{id:"lyk9-fuzi",term:"夫子",pinyin:"",meaning:"弟子对老师的尊称。"},{id:"lyk9-shangxia-a",term:"在上",pinyin:"zài shàng",meaning:"在高处。「在上为乌鸢食」，与「在下」并举。"},{id:"lyk9-shangxia-b",term:"在下",pinyin:"zài xià",meaning:"在低处。「在下为蝼蚁食」，写葬与不葬都归自然。"},{id:"lyk9-louyi",term:"蝼蚁",pinyin:"lóu yǐ",meaning:"蝼蛄与蚂蚁等小虫，泛指地下可能取食遗体的虫类。"},{id:"lyk9-duobiyuci",term:"夺彼与此",pinyin:"",meaning:"从那一方夺去，给这一方；“与”作给予义。"},{id:"lyk9-pian",term:"偏",pinyin:"",meaning:"偏向、厚此薄彼；针对这里的判断，不扩大为取消一切感情与选择。"},{id:"lyk10-buping",term:"以不平平，其平也不平",pinyin:"",meaning:"用不平正的东西衡量、平正他物，所得仍不平正；也有联系不平之心理解的读法。"},{id:"lyk10-buzheng",term:"以不徵徵，其徵也不徵",pinyin:"",meaning:"以不能作可靠凭据的东西征验，所得仍不足为可靠征验；“徵”有简化文本写作“征”。"},{id:"lyk10-ming",term:"明",pinyin:"",meaning:"明察、辨识的能力，本段常联系有所分别的智识理解。"},{id:"lyk10-shi",term:"使",pinyin:"",meaning:"役使、使者；涉及作为工具、受其驱使的关系，具体所指有解释差异。"},{id:"lyk10-shen",term:"神",pinyin:"",meaning:"神妙、不局限于显见分别的通达，不必解释为人格神灵。"},{id:"lyk10-busheng",term:"不胜",pinyin:"",meaning:"不能胜过、不及。"},{id:"lyk10-shijian",term:"恃其所见",pinyin:"",meaning:"倚赖自己的认识，将其作为足够的凭据；“所见”不只指眼睛看见的东西。"},{id:"lyk10-ruren",term:"入于人",pinyin:"",meaning:"将自己的所见推入他人、用来干预或要求他人等，不按身体进入理解。"},{id:"lyk10-gongwai",term:"其功外也",pinyin:"",meaning:"功用、用力偏向外部；常联系向外施用而未返诸自身理解，具体训释有差异。"},{id:"lyk10-bei",term:"悲",pinyin:"",meaning:"对这种失当状态的感叹，不只是个人情绪低落。"}],k=[{id:"lyk-p1-01",label:"中道惊返",sentences:[[{text:"列御寇",glossary:"lyk1-lieyukou"},{text:"之齐",glossary:"lyk1-zhiqi"},"，中道而",{text:"反",glossary:"lyk1-fan"},"，遇",{text:"伯昏瞀人",glossary:"lyk1-bohun"},"。"],["伯昏瞀人曰：“",{text:"奚方而反",glossary:"lyk1-xifang"},"？”曰：“吾惊焉。”曰：“",{text:"恶乎惊",glossary:"lyk1-wuhu"},"？”"],["曰：“吾尝食于",{text:"十浆",glossary:"lyk1-shijiang-a"},"而",{text:"五浆",glossary:"lyk1-shijiang-b"},{text:"先馈",glossary:"lyk1-xiankui"},"。”伯昏瞀人曰：“若是则汝何为惊已？”"]]},{id:"lyk-p1-02",label:"内诚与显露",sentences:[["曰：“夫",{text:"内诚不解",glossary:"lyk1-neicheng"},"，",{text:"形谍成光",glossary:"lyk1-xingdie"},"，以外",{text:"镇人心",glossary:"lyk1-zhen"},"，使人轻乎",{text:"贵老",glossary:"lyk1-guilao"},"，而",{text:"赍其所患",glossary:"lyk1-ji"},"。"]]},{id:"lyk-p1-03",label:"由浆人到君主",sentences:[["夫浆人",{text:"特",glossary:"lyk1-te"},"为",{text:"食羹之货",glossary:"lyk1-shigeng"},"，无多余之",{text:"赢",glossary:"lyk1-ying"},"，其为利也薄，其为权也轻，而犹若是，而况于",{text:"万乘之主",glossary:"lyk1-wansheng"},"乎！"],["身劳于国而",{text:"知尽于事",glossary:"lyk1-zhijin"},"。彼将任我以事，而",{text:"效我以功",glossary:"lyk1-xiaogong"},"。吾是以惊。”"]]},{id:"lyk-p1-04",label:"肯定与预言",sentences:[["伯昏瞀人曰：“善哉观乎！",{text:"女",glossary:"lyk1-ru"},{text:"处已",glossary:"lyk1-chuyi"},"，人将",{text:"保汝",glossary:"lyk1-baoru"},"矣！”"],[{text:"无几何",glossary:"lyk1-wujihe"},"而往，则户外之",{text:"屦",glossary:"lyk1-ju"},"满矣。"]]},{id:"lyk-p1-05",label:"无言而出",sentences:[["伯昏瞀人",{text:"北面而立",glossary:"lyk1-beimian"},"，",{text:"敦杖蹙之乎颐",glossary:"lyk1-dunzhang"},"。立",{text:"有间",glossary:"lyk1-youjian"},"，不言而出。"],[{text:"宾者",glossary:"lyk1-binzhe"},"以告列子，列子提屦，",{text:"跣",glossary:"lyk1-xian"},"而走，",{text:"暨",glossary:"lyk1-jiyu"},"于门，曰：“先生既来，",{text:"曾不",glossary:"lyk1-zengbu"},{text:"发药",glossary:"lyk1-fayao"},"乎？”"]]},{id:"lyk-p1-06",label:"依附与招引",sentences:[["曰：“已矣，吾固告汝曰：人将",{text:"保汝",glossary:"lyk1-baoru"},"。果保汝矣！"],["非汝能使人保汝，而汝不能使人无保汝也，而焉用之",{text:"感豫出异",glossary:"lyk1-ganyu"},"也。"],["必且有感，",{text:"摇而本性",glossary:"lyk1-yao"},"，又",{text:"无谓",glossary:"lyk1-wuwei"},"也。"]]},{id:"lyk-p1-07",label:"交游能否纠偏",sentences:[["与汝游者，又莫汝告也。彼所小言，",{text:"尽人毒",glossary:"lyk1-jinrendu"},"也。莫觉莫悟，",{text:"何相孰也",glossary:"lyk1-xiangshu"},"。"]]},{id:"lyk-p1-08",label:"不系之舟",sentences:[[{text:"巧者",glossary:"lyk1-qiaozhi-a"},"劳而",{text:"知者",glossary:"lyk1-qiaozhi-b"},"忧，",{text:"无能者",glossary:"lyk1-wuneng"},"无所求，饱食而",{text:"敖游",glossary:"lyk1-aoyou"},"，",{text:"汎",glossary:"lyk1-fanfu"},"若",{text:"不系之舟",glossary:"lyk1-buxizhou"},"，",{text:"虚",glossary:"lyk1-xu"},"而敖游者也！”"]]},{id:"lyk-p2-01",label:"学习与身份",sentences:[["郑人",{text:"缓",glossary:"lyk2-huan"},"也，",{text:"呻吟",glossary:"lyk2-shenyin"},{text:"裘氏之地",glossary:"lyk2-qiushi"},"。",{text:"祗三年",glossary:"lyk2-zhisan"},"而缓",{text:"为儒",glossary:"lyk2-weiru"},"。"],[{text:"河润九里",glossary:"lyk2-herun"},"，",{text:"泽及三族",glossary:"lyk2-sanzu"},"，",{text:"使其弟墨",glossary:"lyk2-dimo"},"。"]]},{id:"lyk-p2-02",label:"争辩与死亡",sentences:[[{text:"儒墨",glossary:"lyk2-rumo"},"相与辩，其父",{text:"助翟",glossary:"lyk2-zhudi"},"。",{text:"十年",glossary:"lyk2-shinian"},"而缓自杀。"]]},{id:"lyk-p2-03",label:"梦中之言",sentences:[[{text:"其父梦之",glossary:"lyk2-mengzhi"},"曰：“使",{text:"而子",glossary:"lyk2-erzi"},"为墨者，",{text:"予",glossary:"lyk2-yu"},"也，",{text:"阖尝",glossary:"lyk2-hechang"},"视其",{text:"良",glossary:"lyk2-liang"},"？既为",{text:"秋柏之实",glossary:"lyk2-qiubai"},"矣。”"]]},{id:"lyk-p2-04",label:"造物与人之天",sentences:[["夫",{text:"造物者",glossary:"lyk2-zaowu"},"之",{text:"报人",glossary:"lyk2-baoren"},"也，不报其人而报其",{text:"人之天",glossary:"lyk2-renzhitian"},"，",{text:"彼故使彼",glossary:"lyk2-bigu"},"。"]]},{id:"lyk-p2-05",label:"自异与轻亲",sentences:[["夫人以己为",{text:"有以异于人",glossary:"lyk2-yiyuren"},"，以",{text:"贱其亲",glossary:"lyk2-jianqin"},"。"],["齐人之",{text:"井饮者",glossary:"lyk2-jingyin"},{text:"相捽",glossary:"lyk2-xiangzuo"},"也。故曰：今之世皆缓也。"]]},{id:"lyk-p2-06",label:"自是与遁天",sentences:[[{text:"自是",glossary:"lyk2-zishi"},"有德者以",{text:"不知",glossary:"lyk2-buzhi"},"也，而况有道者乎！古者谓之",{text:"遁天",glossary:"lyk2-duntian"},"之",{text:"刑",glossary:"lyk2-xing"},"。"]]},{id:"lyk-p2-07",label:"安处的交错",sentences:[["圣人",{text:"安",glossary:"lyk2-an"},"其所安，不安其所不安；众人安其所不安，不安其所安。"]]},{id:"lyk-p3-01",label:"知道与不言",sentences:[["庄子曰：“",{text:"知道",glossary:"lyk3-zhidao"},"易，",{text:"勿言",glossary:"lyk3-wuyan"},"难。"],["知而不言，",{text:"所以之天",glossary:"lyk3-zhitian"},"也。知而言之，",{text:"所以之人",glossary:"lyk3-zhiren"},"也。古之人，",{text:"天而不人",glossary:"lyk3-tianburen"},"。”"]]},{id:"lyk-p3-02",label:"屠龙技成",sentences:[[{text:"朱泙漫",glossary:"lyk3-zhupengman"},"学屠龙于",{text:"支离益",glossary:"lyk3-zhiliyi"},"，",{text:"单",glossary:"lyk3-dan"},{text:"千金之家",glossary:"lyk3-qianjin"},"，三年技成而",{text:"无所用其巧",glossary:"lyk3-wusuoyong"},"。"]]},{id:"lyk-p3-03",label:"必与不必",sentences:[["圣人以",{text:"必不必",glossary:"lyk3-bibi"},"，故无",{text:"兵",glossary:"lyk3-bing"},"；众人以不必必之，故多兵。"],[{text:"顺于兵",glossary:"lyk3-shunbing"},"，故",{text:"行有求",glossary:"lyk3-youqiu"},"。兵，",{text:"恃",glossary:"lyk3-shi"},"之则亡。"]]},{id:"lyk-p3-04",label:"小知与耗神",sentences:[[{text:"小夫之知",glossary:"lyk3-xiaofu"},"，不离",{text:"苞苴",glossary:"lyk3-baoju"},{text:"竿牍",glossary:"lyk3-gandu"},"，",{text:"敝精神",glossary:"lyk3-bijing"},"乎",{text:"蹇浅",glossary:"lyk3-jianqian"},"，而欲",{text:"兼济道物",glossary:"lyk3-jianji"},"，",{text:"太一形虚",glossary:"lyk3-taiyi"},"。"],["若是者，迷惑于宇宙，",{text:"形累",glossary:"lyk3-xinglei"},"不知",{text:"太初",glossary:"lyk3-taichu"},"。"]]},{id:"lyk-p3-05",label:"至人的精神归处",sentences:[["彼至人者，归精神乎",{text:"无始",glossary:"lyk3-wushi"},"，而",{text:"甘冥",glossary:"lyk3-ganming"},"乎",{text:"无何有之乡",glossary:"lyk3-wuheyou"},"。"],[{text:"水流乎无形，发泄乎太清",glossary:"lyk3-shuiliu"},"。"]]},{id:"lyk-p3-06",label:"毫毛与大宁",sentences:[["悲哉乎！汝为知在",{text:"毫毛",glossary:"lyk3-haomao"},"而不知",{text:"大宁",glossary:"lyk3-daning"},"。"]]},{id:"lyk-p4-01",label:"出使与厚赏",sentences:[["宋人有",{text:"曹商",glossary:"lyk4-caoshang"},"者，",{text:"为宋王使秦",glossary:"lyk4-shiqin"},"。其往也，",{text:"得车数乘",glossary:"lyk4-shucheng"},"。"],[{text:"王说之",glossary:"lyk4-yuezhi"},"，",{text:"益车百乘",glossary:"lyk4-yiche"},"。",{text:"反于宋",glossary:"lyk4-fan"},"，见庄子，曰："]]},{id:"lyk-p4-02",label:"以贫困为短",sentences:[["“夫处",{text:"穷闾厄巷",glossary:"lyk4-qionglu"},"，",{text:"困窘",glossary:"lyk4-kunjiong"},{text:"织屦",glossary:"lyk4-zhiju"},"，",{text:"槁项",glossary:"lyk4-gaoxiang"},{text:"黄馘",glossary:"lyk4-huangguo"},"者，商之",{text:"所短",glossary:"lyk4-suoduan"},"也；"]]},{id:"lyk-p4-03",label:"以君赏为长",sentences:[[{text:"一悟",glossary:"lyk4-yiwu"},{text:"万乘之主",glossary:"lyk4-wansheng"},"而",{text:"从车百乘",glossary:"lyk4-congche"},"者，商之",{text:"所长",glossary:"lyk4-suochang"},"也。”"]]},{id:"lyk-p4-04",label:"治病得车的反讽",sentences:[["庄子曰：“秦王有病召医。",{text:"破痈溃痤",glossary:"lyk4-poyong"},"者得车一乘，",{text:"舐痔",glossary:"lyk4-shizhi"},"者得车五乘，",{text:"所治愈下",glossary:"lyk4-yuxia"},"，得车愈多。"]]},{id:"lyk-p4-05",label:"反问与逐客",sentences:[[{text:"子岂治其痔邪",glossary:"lyk4-ziqi"},"？何得车之多也？",{text:"子行矣",glossary:"lyk4-zixing"},"！”"]]},{id:"lyk-p5-01",label:"治国支柱的设想",sentences:[[{text:"鲁哀公",glossary:"lyk5-aigong"},"问乎",{text:"颜阖",glossary:"lyk5-yanhe"},"曰：“吾以",{text:"仲尼",glossary:"lyk5-zhongni"},"为",{text:"贞幹",glossary:"lyk5-zhengan"},"，国其有",{text:"瘳",glossary:"lyk5-chou"},"乎？”"]]},{id:"lyk-p5-02",label:"修饰与华辞",sentences:[["曰：“",{text:"殆哉圾乎",glossary:"lyk5-daiji"},"！仲尼方且",{text:"饰羽而画",glossary:"lyk5-shiyu"},"，从事",{text:"华辞",glossary:"lyk5-huaci"},"。"],[{text:"以支为旨",glossary:"lyk5-zhizhi"},"，",{text:"忍性",glossary:"lyk5-renxing"},"以",{text:"视民",glossary:"lyk5-shimin"},"，",{text:"而不知不信",glossary:"lyk5-buzhibuxin"},"。"]]},{id:"lyk-p5-03",label:"心神受制与治理之问",sentences:[[{text:"受乎心，宰乎神",glossary:"lyk5-xinshen"},"，夫何足以",{text:"上民",glossary:"lyk5-shangmin"},"！"],["彼宜",{text:"女",glossary:"lyk5-ru"},"与予颐与，误而可矣！"]]},{id:"lyk-p5-04",label:"离实学伪与劝停",sentences:[["今使民",{text:"离实学伪",glossary:"lyk5-lishi"},"，非所以视民也。"],["为后世虑，不若",{text:"休之",glossary:"lyk5-xiuzhi"},"。难治也！”"]]},{id:"lyk-p5-05",label:"施惠与记功",sentences:[[{text:"施于人而不忘",glossary:"lyk5-shiyu-b"},"，非",{text:"天布",glossary:"lyk5-tianbu"},"也，",{text:"商贾",glossary:"lyk5-shanggu"},"不",{text:"齿",glossary:"lyk5-chi"},"。"],["虽",{text:"以事齿之",glossary:"lyk5-shichi"},"，",{text:"神者",glossary:"lyk5-shenzhe"},"弗齿。"]]},{id:"lyk-p5-06",label:"内外之刑",sentences:[["为外刑者，",{text:"金与木",glossary:"lyk5-jinmu"},"也；为内刑者，",{text:"动与过",glossary:"lyk5-dongguo"},"也。"],[{text:"宵人",glossary:"lyk5-xiaoren"},"之",{text:"离",glossary:"lyk5-li"},"外刑者，金木",{text:"讯",glossary:"lyk5-xun"},"之；离内刑者，",{text:"阴阳食之",glossary:"lyk5-yinyang"},"。"]]},{id:"lyk-p5-07",label:"真人的理想参照",sentences:[["夫免乎外内之刑者，唯",{text:"真人",glossary:"lyk5-zhenren"},"能之。"]]},{id:"lyk-p6-01",label:"人心与天时",sentences:[["孔子曰：“凡人心",{text:"险于山川",glossary:"lyk6-xian"},"，",{text:"难于知天",glossary:"lyk6-zhitian"},"。"],["天犹有春秋冬夏旦暮之",{text:"期",glossary:"lyk6-qi"},"，人者",{text:"厚貌深情",glossary:"lyk6-houmao"},"。"]]},{id:"lyk-p6-02",label:"外貌与内情",sentences:[["故有",{text:"貌愿",glossary:"lyk6-maoyuan"},"而",{text:"益",glossary:"lyk6-yi"},"，有",{text:"长",glossary:"lyk6-chang"},"若不肖，有",{text:"顺懁而达",glossary:"lyk6-shunxuan"},"，有",{text:"坚而缦",glossary:"lyk6-jianman"},"，有",{text:"缓而釬",glossary:"lyk6-huanhan"},"。"],["故其",{text:"就义",glossary:"lyk6-jiuyi"},{text:"若渴",glossary:"lyk6-ruosike-a"},"者，其",{text:"去义",glossary:"lyk6-quyi"},{text:"若热",glossary:"lyk6-ruosike-b"},"。"]]},{id:"lyk-p6-03",label:"远近与繁杂",sentences:[["故君子",{text:"远使之",glossary:"lyk6-yuanjin-a"},"而观其忠，",{text:"近使之",glossary:"lyk6-yuanjin-b"},"而观其敬，",{text:"烦使",glossary:"lyk6-fanshi"},"之而观其能，",{text:"卒然",glossary:"lyk6-curan"},"问焉而观其",{text:"知",glossary:"lyk6-zhi"},"。"]]},{id:"lyk-p6-04",label:"期限、财物与危难",sentences:[[{text:"急与之期",glossary:"lyk6-jiqi"},"而观其信，",{text:"委之以财",glossary:"lyk6-weicai"},"而观其仁，告之以危而观其",{text:"节",glossary:"lyk6-jie"},"。"]]},{id:"lyk-p6-05",label:"酒与杂处",sentences:[["醉之以酒而观其",{text:"则",glossary:"lyk6-ze"},"，",{text:"杂之以处",glossary:"lyk6-zachu"},"而观其",{text:"色",glossary:"lyk6-se"},"。"],[{text:"九徵",glossary:"lyk6-jiuzheng"},"至，",{text:"不肖人得矣",glossary:"lyk6-de"},"。”"]]},{id:"lyk-p6-06",label:"正考父受命谦退",sentences:[[{text:"正考父",glossary:"lyk6-zhengkaofu"},{text:"一命",glossary:"lyk6-ming-a"},"而",{text:"伛",glossary:"lyk6-yulvfu-a"},"，",{text:"再命",glossary:"lyk6-ming-b"},"而",{text:"偻",glossary:"lyk6-yulvfu-b"},"，",{text:"三命",glossary:"lyk6-ming-c"},"而",{text:"俯",glossary:"lyk6-yulvfu-c"},"，",{text:"循墙而走",glossary:"lyk6-xunqiang"},"，孰敢不",{text:"轨",glossary:"lyk6-gui"},"！"]]},{id:"lyk-p6-07",label:"受命而骄",sentences:[[{text:"如而夫者",glossary:"lyk6-rufu"},"，一命而",{text:"吕钜",glossary:"lyk6-lvju"},"，再命而于车上舞，三命而",{text:"名诸父",glossary:"lyk6-mingzhufu"},"，孰协",{text:"唐、许",glossary:"lyk6-tangxu"},"！"]]},{id:"lyk-p6-08",label:"德有心与内视",sentences:[[{text:"贼",glossary:"lyk6-zei"},"莫大乎",{text:"德有心",glossary:"lyk6-deyouxin"},"，而",{text:"心有睫",glossary:"lyk6-xinjie"},"，及其有睫也而",{text:"内视",glossary:"lyk6-neishi"},"，内视而败矣。"]]},{id:"lyk-p6-09",label:"自好与贬斥",sentences:[["凶德有五，",{text:"中德",glossary:"lyk6-zhongde"},"为首。何谓中德？"],["中德也者，有以",{text:"自好",glossary:"lyk6-zihao"},"也而",{text:"吡",glossary:"lyk6-pi"},{text:"其所不为者",glossary:"lyk6-suobuwei"},"也。"]]},{id:"lyk-p7-01",label:"八极与三必",sentences:[["穷有",{text:"八极",glossary:"lyk7-baji"},"，达有",{text:"三必",glossary:"lyk7-sanbi"},"，",{text:"形有六府",glossary:"lyk7-liufu"},"。"],[{text:"美、髯",glossary:"lyk7-meiran"},"、",{text:"长、大、壮、丽",glossary:"lyk7-changda"},"、",{text:"勇、敢",glossary:"lyk7-yonggan"},"，",{text:"八者俱过人",glossary:"lyk7-guoren"},"也，因以是穷。"],[{text:"缘循",glossary:"lyk7-yuanxun"},"、",{text:"偃佒",glossary:"lyk7-yanyang"},"、",{text:"困畏不若人",glossary:"lyk7-kunwei"},"，三者俱通达。"]]},{id:"lyk-p7-02",label:"智勇仁义与生知",sentences:[[{text:"知慧",glossary:"lyk7-zhihui"},{text:"外通",glossary:"lyk7-waitong"},"，",{text:"勇动多怨，仁义多责",glossary:"lyk7-yuanze"},"。"],[{text:"达生之情",glossary:"lyk7-dasheng"},"者",{text:"傀",glossary:"lyk7-guixiao-a"},"，达于知者",{text:"肖",glossary:"lyk7-guixiao-b"},"。"],["达",{text:"大命",glossary:"lyk7-daxiaoming-a"},"者",{text:"随",glossary:"lyk7-suizao-a"},"，达",{text:"小命",glossary:"lyk7-daxiaoming-b"},"者",{text:"遭",glossary:"lyk7-suizao-b"},"。"]]},{id:"lyk-p7-03",label:"得车自夸",sentences:[["人有见宋王者，",{text:"锡",glossary:"lyk7-xi"},"车",{text:"十乘",glossary:"lyk7-shicheng"},"，以其十乘",{text:"骄稚",glossary:"lyk7-jiaozhi"},"庄子。"]]},{id:"lyk-p7-04",label:"贫家得珠",sentences:[["庄子曰：“河上有家贫恃",{text:"纬萧",glossary:"lyk7-weixiao"},"而食者，其子",{text:"没于渊",glossary:"lyk7-moyuyuan"},"，得",{text:"千金之珠",glossary:"lyk7-qianjinzhu"},"。"]]},{id:"lyk-p7-05",label:"父亲警告",sentences:[["其父谓其子曰：‘取石来",{text:"锻之",glossary:"lyk7-duanzhi"},"！"],["夫千金之珠，必在",{text:"九重之渊",glossary:"lyk7-jiuzhong"},"而",{text:"骊龙",glossary:"lyk7-lilong"},{text:"颔下",glossary:"lyk7-hanxia"},"。"],["子能得珠者，必遭其睡也。使骊龙而",{text:"寤",glossary:"lyk7-wu"},"，子尚",{text:"奚微之有",glossary:"lyk7-xiwei"},"哉！’"]]},{id:"lyk-p7-06",label:"宋王与骊龙",sentences:[["今宋国之深，",{text:"非直",glossary:"lyk7-feizhi"},"九重之渊也；宋王之猛，非直骊龙也。"],["子能得车者，必遭其睡也；使宋王而寤，子为",{text:"齑粉",glossary:"lyk7-jifen"},{text:"夫",glossary:"lyk7-fu"},"！”"]]},{id:"lyk-p8-01",label:"聘请来到",sentences:[[{text:"或",glossary:"lyk8-huo"},{text:"聘",glossary:"lyk8-pin"},"于庄子。庄子",{text:"应其使",glossary:"lyk8-yingshi"},"曰：“子见夫",{text:"牺牛",glossary:"lyk8-xiniu"},"乎？"]]},{id:"lyk-p8-02",label:"装饰与供养",sentences:[[{text:"衣以文绣",glossary:"lyk8-wenxiu"},"，",{text:"食以刍菽",glossary:"lyk8-chushu"},"。"]]},{id:"lyk-p8-03",label:"去向与退出",sentences:[["及其",{text:"牵",glossary:"lyk8-qian"},"而入于",{text:"大庙",glossary:"lyk8-damiao"},"，虽欲为",{text:"孤犊",glossary:"lyk8-gudu"},"，",{text:"其可得乎",glossary:"lyk8-kede"},"！”"]]},{id:"lyk-p9-01",label:"弟子欲厚葬",sentences:[["庄子",{text:"将死",glossary:"lyk9-jiangsi"},"，弟子欲",{text:"厚葬",glossary:"lyk9-houzang"},"之。"]]},{id:"lyk-p9-02",label:"天地为葬具",sentences:[["庄子曰：“吾以天地为",{text:"棺椁",glossary:"lyk9-guanguo"},"，以日月为",{text:"连璧",glossary:"lyk9-lianbi"},"，星辰为",{text:"珠玑",glossary:"lyk9-zhuji"},"，万物为",{text:"赍送",glossary:"lyk9-jisong"},"。"],["吾",{text:"葬具",glossary:"lyk9-zangju"},"岂不",{text:"备",glossary:"lyk9-bei"},"邪？",{text:"何以加此",glossary:"lyk9-jiaci"},"！”"]]},{id:"lyk-p9-03",label:"弟子的担忧",sentences:[["弟子曰：“吾恐",{text:"乌鸢",glossary:"lyk9-wuyuan"},"之食",{text:"夫子",glossary:"lyk9-fuzi"},"也。”"]]},{id:"lyk-p9-04",label:"上下与偏向",sentences:[["庄子曰：“",{text:"在上",glossary:"lyk9-shangxia-a"},"为乌鸢食，",{text:"在下",glossary:"lyk9-shangxia-b"},"为",{text:"蝼蚁",glossary:"lyk9-louyi"},"食。",{text:"夺彼与此",glossary:"lyk9-duobiyuci"},"，何其",{text:"偏",glossary:"lyk9-pian"},"也！”"]]},{id:"lyk-p10-01",label:"衡量与征验",sentences:[[{text:"以不平平，其平也不平",glossary:"lyk10-buping"},"；",{text:"以不徵徵，其徵也不徵",glossary:"lyk10-buzheng"},"。"]]},{id:"lyk-p10-02",label:"明与神",sentences:[[{text:"明",glossary:"lyk10-ming"},"者唯为之",{text:"使",glossary:"lyk10-shi"},"，",{text:"神",glossary:"lyk10-shen"},"者徵之。"],["夫明之",{text:"不胜",glossary:"lyk10-busheng"},"神也久矣，"]]},{id:"lyk-p10-03",label:"恃见与功外",sentences:[["而愚者",{text:"恃其所见",glossary:"lyk10-shijian"},{text:"入于人",glossary:"lyk10-ruren"},"，",{text:"其功外也",glossary:"lyk10-gongwai"},"，不亦",{text:"悲",glossary:"lyk10-bei"},"乎！"]]}],m=[{text:"列御寇之齐，中道而反。",guide:"警觉与中返：列子已经主动停止前行，并能由优待预见任用与考功的风险。",note:"停止一次行程，不等于已经解除全部牵累。"},{text:"彼将任我以事，而效我以功。",guide:"优待与用途：被重视可能进一步转成承担事务、接受考核与身劳智尽。",note:"这是列子的预见，不是已经发生的任职经历；也不能认定所有优待者都存心利用。"},{text:"人将保汝矣！",guide:"显露与依附：即使不赴齐，自身显露与他人的亲附仍可能延续。",note:"门外鞋履证明聚集，不能证明所有来客的动机。"},{text:"必且有感，摇而本性。",guide:"相感与本性：影响他人，也可能在他人的期待与回应中反过来被牵动。",note:"关系机制的展开是解读，不是原文逐项陈述；他人的行动仍有独立责任。"},{text:"巧者劳而知者忧。",guide:"巧知与劳忧：能力若与不断应事、显能和受期待相连，可能成为劳忧的来源。",note:"不是要求废弃所有技巧、知识与学习。"},{text:"汎若不系之舟，虚而敖游者也！",guide:"不系与虚游：不以求取、显能与自我执持作为持续拘系自身的绳索。",note:"不是取消全部关系，也不是现实责任的普遍豁免。"}],b=[{text:"五浆先馈。",guide:"通常被视为有利的优待，在列子眼中成为特殊对待的警讯。",note:"受到重视，为什么未必意味着更加安全？"},{text:"善哉观乎！",guide:"伯昏瞀人肯定观察，却继续指出留下后仍可能出现的依附。",note:"看见一种风险与解除造成牵累的方式，有什么区别？"},{text:"户外之屦满矣。",guide:"鞋履满布使“人将保汝”的预言得到叙事照应。",note:"这个细节能够证明什么，又不能证明什么？"},{text:"曾不发药乎？",guide:"列子追请规劝，求教诚意与尚未领悟可以同时存在。",note:"愿意受教之后，仍须检省什么？"},{text:"感豫出异。",guide:"教诲从拒绝任用转向检省显能、出异与相感的方式。",note:"不主动召集他人，是否就等于不再招引？"},{text:"汎若不系之舟。",guide:"舟仍在水中，只是不被系索固定。",note:"不被关系拘系与没有任何关系，为什么不同？"}],x=[{text:"祗三年而缓为儒。",guide:"学习与身份：学习形成身份，后文检验这种身份怎样进入人与己的关系。",note:"成为儒者本身尚未被判为错误，也不能据此确认已经通达儒学。"},{text:"以己为有以异于人，以贱其亲。",guide:"差异与轻亲：差异被解释成优越，再成为看低亲近者的凭据。",note:"不是要求亲属意见一致，也不意味着接受亲属的一切不当行为。"},{text:"不报其人而报其人之天。",guide:"人之天：以天然所受与变化的尺度，动摇自我标榜及学派身份的绝对性。",note:"不直接推出天命决定一切，或造物者按善恶实施报应。"},{text:"自是有德者以不知也。",guide:"自是与德名：有德的名义不能自动证明自身判断正确。",note:"疑难句保留句法差异；批评自我担保，不是取消判断。"},{text:"古者谓之遁天之刑。",guide:"遁天之刑：人为身份、自是与执持可能使人失去天然根据，并形成伤害。",note:"不补成一个人格化的天在惩罚异见。"},{text:"圣人安其所安，不安其所不安。",guide:"可安与不可安：检验安定所依凭的根据，而不只看是否赢得身份或意见上的胜出。",note:"原文没有逐项列出所安对象，不能把解读固定为唯一清单。"}],q=[{text:"儒墨相与辩，其父助翟。",guide:"学派分歧进入家庭关系，但原文没有展开论证胜负。",note:"立场分化与轻贱他人，为什么需要分开？"},{text:"十年而缓自杀。",guide:"故事呈现严重结局，却没有逐项交代心理过程与全部原因。",note:"为什么不能将这一结局变成解释现实自杀的单一公式？"},{text:"其父梦之曰。",guide:"通常读作缓在父亲梦中说话，梦境使身份分别受到变化尺度的检验。",note:"叙事中的梦境能够承担什么作用，而不必证明什么事实？"},{text:"以贱其亲。",guide:"最明确的批评落在以自认优越贬低亲近者。",note:"如何保持不同意见，而不把差异变成人的高下？"},{text:"今之世皆缓也。",guide:"个案成为一种当世心态的代表，不是人人同一生平的统计。",note:"概括的范围扩大后，哪些细节仍不能照搬？"},{text:"众人安其所不安，不安其所安。",guide:"结尾以交错句式检验安定根据的倒置。",note:"自己依赖的安定，究竟是否真正可安？"}],c=[{text:"知道易，勿言难。",guide:"知道与勿言：有所认识后，不急于显示、推广并求得认可，也需要克制。",note:"不是断言道很容易，也不是取消所有教导、提醒与公共表达。"},{text:"三年技成而无所用其巧。",guide:"技成与可用：学习在技艺内部已经成功，仍须检验技巧、代价与实际处境的联系。",note:"不把无所用缩成不能立即赚钱，也不忽略学习的实际代价。"},{text:"众人以不必必之。",guide:"强作必然：把原本不必如此的事情执定为非如此不可，可能引出争竞与强求。",note:"不等于一切事情无所谓，或必要行动都应取消。"},{text:"敝精神乎蹇浅。",guide:"小知与耗神：局促往来中的反复筹算也可能耗神，局部熟练未必足以通达广大根本。",note:"不是说所有细节、馈赠与文书都无价值。"},{text:"归精神乎无始，而甘冥乎无何有之乡。",guide:"精神的归处：以超出固定形迹的表达，呈现不急于显明、据有与证明的精神安顿。",note:"不是赞美麻木、昏昧，也不是可实际定位的场所。"},{text:"汝为知在毫毛而不知大宁。",guide:"毫毛与大宁：细小处的精熟，不能代替对生命与精神整体安顿的认识。",note:"不是废弃细节知识，也不把大宁等同于闲居无事。"}],P=[{text:"知道易，勿言难。",guide:"重点在所知之后如何相处，而非宣布认识道毫无困难。",note:"为什么知道以后，仍须检验表达的冲动？"},{text:"三年技成。",guide:"朱泙漫不是学技失败，而是学成之后仍面临可用性问题。",note:"投入与精熟能否独自证明学习值得？"},{text:"以不必必之。",guide:"将可以不同处理的事情强作必然，可能使行动转向对抗。",note:"坚持必要之事与执定非如此不可，怎样区别？"},{text:"不离苞苴竿牍。",guide:"智虑被局限于往来与经营，活动熟练不等于认识广阔。",note:"自己擅长的小范围，是否被当成了全部世界？"},{text:"水流乎无形。",guide:"以流动形象对照固定技巧与形迹拘束。",note:"自在是否只来自增加能力，也可能来自松开方式的执持？"},{text:"不知大宁。",guide:"结尾将知识的检验转向整体安顿，而不止眼前回应与局部精熟。",note:"会处理事情与能够安顿自己，有什么距离？"}],f=[{text:"王说之，益车百乘。",guide:"受赏与值得受赏：故事承认秦王认可与丰厚所得，再检验所得能否自证高明。",note:"获得认可与值得认可不同；也不能反向断言所有厚赏都不正当。"},{text:"商之所短也；……商之所长也。",guide:"以所得建立高下：曹商借自述长短，将庄子的困顿置于低处，将自己的君赏置于高处。",note:"不是中性的自我介绍，也不由此建立贫者皆贤、富者皆恶的对应。"},{text:"所治愈下，得车愈多。",guide:"赏赐意义的反转：将车多从高明的证据改写为可能伴随更深自辱的结果。",note:"反讽针对取悦与自夸，不是贬低正规医疗或身体部位。"},{text:"子岂治其痔邪？",guide:"反问与事实：极端譬喻使厚赏失去自证效力。",note:"原文未记述曹商实际如何取悦秦王，不能把反问当成事实记录。"},{text:"何得车之多也？",guide:"所得与代价：所得之外，还须问取得的方式与人格、行动代价。",note:"所揭示的是可能关系，不是厚赏必然来自自辱的定律。"}],T=[{text:"益车百乘。",guide:"庄子没有否认厚赏，而是改变它的评价意义。",note:"得到很多，与因此值得尊重，为什么不同？"},{text:"商之所短也。",guide:"以自己的不擅长来描写庄子的困顿，实际是在轻人。",note:"这句话为何不是单纯的自谦？"},{text:"所治愈下，得车愈多。",guide:"反讽切断报酬多与行为尊贵之间的必然联系。",note:"庄子是否接受了曹商原先的比较尺度？"},{text:"子岂治其痔邪？",guide:"讽刺有力，却未提供曹商使秦的完整事实。",note:"价值反转与具体行为指控，应怎样区分？"},{text:"子行矣！",guide:"交谈在逐客中结束，没有写出曹商悔悟。",note:"拒绝一种尺度，为什么不等于完成了教化？"}],z=[{text:"吾以仲尼为贞幹，国其有瘳乎？",guide:"治理与实际改善：问题涉及用人、治理方式及能否使国家与百姓受益。",note:"颜阖的批评是人物话语，不直接裁定历史孔子的全部思想与实践。"},{text:"饰羽而画，从事华辞。以支为旨。",guide:"形式与根本：检验外在修饰与枝节是否反过来占据根本的位置。",note:"不是优美语言必然虚假，也不据此否定全部礼学。"},{text:"今使民离实学伪，非所以视民也。",guide:"离实学伪：治理可能将失真的呈现方式推广为百姓学习的范式。",note:"不把所有规范、教育与必要自制都视为伤害本性。"},{text:"施于人而不忘，非天布也。",guide:"施惠与执功：善行已经发生，仍须检验是否转为记功、索报和自我标举。",note:"必要记录与责任核对，不自动等于执功。"},{text:"虽以事齿之，神者弗齿。",guide:"作用与修养：认可实际办事效果，不等于认定内在方式已与真相应。",note:"不是否认一切施惠的实际作用。"},{text:"为外刑者，金与木也；为内刑者，动与过也。",guide:"内外之刑：伤害既可能来自外部施加，也可能来自自身失当活动的耗损。",note:"不能将所有痛苦或疾病都归因于个人过错。"}],_=[{text:"国其有瘳乎？",guide:"以国家病愈提出治理效果之问。",note:"任用一个有名望的人，是否足以保证治理改善？"},{text:"以支为旨。",guide:"形式原应服务内容，却可能反过来成为首要目标。",note:"何时是在帮助实现内容，何时是在替代内容？"},{text:"离实学伪。",guide:"批评从个人修饰扩大到传播失真范式。",note:"整齐一致、易于展示的成果，是否就意味着合宜？"},{text:"施于人而不忘。",guide:"给予之后如何对待所施之惠，也是检验的一部分。",note:"帮助为何可能转成控制关系的凭据？"},{text:"神者弗齿。",guide:"办成事情与内在修养不是同一评价层面。",note:"有实际作用，是否免去了方式与动机的检验？"},{text:"唯真人能之。",guide:"真人构成修养上的理想参照，不是免灾承诺。",note:"为什么不能由现实受害反推一个人不真？"}],j=[{text:"人者厚貌深情。",guide:"表里与变化：外貌、一时态度与内在实情未必相应，识人不能只凭固定样式。",note:"不一致不必全出于蓄意欺骗，也可能涉及处境变化与观察者误读。"},{text:"九徵至，不肖人得矣。",guide:"多处境征验：在距离、负担、利益、风险与交往环境的变化中观察行为。",note:"不是百分之百读心的方法，也不建议现实中灌酒、设险或侵犯隐私。"},{text:"一命而伛，再命而偻，三命而俯。",guide:"受命与谦退：正考父的受命增位没有转成自大，形成与骄张者的对照。",note:"弯身姿态不能独自证明内在谦德。"},{text:"贼莫大乎德有心。",guide:"德行的执取：德行也可能被据为自我形象与优越位置的凭据。",note:"不是否定有意识的行善、学习与改过。"},{text:"内视而败矣。",guide:"内省与自赏：结合自好之说，警惕沉入对自身德行的欣赏。",note:"不应扩大为反对所有自我反思。"},{text:"有以自好也而吡其所不为者也。",guide:"自好与轻人：坚持自己的选择，滑向以自己为唯一尺度、贬斥不同做法。",note:"不以偏好轻人，不等于取消有根据的善恶判断。"}],S=[{text:"厚貌深情。",guide:"外在表现只是线索，不必然就是内情本身。",note:"观察者是否也可能误读看起来不像贤者的人？"},{text:"就义若渴，去义若热。",guide:"一时热切与稳定实践之间仍有距离。",note:"态度强烈，为什么不能独自证明操守稳固？"},{text:"九徵至。",guide:"以多种处境交叉观察，不把一次表现当作全貌。",note:"如何保留观察原则，而不照搬伤害性试探？"},{text:"三命而名诸父。",guide:"地位提升可能转成对亲近关系的轻慢。",note:"受命增位后，评价他人的尺度是否也改变了？"},{text:"德有心。",guide:"不只财富地位，德行本身也可能成为自我经营的资源。",note:"检省自己的德行与欣赏自己的优越，有什么区别？"},{text:"吡其所不为者。",guide:"结尾反过来检验评价者自身。",note:"我是在辨明不当行为，还是只因他人不采用我的方式便贬低他？"}],w=[{text:"八者俱过人也，因以是穷。",guide:"过人与致穷：显著优势未必自动转成安稳，可能反而形成牵累。",note:"不是所有出众者必然受困，也不能把天然显著的风险都归责于爱表现。"},{text:"达生之情者傀，达于知者肖。",guide:"生与知：智识精熟与生命情状的通达并非同一尺度。",note:"疑难字保留训释差异，不据此取消知识价值。"},{text:"达大命者随，达小命者遭。",guide:"大小命：提示根本命限与具体际遇的层次差别。",note:"不简单译为长命短命，也不将随顺等同于被动接受一切。"},{text:"子能得珠者，必遭其睡也。",guide:"得珠与龙睡：取得一次成功，不证明已掌握危险条件。",note:"这是寓言中的判断，不抹去现实成功中的实际能力。"},{text:"使宋王而寤，子为齑粉夫！",guide:"赏赐与安全：目前的悦纳不保证态度改变时仍有安全保障。",note:"不是具体事故记载，也不普遍否定一切任用合作。"}],A=[{text:"因以是穷。",guide:"开篇反转过人必有利的想当然。",note:"优势为何仍需连同处境和关系考察？"},{text:"三者俱通达。",guide:"常联系不矜张、不逞强的处世方向。",note:"不争与表演无能、逃避责任有什么区别？"},{text:"以其十乘骄稚庄子。",guide:"匿名得车者再次以君赏轻人。",note:"为什么不能将此人直接认作曹商？"},{text:"取石来锻之！",guide:"父亲先检验珍珠来源与风险，而不是庆贺收益。",note:"拒绝危险所得，是否就保证已消除全部风险？"},{text:"必遭其睡也。",guide:"危险暂未发动，与危险已被控制不同。",note:"一次顺利取得，能证明哪些事，不能证明哪些事？"}],C=[{text:"子见夫牺牛乎？",guide:"礼遇与用途：华美供养从一开始就在祭祀用途之中。",note:"本段未交代聘请者、职位与待遇，不补入其他篇章的细节。"},{text:"衣以文绣，食以刍菽。",guide:"供养与自主：优待可以真实，却不证明受礼者的利益是整个安排的中心。",note:"不推定任何照料背后都有恶意。"},{text:"牵而入于大庙。",guide:"去向由谁决定：重点由所得转为生命如何被纳入他人的用途。",note:"不是只反对奢华，也不据此否定所有公共事业。"},{text:"虽欲为孤犊，其可得乎！",guide:"退出的余地：进入时的待遇须连同后续限制与退出可能一起考察。",note:"不要求一概拒绝任用和合作。"}],V=[{text:"或聘于庄子。",guide:"问题从评价他人受赏，转为庄子自己的选择。",note:"哪些聘请细节原文没有交代？"},{text:"牺牛。",guide:"身份已经揭示优待与最终用途的联系。",note:"只看文绣和刍菽，会漏掉什么？"},{text:"牵而入。",guide:"得到什么之外，还要看谁决定去向。",note:"供养充足为何不等于行动自主？"},{text:"其可得乎！",guide:"反问强调事后即使想退回，也可能无从退出。",note:"接受之前需要辨明哪些后续条件？"}],I=[{text:"弟子欲厚葬之。",guide:"敬爱与厚葬：关怀的心意与表达关怀的方式仍须区分。",note:"不预先认定弟子虚伪，也不认定敬爱必然要求厚葬。"},{text:"吾以天地为棺椁。",guide:"天地的容纳：将死亡的归宿放回天地变化，转换葬具完备的尺度。",note:"不是具体葬法，也不证明某种来世学说。"},{text:"何以加此！",guide:"增添与合宜：更多器物与排场不自动意味着更合宜。",note:"不由此取消所有现实丧葬安排。"},{text:"夺彼与此，何其偏也！",guide:"偏好与安排：避免一种身体去向，仍可能转向另一种变化，爱护也要检省偏好。",note:"不抹去不同葬法在法律、卫生、文化和家属需要上的实际差异。"}],R=[{text:"弟子欲厚葬之。",guide:"先理解关怀，不立即给心意贴上虚伪标签。",note:"心意值得理解，是否意味着方式无须检验？"},{text:"葬具岂不备邪？",guide:"不只要求减少器物，而是以天地万物转换完备的尺度。",note:"为什么这不只是节俭的主张？"},{text:"吾恐乌鸢之食夫子也。",guide:"弟子关心具体身体去向，不只是追求排场。",note:"哪一种变化被特别视为不可接受？"},{text:"夺彼与此。",guide:"庄子将完全保护的设想改写成两种去向之间的分配。",note:"人为安排能够改变什么，不能取消什么？"}],D=[{text:"以不平平，其平也不平。",guide:"尺度的检验：判断有形式，不等于所凭尺度已经平正。",note:"不是宣布人永远不能判断。"},{text:"以不徵徵，其徵也不徵。",guide:"征验的依据：用于证明的凭据也须接受检验。",note:"可作现代证据思考的启发，不说原文已给出完整逻辑或证据理论。"},{text:"明者唯为之使，神者徵之。",guide:"明与神的限度：明察有作用，但不必是全部通达的最高根据。",note:"疑难句保留解释差异，不将神妙或直觉提升为无需检验的权威。"},{text:"恃其所见入于人。",guide:"有限所见的过度授权：部分认识可能被执持成替他人决定的充分资格。",note:"不是所有所见都错，也不取消分享、教学与劝告。"},{text:"其功外也，不亦悲乎！",guide:"向外与返己：向外施用须伴随对自身尺度与依据的检省。",note:"不由此否定公共事务与帮助他人的意义。"}],N=[{text:"以不平平。",guide:"结论之前，先看判断尺度是否已经偏斜。",note:"自己是否把所长、偏好或处境当成通用标准？"},{text:"以不徵徵。",guide:"被拿来征验的依据，也不能自免于检验。",note:"君主认可、自称有德、一次成功，各能证明什么？"},{text:"明之不胜神。",guide:"局部辨识与整体通达并非同一层次。",note:"为什么不应直接套成理性与迷信的二分？"},{text:"恃其所见。",guide:"危险在把有限认识倚为足够凭据，而不只是认识有限。",note:"我是否允许自己的认识继续被质疑？"},{text:"其功外也。",guide:"判断他人之时，评价者自身也重新进入检验。",note:"我是否善于指出别人问题，却不检查自己的根据？"}];function h(g){return k.filter(t=>t.id.startsWith(`lyk-p${g}`))}function p(g){const t=new Set;for(const l of h(g))for(const s of l.sentences)for(const o of s)typeof o!="string"&&o.glossary&&t.add(o.glossary);return y.filter(l=>t.has(l.id)&&Array.from(l.term).length<=5)}const E=h("1"),K=p("1"),v=h("2"),B=p("2"),G=h("3"),O=p("3"),L=h("4"),J=p("4"),U=h("5"),W=p("5"),$=h("6"),F=p("6"),H=h("7"),M=p("7"),Q=h("8"),X=p("8"),Y=h("9"),Z=p("9"),tt=h("10"),dt=p("10");return(g,t)=>{const l=u("DaoReadingPrelude"),s=u("DaoTextReading"),o=u("DaoKeywordCards"),n=u("DaoLineGuide");return et(),it("div",null,[t[0]||(t[0]=d("h1",{id:"庄子·列御寇",tabindex:"-1"},[e("庄子·列御寇 "),d("a",{class:"header-anchor",href:"#庄子·列御寇","aria-label":'Permalink to "庄子·列御寇"'},"​")],-1)),a(l,{title:"有所能、有所学、有所知，是否就能安顿？",summary:"第一批先看优待与依附、学派身份与自是、言说与技巧三组问题。原文、字词解释与引申解读分开，疑难句保留讨论空间。"}),t[1]||(t[1]=i('<p>本篇开头并不先写列子贪求权位。相反，他已经对受到优待产生警觉，中途返回。</p><p>但故事继续追问：看见外部危险，是否就改变了造成牵累的内在方式？</p><p>本批材料依次展开三个方向：</p><ol><li><strong>显露与依附</strong>：被重视、被亲附，如何反过来形成劳忧？</li><li><strong>身份与自是</strong>：所学与所异，如何变成轻贱他人的凭据？</li><li><strong>知识与安顿</strong>：言说、技巧与局部聪明，是否足以证明通达？</li></ol><p><strong>这只是前三份的阅读路线，不提前作为全篇定论。</strong></p><h2 id="一、惊返与先馈·人将保汝·不系之舟" tabindex="-1">一、惊返与先馈·人将保汝·不系之舟 <a class="header-anchor" href="#一、惊返与先馈·人将保汝·不系之舟" aria-label="Permalink to &quot;一、惊返与先馈·人将保汝·不系之舟&quot;">​</a></h2>',6)),a(l,{title:"退返之后，招引是否仍在？",summary:"从列子对先馈的惊惧，进入任用、考功与身劳智尽的预见，再看伯昏瞀人为何将问题转向显露、相感与依附。"}),t[2]||(t[2]=i('<h3 id="本份范围" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“列御寇之齐，中道而反……”</li><li><strong>止于</strong>：“虚而敖游者也！”</li><li><strong>连续脉络</strong>：赴齐中返 → 解释所惊 → 任用与考功 → 他人依附 → 满屦与追请 → 显露和相感 → 巧知劳忧 → 不系之舟。</li></ul><h3 id="原文·连续阅读" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(E),glossary:y,"default-mode":"classic","aria-label":"列御寇·第1份 原文"},null,8,["sections"]),t[3]||(t[3]=d("p",null,[d("strong",null,"文字说明")],-1)),t[4]||(t[4]=d("p",null,"依据所提供文本整理，调整排版与标点，并在本份末尾收束引号。",-1)),t[5]||(t[5]=d("p",null,"“内诚不解”“形谍成光”“感豫出异”“何相孰也”等处训释疑难，以下说明主要联系，不强定逐字译法。",-1)),t[6]||(t[6]=d("p",null,"“保”主要联系聚集、亲附、依附理解，不直接译为现代的保护或担保。",-1)),t[7]||(t[7]=d("h3",{id:"关键词卡片",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(K)},null,8,["items"]),t[8]||(t[8]=d("h3",{id:"逐句导读",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:b}),t[9]||(t[9]=d("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:m}),t[10]||(t[10]=i('<h3 id="一、中途返回-列子已经有所警觉" tabindex="-1">一、中途返回：列子已经有所警觉 <a class="header-anchor" href="#一、中途返回-列子已经有所警觉" aria-label="Permalink to &quot;一、中途返回：列子已经有所警觉&quot;">​</a></h3><blockquote><p>列御寇之齐，中道而反。</p></blockquote><p>列子尚未到齐国便主动返回，不是完全不知警觉，也不是只能等到受害后反省。</p><p>伯昏瞀人却接连追问为什么返回、因何而惊、受到先馈为何反而害怕。这要求列子解释：什么构成危险，如何由眼前小事推想到未来关系？</p><p><strong>返回只能说明停止了这一次行程，不能独自证明已经解除牵累。</strong></p><h3 id="二、先馈为什么成为警讯" tabindex="-1">二、先馈为什么成为警讯？ <a class="header-anchor" href="#二、先馈为什么成为警讯" aria-label="Permalink to &quot;二、先馈为什么成为警讯？&quot;">​</a></h3><p>十家店中有五家优先给食，通常可以视为尊重与优待，列子却由此感到惊惧。</p><p>关键不在店家已经伤害他，而在这种反应显示：自身某种状态显露于外，足以改变他人对待自己的方式。</p><p>“使人轻乎贵老”通常可以联系他人将列子置于尊贵者、年长者之前理解。</p><p>优待所显示的不只是善意，也可能是特殊判断。但原文没有逐一交代店家的动机。</p><p><strong>不能认定所有先馈者都存心利用列子。列子是在预见后续关系，而非报告已经查明的动机。</strong></p><h3 id="三、内诚成光-招引不必出于蓄意炫耀" tabindex="-1">三、内诚成光：招引不必出于蓄意炫耀 <a class="header-anchor" href="#三、内诚成光-招引不必出于蓄意炫耀" aria-label="Permalink to &quot;三、内诚成光：招引不必出于蓄意炫耀&quot;">​</a></h3><blockquote><p>内诚不解，形谍成光。</p></blockquote><p>疑难句先连接内在状态与外在形貌、光采。列子的招引不必全出于蓄意表演，也可能是某种内在修养仍显成了令人注意的特征。</p><p>因而，不宜简单改写为“列子故意装成高人”。</p><p>本段更细的问题是：<strong>不故意炫耀，与已不再招引，并不是同一件事。</strong></p><p>后面的“感豫出异”继续检验显露、影响他人的方式是否止息。</p><h3 id="四、由浆人推想到君主-优待可能转成用途" tabindex="-1">四、由浆人推想到君主：优待可能转成用途 <a class="header-anchor" href="#四、由浆人推想到君主-优待可能转成用途" aria-label="Permalink to &quot;四、由浆人推想到君主：优待可能转成用途&quot;">​</a></h3><p>列子的推想分为两步：</p><table tabindex="0"><thead><tr><th>对象</th><th>所见或所虑</th></tr></thead><tbody><tr><td>浆人</td><td>利薄、权轻，尚且给予特殊对待</td></tr><tr><td>万乘之主</td><td>可能进一步任用、责求功效</td></tr></tbody></table><blockquote><p>彼将任我以事，而效我以功。</p></blockquote><p>不只是礼遇，而是交给事务、要求承担职责、按成果考核。</p><p><strong>受重视 → 被任用 → 承担事务 → 被责求功效 → 身劳智尽。</strong></p><p>这是列子的预见，不是已在齐国任职失败的经历。</p><h3 id="五、肯定观察-不等于认可全部状态" tabindex="-1">五、肯定观察，不等于认可全部状态 <a class="header-anchor" href="#五、肯定观察-不等于认可全部状态" aria-label="Permalink to &quot;五、肯定观察，不等于认可全部状态&quot;">​</a></h3><blockquote><p>善哉观乎！女处已，人将保汝矣！</p></blockquote><p>前句肯定列子的观察，后句将问题从“去齐国会怎样”转向“即使留下，他人会怎样亲附”。</p><p>两者并不矛盾：</p><ul><li>列子已经看见一种危险。</li><li>更普遍的显露、招引与牵累仍未解除。</li></ul><p><strong>外在位置改变，不等于人与自己相接的方式已经改变。</strong></p><h3 id="六、满屦与追请-聚集得到验证-求教仍然发生" tabindex="-1">六、满屦与追请：聚集得到验证，求教仍然发生 <a class="header-anchor" href="#六、满屦与追请-聚集得到验证-求教仍然发生" aria-label="Permalink to &quot;六、满屦与追请：聚集得到验证，求教仍然发生&quot;">​</a></h3><p>“户外之屦满矣”以鞋履满布呈现他人聚集，与“人将保汝”照应。</p><p>但它不能证明列子已建立庞大学派、来客全为谋利，或列子主动收徒牟利。</p><p>伯昏瞀人站立片刻，无言而出。列子得知后提屦跣走，请求：</p><blockquote><p>先生既来，曾不发药乎？</p></blockquote><p>教诲被比作纠偏的药石。列子愿意听规劝，这一诚意应当保留。</p><p>但求教不等于已悟，沉默也不必被补写成明确设计的教学考验。</p><h3 id="七、不能使人无保汝-检验的不只是主动召集" tabindex="-1">七、不能使人无保汝：检验的不只是主动召集 <a class="header-anchor" href="#七、不能使人无保汝-检验的不只是主动召集" aria-label="Permalink to &quot;七、不能使人无保汝：检验的不只是主动召集&quot;">​</a></h3><blockquote><p>非汝能使人保汝，而汝不能使人无保汝也……</p></blockquote><p>结合“感豫出异”，问题不只是有没有邀请、有没有求名，也在于怎样显现、影响他人及与这种影响相处。</p><p>他人的依附未必由列子命令而来，但伯昏瞀人认为他仍未止息招引。</p><p>这是本段的修养要求。<strong>现代引申不能据此将一切追随行为都归罪于被追随者；他人的行动仍有独立责任。</strong></p><h3 id="八、感豫出异与摇动本性-影响不是单向的" tabindex="-1">八、感豫出异与摇动本性：影响不是单向的 <a class="header-anchor" href="#八、感豫出异与摇动本性-影响不是单向的" aria-label="Permalink to &quot;八、感豫出异与摇动本性：影响不是单向的&quot;">​</a></h3><p>列子已经担忧被重视后遭任用，教诲却要求进一步检省：是否仍保留使人重视、悦服与追随的方式？</p><p>“出异”不是要求消除一切人与人的差异，而是批评显露、招引及其扰动。</p><blockquote><p>必且有感，摇而本性。</p></blockquote><p><strong>解释上的关系循环</strong>：显露引来依附，依附形成期待，期待又牵动自身，促使人维持显露。</p><p>这不是原文逐项陈述的心理机制，却可帮助说明：离开权势者仍不足以自动解除牵累。</p><h3 id="九、亲熟未必带来纠偏" tabindex="-1">九、亲熟未必带来纠偏 <a class="header-anchor" href="#九、亲熟未必带来纠偏" aria-label="Permalink to &quot;九、亲熟未必带来纠偏&quot;">​</a></h3><blockquote><p>与汝游者，又莫汝告也。</p></blockquote><p>聚集与熟悉不必然意味着相互有益。后面的“小言”“尽人毒”“莫觉莫悟”继续批评不能使人觉悟、反可能延续失觉的交游。</p><p>但原文没有给出全部来客的具体言论，不能凭空补写阿谀、谋利与争名的细节。</p><p><strong>人数与亲熟程度，不能独自证明交往的价值。</strong></p><h3 id="十、巧知与无能-能力如何成为负担" tabindex="-1">十、巧知与无能：能力如何成为负担？ <a class="header-anchor" href="#十、巧知与无能-能力如何成为负担" aria-label="Permalink to &quot;十、巧知与无能：能力如何成为负担？&quot;">​</a></h3><blockquote><p>巧者劳而知者忧。</p></blockquote><p>与前文“身劳于国而知尽于事”照应：有技巧者容易被要求应事，善谋虑者容易不断筹划。</p><p>这不是所有有能力者必然不幸的定律。关键是能力如何使用，是否与显能、求取和无法松开的期待相连。</p><p>“无能者无所求”可联系不以能巧自居、不凭显能求取理解，不直接赞美无知、懒惰或失责。</p><p>“饱食而敖游”呈现不被劳忧持续驱迫的姿态，不是吃饱闲逛便已完成修养。</p><h3 id="十一、不系之舟-松开拘系-不是取消世界" tabindex="-1">十一、不系之舟：松开拘系，不是取消世界 <a class="header-anchor" href="#十一、不系之舟-松开拘系-不是取消世界" aria-label="Permalink to &quot;十一、不系之舟：松开拘系，不是取消世界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>前面的状态</th><th>结尾的形象</th></tr></thead><tbody><tr><td>被看作特殊之人</td><td>不执持特殊身份</td></tr><tr><td>他人聚集、依附</td><td>不被关系持续拘系</td></tr><tr><td>被期待显能、应事</td><td>不以求取驱动</td></tr><tr><td>巧劳、知忧</td><td>虚而敖游</td></tr></tbody></table><p>舟仍在水中，仍与环境发生关系，只是没有被系索固定。</p><p><strong>不系可以理解为松开求取、显能与自我执持的拘束，不是完全没有关系。</strong></p><p>“虚”也不是清空全部思想情感，而是与不断显露、相感和劳忧形成对照。</p><h3 id="十二、与《渔父》的对读及后续阅读线索" tabindex="-1">十二、与《渔父》的对读及后续阅读线索 <a class="header-anchor" href="#十二、与《渔父》的对读及后续阅读线索" aria-label="Permalink to &quot;十二、与《渔父》的对读及后续阅读线索&quot;">​</a></h3><table tabindex="0"><thead><tr><th>比较项</th><th>《渔父》</th><th>本份</th></tr></thead><tbody><tr><td>危险入口</td><td>经营人事而危真</td><td>优待可能转为任用与劳忧</td></tr><tr><td>初步认识</td><td>孔子追问所失</td><td>列子已观察风险</td></tr><tr><td>进一步要求</td><td>修身守真，不只求之于人</td><td>不只退返，还须检省招引</td></tr><tr><td>求教行动</td><td>追寻、再拜</td><td>提屦跣走、请求发药</td></tr><tr><td>所指方向</td><td>精诚及人事实现</td><td>无所求、虚而敖游</td></tr></tbody></table><p>两篇都提示：发现问题，不等于改变造成问题的方式。但不必合成完全相同的修养论。</p><p>后续可继续追踪三问：</p><ul><li>被重视是否更安全？</li><li>有所能、有所知是否必然有益？</li><li>显露与关系是否反过来构成拘系？</li></ul><p>这些是待后续材料检验的线索，不提前代替全篇论证。</p><h3 id="本份·核心对照" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>中返</td><td>中道而反</td><td>已主动警觉</td><td>已解决全部问题</td></tr><tr><td>先馈</td><td>五浆先馈</td><td>特殊对待的警讯</td><td>店家都存心利用</td></tr><tr><td>显露</td><td>形谍成光</td><td>内在显于外</td><td>必是蓄意装扮</td></tr><tr><td>任用</td><td>任我以事，效我以功</td><td>礼遇与责求</td><td>已发生做官失败</td></tr><tr><td>肯定</td><td>善哉观乎</td><td>认可观察</td><td>认可全部状态</td></tr><tr><td>聚集</td><td>户外之屦满矣</td><td>依附出现</td><td>确定全部来客动机</td></tr><tr><td>求教</td><td>曾不发药乎</td><td>愿受规劝</td><td>求教即已悟</td></tr><tr><td>招引</td><td>感豫出异</td><td>检省显能相感</td><td>一切差异都应消除</td></tr><tr><td>本性</td><td>摇而本性</td><td>关系反过来牵动自身</td><td>他人不必负责</td></tr><tr><td>交游</td><td>又莫汝告也</td><td>亲熟不等于觉悟</td><td>所有交往无价值</td></tr><tr><td>巧知</td><td>巧者劳而知者忧</td><td>能力与劳忧</td><td>废弃所有能力</td></tr><tr><td>无能</td><td>无能者无所求</td><td>不凭显能求取</td><td>无知懒惰最好</td></tr><tr><td>舟与虚</td><td>汎若不系之舟</td><td>松开求取与执持</td><td>取消关系责任</td></tr></tbody></table><h3 id="本份收束" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>本段不是“发现危险、返回、从此无患”，而是继续检验：</p><p><strong>已察任用风险 → 仍会引来依附 → 聚集显出方式未变 → 不再以显能、出异与他人的回应为生活重心。</strong></p><p>不系之舟收束这一转向：由被重视、被期待、被牵动，转向不被求取与自我执持持续拘系。</p><h2 id="二、郑人缓·儒墨与亲亲·遁天之刑" tabindex="-1">二、郑人缓·儒墨与亲亲·遁天之刑 <a class="header-anchor" href="#二、郑人缓·儒墨与亲亲·遁天之刑" aria-label="Permalink to &quot;二、郑人缓·儒墨与亲亲·遁天之刑&quot;">​</a></h2>',77)),a(l,{title:"不同为何变成高下？",summary:"学习形成身份，身份进入家庭争辩；重点检验自认优越怎样转成轻贱亲近者，不将故事结局缩成单一因果。"}),t[11]||(t[11]=i('<h3 id="本份范围-1" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-1" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“郑人缓也，呻吟裘氏之地。”</li><li><strong>止于</strong>：“众人安其所不安，不安其所安。”</li><li><strong>连续脉络</strong>：学而为儒 → 弟为墨 → 争辩与父助 → 死亡与梦境 → 人之天 → 自异轻亲 → 当世批评 → 遁天之刑 → 安处对照。</li></ul><h3 id="原文·连续阅读-1" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-1" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(v),glossary:y,"default-mode":"classic","aria-label":"列御寇·第2份 原文"},null,8,["sections"]),t[12]||(t[12]=d("p",null,[d("strong",null,"文字说明")],-1)),t[13]||(t[13]=d("p",null,"本份作为独立故事与议论单元处理，不延续为伯昏瞀人的讲话。",-1)),t[14]||(t[14]=d("p",null,"“河润九里，泽及三族”“其父梦之曰”及梦中之言、“彼故使彼”“自是有德者以不知也”等处有解释分歧，优先辨明主要脉络，不强定唯一译法。",-1)),t[15]||(t[15]=d("h3",{id:"关键词卡片-1",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-1","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(B)},null,8,["items"]),t[16]||(t[16]=d("h3",{id:"逐句导读-1",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-1","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:q}),t[17]||(t[17]=d("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:x}),t[18]||(t[18]=i('<h3 id="一、学习形成身份-尚未证明通达或失当" tabindex="-1">一、学习形成身份，尚未证明通达或失当 <a class="header-anchor" href="#一、学习形成身份-尚未证明通达或失当" aria-label="Permalink to &quot;一、学习形成身份，尚未证明通达或失当&quot;">​</a></h3><blockquote><p>祗三年而缓为儒。</p></blockquote><p>原文先写学习后成为儒者，尚不能确认缓真正通达、只是冒充，或成为儒者本身就是错误。</p><p>后续检验的是：身份怎样进入家庭关系，怎样被用作判断高下的根据。</p><p><strong>学习不是这里直接否定的对象，学习后怎样看待自己与他人才是关键。</strong></p><h3 id="二、河润与弟墨-影响扩展不等于意见一致" tabindex="-1">二、河润与弟墨：影响扩展不等于意见一致 <a class="header-anchor" href="#二、河润与弟墨-影响扩展不等于意见一致" aria-label="Permalink to &quot;二、河润与弟墨：影响扩展不等于意见一致&quot;">​</a></h3><blockquote><p>河润九里，泽及三族，使其弟墨。</p></blockquote><p>水的润泽比拟影响扩展，随后却写弟成为墨者。如何衔接较为简略。</p><p>不能补写缓亲授墨学、弟为反抗哥哥而转墨，或儒学必然导致弟弟成为墨者。</p><p>最明确的是：同一家庭中，缓为儒、弟为墨，随后发生争辩。</p><p><strong>影响的扩展，与认同的一致不是一回事。</strong></p><h3 id="三、学派差异进入亲近关系-但未裁定学说胜负" tabindex="-1">三、学派差异进入亲近关系，但未裁定学说胜负 <a class="header-anchor" href="#三、学派差异进入亲近关系-但未裁定学说胜负" aria-label="Permalink to &quot;三、学派差异进入亲近关系，但未裁定学说胜负&quot;">​</a></h3><blockquote><p>儒墨相与辩，其父助翟。</p></blockquote><p>父亲支持墨的一方，不能据此确认父亲公正、故意羞辱缓，或弟弟观点必然正确。</p><p>原文没有展开双方论证。思想身份与亲近关系发生冲突，后文“以贱其亲”才给出较明确的批评方向。</p><h3 id="四、死亡结局严重-原因却未被逐项写明" tabindex="-1">四、死亡结局严重，原因却未被逐项写明 <a class="header-anchor" href="#四、死亡结局严重-原因却未被逐项写明" aria-label="Permalink to &quot;四、死亡结局严重，原因却未被逐项写明&quot;">​</a></h3><blockquote><p>十年而缓自杀。</p></blockquote><p>上下文将学习、争辩、亲属立场与死亡相连，却未写出具体心理过程。</p><p>不能补成一次辩论失败便立即自杀，或父亲一句话直接决定死亡。</p><p>**故事中的思想劝诫不能变成现实自杀的单一归因。**后续应着重分析原文明确提出的自是、轻亲与执持，不以结局裁定现实中受困者的全部责任。</p><h3 id="五、梦境-从执持身份转向死亡与变化" tabindex="-1">五、梦境：从执持身份转向死亡与变化 <a class="header-anchor" href="#五、梦境-从执持身份转向死亡与变化" aria-label="Permalink to &quot;五、梦境：从执持身份转向死亡与变化&quot;">​</a></h3><p>“其父梦之曰”通常读作父亲梦见缓，由缓在梦中说话。“而子”为“你的儿子”，“予”为说话者自称。</p><p>不能仅因句首有“其父”，便把引语全部归给父亲。</p><p>“良”“秋柏之实”常被联系于墓地与死后变化，但字句疑难，应保留解释空间。</p><p><strong>梦境的叙事作用</strong>：将活着时紧持的儒墨身份置于死亡与变化的尺度下重新检验。</p><p>不宜读成超自然报应已经得到事实证明。</p><h3 id="六、人之天-不由自我标榜最终定义人" tabindex="-1">六、人之天：不由自我标榜最终定义人 <a class="header-anchor" href="#六、人之天-不由自我标榜最终定义人" aria-label="Permalink to &quot;六、人之天：不由自我标榜最终定义人&quot;">​</a></h3><blockquote><p>不报其人而报其人之天。</p></blockquote><p>议论区分人为标举、认同的自身，与天然所受的生命根据。</p><p>“报”不立即缩成善恶奖惩。“彼故使彼”的代词也有疑难。</p><p>可先把握：万物变化不以人的学派身份与自我标榜为最终尺度。</p><p>但不能推出观点全由天命决定、人不必负责，或每个儒墨主张都天然正确。</p><p><strong>动摇身份的绝对性，不等于取消所有分辨。</strong></p><h3 id="七、最明确的批评-把差异用作轻亲的凭据" tabindex="-1">七、最明确的批评：把差异用作轻亲的凭据 <a class="header-anchor" href="#七、最明确的批评-把差异用作轻亲的凭据" aria-label="Permalink to &quot;七、最明确的批评：把差异用作轻亲的凭据&quot;">​</a></h3><blockquote><p>夫人以己为有以异于人，以贱其亲。</p></blockquote><p><strong>自认有所不同 → 将不同解释为优越 → 以此看低亲近者。</strong></p><p>关键不是不同本身，而是把不同用作贬低他人的根据。</p><p>这不是要求家庭成员观点一致、禁止辩论，或为和气放弃判断。</p><p>同样，尊重亲近关系不意味着接受亲属的一切不当行为。<strong>辨明是非与不轻贱他人可以同时成立。</strong></p><h3 id="八、井饮者相捽-高论不保证行为超出争强" tabindex="-1">八、井饮者相捽：高论不保证行为超出争强 <a class="header-anchor" href="#八、井饮者相捽-高论不保证行为超出争强" aria-label="Permalink to &quot;八、井饮者相捽：高论不保证行为超出争强&quot;">​</a></h3><p>原文只写取水者互相揪扯，没有交代起因、先后与是否争水，不补写完整事件。</p><p>它将学派争辩与日常争斗并置，使读者检验：谈论高深道理，是否仍以争强的方式对人？</p><p>但不能把任何讨论都等同于扭打。受到检验的是自是与伤害，不是讨论本身。</p><h3 id="九、皆缓、自是与遁天-德名也不能自证" tabindex="-1">九、皆缓、自是与遁天：德名也不能自证 <a class="header-anchor" href="#九、皆缓、自是与遁天-德名也不能自证" aria-label="Permalink to &quot;九、皆缓、自是与遁天：德名也不能自证&quot;">​</a></h3><p>“今之世皆缓也”让缓成为某类当世心态的代表，不是人人同一生平的事实统计。</p><p>“自是有德者以不知也”句法有分歧，结合前文可先理解：自以为是并不证明通达，有德的名义也不能自动担保正确。</p><blockquote><p>古者谓之遁天之刑。</p></blockquote><p>“遁天”与“人之天”照应，可联系人为身份、自高与执持使人离开天然根据理解。</p><p>“刑”指出伤害性，不必限于国家刑罚，也不补成人格化的天惩罚异见。</p><h3 id="十、安处的交错-安定根据是否倒置" tabindex="-1">十、安处的交错：安定根据是否倒置？ <a class="header-anchor" href="#十、安处的交错-安定根据是否倒置" aria-label="Permalink to &quot;十、安处的交错：安定根据是否倒置？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>圣人</th><th>众人</th></tr></thead><tbody><tr><td>安于真正可安之处</td><td>安于本不应安之处</td></tr><tr><td>不以不可安者为安处</td><td>对本可安者反不能安</td></tr></tbody></table><p>结合前文，可将倒置联系于天然所受与人为执持：将身份胜出、意见压倒与优越确认当成安定根据。</p><p>但原文未列出“所安”的具体对象，这只是语境解读，不固定为唯一清单。</p><p><strong>结尾不是只问有没有安静，而是问所依赖的安定是否真正可安。</strong></p><h3 id="十一、与第一份及《渔父》的对读" tabindex="-1">十一、与第一份及《渔父》的对读 <a class="header-anchor" href="#十一、与第一份及《渔父》的对读" aria-label="Permalink to &quot;十一、与第一份及《渔父》的对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>第一份</th><th>第二份</th></tr></thead><tbody><tr><td>自身光采显露</td><td>学习形成身份</td></tr><tr><td>他人给予特殊对待</td><td>自己以差异评判他人</td></tr><tr><td>依附反过来牵动自身</td><td>自是伤害亲近关系</td></tr><tr><td>巧知与劳忧</td><td>身份执持与遁天之刑</td></tr><tr><td>不系之舟</td><td>检验可安与不可安</td></tr></tbody></table><p>两份检验看似成就人的东西如何反过来拘束人，但方向不同。</p><p>《渔父》所谓“不同于己，虽善不善，谓之矜”，可与“以异”而“贱亲”对读：维护的是有根据的判断，还是自身的优越位置？</p><p>可以比较，不机械地把缓归入另一篇的分类。</p><h3 id="本份·核心对照-1" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-1" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>学习</td><td>三年而缓为儒</td><td>学习形成身份</td><td>成为儒者即错误</td></tr><tr><td>差异</td><td>使其弟墨</td><td>家庭出现不同认同</td><td>已知全部转墨原因</td></tr><tr><td>争辩</td><td>其父助翟</td><td>分歧进入亲近关系</td><td>已裁定儒墨胜负</td></tr><tr><td>死亡</td><td>十年而缓自杀</td><td>严重伤害的结局</td><td>单因解释现实自杀</td></tr><tr><td>梦境</td><td>其父梦之曰</td><td>身份受到变化检验</td><td>已证超自然报应</td></tr><tr><td>天然</td><td>报其人之天</td><td>不只由标榜定义人</td><td>天命决定一切</td></tr><tr><td>轻亲</td><td>以贱其亲</td><td>差异转成贬低</td><td>家人必须一致</td></tr><tr><td>争斗</td><td>井饮者相捽</td><td>高论未必超出争强</td><td>辩论都是扭打</td></tr><tr><td>当世</td><td>今之世皆缓也</td><td>个案成为心态代表</td><td>人人结局相同</td></tr><tr><td>自是</td><td>自是有德者以不知也</td><td>德名不能自证</td><td>不得进行判断</td></tr><tr><td>天刑</td><td>遁天之刑</td><td>失其天然的伤害</td><td>天在惩罚异见</td></tr><tr><td>安处</td><td>安其所安</td><td>检验安定根据</td><td>不思不动即安</td></tr></tbody></table><h3 id="本份收束-1" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-1" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>不能只归结为“儒墨争辩不好”。更具体的链条是：</p><p><strong>学习形成身份 → 身份成为优越凭据 → 差异变成轻亲理由 → 自是执持使人失去可安之处。</strong></p><p>所要求的不是取消不同意见，而是不将所学、所德与所异变成使他人低于自己的凭据。</p><h2 id="三、知道与不言·屠龙之巧·小知与大宁" tabindex="-1">三、知道与不言·屠龙之巧·小知与大宁 <a class="header-anchor" href="#三、知道与不言·屠龙之巧·小知与大宁" aria-label="Permalink to &quot;三、知道与不言·屠龙之巧·小知与大宁&quot;">​</a></h2>',66)),a(l,{title:"局部精熟能否代替整体安顿？",summary:"由所知如何进入言说，转向技成是否可用、所求是否必要，以及局部聪明为何仍可能耗神而不知大宁。"}),t[19]||(t[19]=i('<h3 id="本份范围-2" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-2" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“庄子曰：‘知道易，勿言难。’”</li><li><strong>止于</strong>：“汝为知在毫毛而不知大宁。”</li><li><strong>连续脉络</strong>：知道与不言 → 天与人 → 屠龙技成 → 必与不必 → 兵与求 → 小知耗神 → 至人归精神 → 毫毛与大宁。</li></ul><h3 id="原文·连续阅读-2" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-2" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(G),glossary:y,"default-mode":"classic","aria-label":"列御寇·第3份 原文"},null,8,["sections"]),t[20]||(t[20]=d("p",null,[d("strong",null,"文字说明")],-1)),t[21]||(t[21]=d("p",null,"“庄子曰”首先引出知道与不言的数句。后面的屠龙故事与议论按相邻文本单元分析，不无限延长其引语边界。",-1)),t[22]||(t[22]=d("p",null,"“以必不必”“顺于兵”“太一形虚”“水流乎无形”等处存在训释或句法差异，以下说明主要联系，不强定唯一解释。",-1)),t[23]||(t[23]=d("h3",{id:"关键词卡片-2",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-2","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(O)},null,8,["items"]),t[24]||(t[24]=d("h3",{id:"逐句导读-2",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-2","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:P}),t[25]||(t[25]=d("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:c}),t[26]||(t[26]=i('<h3 id="一、知道易-勿言难-检验所知之后的冲动" tabindex="-1">一、知道易，勿言难：检验所知之后的冲动 <a class="header-anchor" href="#一、知道易-勿言难-检验所知之后的冲动" aria-label="Permalink to &quot;一、知道易，勿言难：检验所知之后的冲动&quot;">​</a></h3><p>不宜按字面推出道很简单、人人轻易完全认识。</p><p>相对判断着重于：有所认识后，不急于说出、显示并使人认可，反而困难。</p><p>所知可能转成纠正别人、证明自己或推广主张的冲动。因此，怎样处理所知，与有所知同样需要检验。</p><p>但原文未列出所有应说、不应说的情境，不能成为取消一切教导、提醒与公共表达的原则。</p><h3 id="二、之天与之人-言说不只是透明通道" tabindex="-1">二、之天与之人：言说不只是透明通道 <a class="header-anchor" href="#二、之天与之人-言说不只是透明通道" aria-label="Permalink to &quot;二、之天与之人：言说不只是透明通道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>去向</th><th>基本联系</th></tr></thead><tbody><tr><td>所以之天</td><td>天然、不强作</td></tr><tr><td>所以之人</td><td>人为表达、组织与经营</td></tr></tbody></table><p><strong>解读上的展开</strong>：进入言说后，所知可能被名称分类固定、被立场争辩牵引，或受到听者期待与自我表现愿望影响。</p><p>这些不是原文逐项列出的机制，却说明言说可能改变人与所知的关系。</p><p>不能分成自然的一切正确、人为的一切错误。本篇自身仍用故事和言语教诲，所警惕的是言说与经营的执著。</p><p>“天而不人”也不是不再为人、不与人相处或不负责任；“古之人”是理想参照，不是古人全无言说活动的统计。</p><h3 id="三、屠龙技成-内部成功仍须检验生活联系" tabindex="-1">三、屠龙技成：内部成功仍须检验生活联系 <a class="header-anchor" href="#三、屠龙技成-内部成功仍须检验生活联系" aria-label="Permalink to &quot;三、屠龙技成：内部成功仍须检验生活联系&quot;">​</a></h3><p>故事明确写出：</p><ol><li>耗尽千金家产。</li><li>学习三年。</li><li>技巧练成。</li><li>无所使用。</li></ol><p>朱泙漫不是因不努力而学技失败，而是在技艺内部成功之后，仍面临技巧与实际处境不相接的问题。</p><p><strong>代价与精熟不能独自证明所学值得。</strong></p><h3 id="四、无所用-既不缩成赚钱-也不忽略代价" tabindex="-1">四、无所用：既不缩成赚钱，也不忽略代价 <a class="header-anchor" href="#四、无所用-既不缩成赚钱-也不忽略代价" aria-label="Permalink to &quot;四、无所用：既不缩成赚钱，也不忽略代价&quot;">​</a></h3><p>故事没有直接证明世间绝对无龙，也没有写后来生活；不能扩成所有不立即获利的学习都无价值。</p><p>反过来，也不能说只要喜欢，耗尽家产与能否使用便无需考虑。</p><p>所要求的是检验代价、技巧与实际生活的关系，不将技巧完成作为足够的价值证明。</p><h3 id="五、必与不必-强作非如此不可" tabindex="-1">五、必与不必：强作非如此不可 <a class="header-anchor" href="#五、必与不必-强作非如此不可" aria-label="Permalink to &quot;五、必与不必：强作非如此不可&quot;">​</a></h3><blockquote><p>众人以不必必之。</p></blockquote><p>“以必不必”有训释差异，但对照涉及不执定必须如此，与将本不必如此强作必然。</p><p>可用来检省“一定取得、一定胜过、一定让人接受、一定按我方式完成”的执持。</p><p>这不意味着所有事情无所谓，也不取消必要行动与辨别。<strong>重点是强作必然，不是对任何后果都不在意。</strong></p><h3 id="六、兵与求-争竞是否成了唯一凭据" tabindex="-1">六、兵与求：争竞是否成了唯一凭据？ <a class="header-anchor" href="#六、兵与求-争竞是否成了唯一凭据" aria-label="Permalink to &quot;六、兵与求：争竞是否成了唯一凭据？&quot;">​</a></h3><p>“兵”可按兵器争战理解，也有争竞之具、心态的读法。</p><p><strong>阅读上的联系</strong>：执定非如此不可 → 诉诸争竞 → 行动不断求取 → 倚赖争竞而陷入危险。</p><p>原文不是战争与防卫的完整论证，不能据此取消所有防卫、争取或分歧。</p><p>所批评的是恃兵、强求，尤其将对抗性手段当成可靠依托。</p><h3 id="七、小知的范围-熟练周旋不等于通达" tabindex="-1">七、小知的范围：熟练周旋不等于通达 <a class="header-anchor" href="#七、小知的范围-熟练周旋不等于通达" aria-label="Permalink to &quot;七、小知的范围：熟练周旋不等于通达&quot;">​</a></h3><blockquote><p>小夫之知，不离苞苴竿牍。</p></blockquote><p>馈赠、书札指向往来交际，“不离”突出智虑范围受限。</p><p>不是所有送礼写信都邪恶，而是聪明是否只围绕事务、利害与回应运转。</p><p>知道怎样安排、应付、获得回应，可以很熟练，却不等于通达生命根本。</p><h3 id="八、耗神与广大自许-局部凭据是否相称" tabindex="-1">八、耗神与广大自许：局部凭据是否相称？ <a class="header-anchor" href="#八、耗神与广大自许-局部凭据是否相称" aria-label="Permalink to &quot;八、耗神与广大自许：局部凭据是否相称？&quot;">​</a></h3><blockquote><p>敝精神乎蹇浅，而欲兼济道物，太一形虚。</p></blockquote><p>狭小事务中的反复筹算也会耗神，与第一份“巧者劳而知者忧”照应。</p><p>“太一形虚”不强定为精确体系概念。可先保留反差：智虑局促，所宣称的通达却广大。</p><p><strong>需要检验的不是有没有认真，而是所凭认识与广大自许是否相称。</strong></p><h3 id="九、形累不知太初-细节不是全部认识" tabindex="-1">九、形累不知太初：细节不是全部认识 <a class="header-anchor" href="#九、形累不知太初-细节不是全部认识" aria-label="Permalink to &quot;九、形累不知太初：细节不是全部认识&quot;">​</a></h3><p>局部聪明未解除整体迷惑。人可能善于处理已有形迹，却仍被形迹牵累。</p><p>“太初”指向原初、根本，不是要求知道宇宙诞生的准确日期。</p><p>文本也不是说细节越多必然越迷惑，而是：将细节知识当成全部认识，可能遮蔽更大的安顿问题。</p><h3 id="十、无始与无何有-不急于显明、据有与证明" tabindex="-1">十、无始与无何有：不急于显明、据有与证明 <a class="header-anchor" href="#十、无始与无何有-不急于显明、据有与证明" aria-label="Permalink to &quot;十、无始与无何有：不急于显明、据有与证明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>小知之人的状态</th><th>至人的形象</th></tr></thead><tbody><tr><td>困于狭小往来</td><td>归精神于无始</td></tr><tr><td>欲凭局部聪明兼济道物</td><td>不以特定形迹执定根本</td></tr><tr><td>被形累牵动</td><td>甘冥于无何有之乡</td></tr><tr><td>不断求取</td><td>不急于据有与显示</td></tr></tbody></table><p>“无始”“无何有之乡”不是可以找到地址的地方。</p><p>“甘冥”呈现安然，而非无奈退缩、麻木或失去意识。以不能具体限定的表达，呈现不必时时显明、求取与证明的精神归处。</p><h3 id="十一、水与太清-从固定技巧转向流动形象" tabindex="-1">十一、水与太清：从固定技巧转向流动形象 <a class="header-anchor" href="#十一、水与太清-从固定技巧转向流动形象" aria-label="Permalink to &quot;十一、水与太清：从固定技巧转向流动形象&quot;">​</a></h3><blockquote><p>水流乎无形，发泄乎太清。</p></blockquote><p>主语与句法有讨论空间，可先把握不固守形状、舒展流注与清虚的意象。</p><p>与第一份不系之舟可作照应：舟不被系索固定，水不固守某一形状。</p><p><strong>自在可能不仅来自增加能力，也来自松开对特定方式的执持。</strong></p><p>这是意象上的联系，不强说两处表达完全相同的境界。</p><h3 id="十二、毫毛与大宁-知识的重心在哪里" tabindex="-1">十二、毫毛与大宁：知识的重心在哪里？ <a class="header-anchor" href="#十二、毫毛与大宁-知识的重心在哪里" aria-label="Permalink to &quot;十二、毫毛与大宁：知识的重心在哪里？&quot;">​</a></h3><blockquote><p>汝为知在毫毛而不知大宁。</p></blockquote><p>结尾不是废弃细节，而是检验不相称：细小处十分用心，广大安宁却未被认识。</p><p><strong>全段归纳</strong>：</p><ul><li>会处理事务，未必会安顿自身。</li><li>会计算得失，未必知道所求是否必要。</li><li>会完成技巧，未必知道其与生活怎样相接。</li><li>会发表判断，未必能松开证明自己的冲动。</li></ul><p>这些不是“毫毛”的逐字翻译。“大宁”也不是只指没工作、没声音，而是整体的生命与精神安顿。</p><h3 id="十三、与前两份及《说剑》《渔父》的对读" tabindex="-1">十三、与前两份及《说剑》《渔父》的对读 <a class="header-anchor" href="#十三、与前两份及《说剑》《渔父》的对读" aria-label="Permalink to &quot;十三、与前两份及《说剑》《渔父》的对读&quot;">​</a></h3><table tabindex="0"><thead><tr><th>前文</th><th>本份</th></tr></thead><tbody><tr><td>巧者劳而知者忧</td><td>敝精神乎蹇浅</td></tr><tr><td>显露招来特殊对待</td><td>所知转为言说与经营</td></tr><tr><td>自异轻亲</td><td>不必之事强作必然</td></tr><tr><td>无所求、不系之舟</td><td>不恃争竞、归精神于无始</td></tr><tr><td>检验所安根据</td><td>毫毛之知与大宁</td></tr></tbody></table><p>三份不是重复“不要有才能”，而是分别检验显露与依附、身份与轻亲、技巧与强求。</p><p>《说剑》不只看杀伤技巧，还检验身份与功用；屠龙故事则写技成而无所用。二者都不让高明自证价值。</p><p>《渔父》中的细密审察与这里的小知耗神，都提示：局部认真不自动证明整体方向合宜。</p><h3 id="本份·核心对照-2" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-2" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>知与言</td><td>知道易，勿言难</td><td>所知之后的克制</td><td>道易、任何话都不能说</td></tr><tr><td>天与人</td><td>所以之天</td><td>警惕人为经营</td><td>所有人为活动都错</td></tr><tr><td>技巧</td><td>三年技成</td><td>技艺内部成功</td><td>学艺失败</td></tr><tr><td>使用</td><td>无所用其巧</td><td>技巧与处境</td><td>不赚钱即无价值</td></tr><tr><td>必与不必</td><td>以不必必之</td><td>强作必然</td><td>一切无所谓</td></tr><tr><td>兵与求</td><td>恃之则亡</td><td>倚赖争竞的危险</td><td>取消所有防卫争取</td></tr><tr><td>小知</td><td>不离苞苴竿牍</td><td>智虑范围受限</td><td>馈赠书札都邪恶</td></tr><tr><td>耗神</td><td>敝精神乎蹇浅</td><td>局促事务耗神</td><td>细节都无价值</td></tr><tr><td>广大之求</td><td>欲兼济道物</td><td>凭据与自许的反差</td><td>已强定太一形虚</td></tr><tr><td>根本</td><td>不知太初</td><td>形迹不等于根本</td><td>必知宇宙起始日期</td></tr><tr><td>至人</td><td>甘冥乎无何有之乡</td><td>不急于据有显示</td><td>麻木昏昧</td></tr><tr><td>结尾</td><td>不知大宁</td><td>知识与整体安顿</td><td>大宁只是闲居</td></tr></tbody></table><h3 id="本份收束-2" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-2" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>不只是少说话、少学技巧、少管事，而是检验：</p><ul><li>所知是否立即转成显示与经营？</li><li>所巧是否与实际处境相接？</li><li>所求是否被强作非如此不可？</li><li>所耗精神是否只服务于狭小周旋？</li></ul><p>“大宁”提示：知识与技巧的意义，不能只从局部精熟与眼前回应判断，还须回到生命与精神是否得到合宜安顿。</p><p>下一份将由曹商的外在所得继续追问：受到赏识、获得丰厚回报，是否足以证明高明与尊严？</p><h2 id="四、曹商得车·厚赏与自辱·庄子逐客" tabindex="-1">四、曹商得车·厚赏与自辱·庄子逐客 <a class="header-anchor" href="#四、曹商得车·厚赏与自辱·庄子逐客" aria-label="Permalink to &quot;四、曹商得车·厚赏与自辱·庄子逐客&quot;">​</a></h2>',73)),a(l,{title:"得到很多，是否就能自证高明？",summary:"曹商以君主认可和百乘之车建立高下；庄子不否认所得，而以反讽追问取得方式与代价。"}),t[27]||(t[27]=i('<h3 id="本份范围-3" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-3" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“宋人有曹商者，为宋王使秦。”</li><li><strong>止于</strong>：“子行矣！”</li><li><strong>连续脉络</strong>：出使获赏 → 以贫困反衬成功 → 治病得车的反讽 → 改写车多的意义 → 逐客。</li></ul><p>第三份写技成与大宁，本份换成更醒目的结果尺度：</p><blockquote><p>获得君主赏识与丰厚报酬，是否足以证明自己的高明？</p></blockquote><h3 id="原文·连续阅读-3" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-3" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',5)),a(s,{sections:r(L),glossary:y,"default-mode":"classic","aria-label":"列御寇·第4份 原文"},null,8,["sections"]),t[28]||(t[28]=d("p",null,[d("strong",null,"文字说明")],-1)),t[29]||(t[29]=d("p",null,"原文依据所提供文本整理。“王说之”的“说”读 yuè，车数语境中的“乘”读 shèng。",-1)),t[30]||(t[30]=d("p",null,"庄子使用带有羞辱意味的身体譬喻进行反讽。原文没有记述曹商具体如何取悦秦王，不能将反问当成事实记录。",-1)),t[31]||(t[31]=d("h3",{id:"关键词卡片-3",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-3","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(J)},null,8,["items"]),t[32]||(t[32]=d("h3",{id:"逐句导读-3",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-3","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:T}),t[33]||(t[33]=d("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:f}),t[34]||(t[34]=i('<h3 id="一、先让外在所得成立-再检验它的意义" tabindex="-1">一、先让外在所得成立，再检验它的意义 <a class="header-anchor" href="#一、先让外在所得成立-再检验它的意义" aria-label="Permalink to &quot;一、先让外在所得成立，再检验它的意义&quot;">​</a></h3><p>故事并未否认曹商确实获得厚赏，也没有先说他完全没有交际才能。</p><table tabindex="0"><thead><tr><th>已经写出的事实</th><th>尚不能直接证明的判断</th></tr></thead><tbody><tr><td>秦王喜欢曹商</td><td>曹商所行必然合宜</td></tr><tr><td>曹商得到厚赏</td><td>厚赏必然来自高尚行为</td></tr><tr><td>曹商拥有大量车辆</td><td>他因此高于贫困的庄子</td></tr></tbody></table><p><strong>获得认可，与值得认可，并不是同一个问题。</strong></p><h3 id="二、所短与所长-不是中性介绍-而是建立高下" tabindex="-1">二、所短与所长：不是中性介绍，而是建立高下 <a class="header-anchor" href="#二、所短与所长-不是中性介绍-而是建立高下" aria-label="Permalink to &quot;二、所短与所长：不是中性介绍，而是建立高下&quot;">​</a></h3><p>曹商的“所短”对应庄子的处境，“所长”对应自己的所得。</p><table tabindex="0"><thead><tr><th>层面</th><th>对庄子的描写</th><th>对自身的展示</th></tr></thead><tbody><tr><td>居处与生计</td><td>穷闾厄巷、困窘织屦</td><td>君主厚赏</td></tr><tr><td>身体与外观</td><td>槁项黄馘</td><td>百乘之车的排场</td></tr><tr><td>隐含评价</td><td>困顿即无能</td><td>获赏即高明</td></tr></tbody></table><p>他没有讨论庄子的思想，而是用资源、身体状态和权势认可压低对方。</p><p>但不能反向推出贫困必然证明高尚。<strong>本段动摇贫富自证高下的尺度，不建立贫者皆贤、富者皆恶的对应。</strong></p><h3 id="三、一悟万乘之主-迅速、权势与可见所得" tabindex="-1">三、一悟万乘之主：迅速、权势与可见所得 <a class="header-anchor" href="#三、一悟万乘之主-迅速、权势与可见所得" aria-label="Permalink to &quot;三、一悟万乘之主：迅速、权势与可见所得&quot;">​</a></h3><p>“一悟”让成功显得迅速，“万乘之主”放大认可者的权势，“百乘之车”将认可变成可展示的所得。</p><p>曹商据此证明所长，却未说明君主究竟喜欢他什么。</p><p>这个未被交代的取得方式，正是庄子反讽进入的地方。</p><h3 id="四、庄子不争贫富-而是改写赏赐的意义" tabindex="-1">四、庄子不争贫富，而是改写赏赐的意义 <a class="header-anchor" href="#四、庄子不争贫富-而是改写赏赐的意义" aria-label="Permalink to &quot;四、庄子不争贫富，而是改写赏赐的意义&quot;">​</a></h3><p>庄子没有回答自己其实不穷，也没有宣称自己更能得车。</p><p>他举出治病得车的关系，与曹商同样涉及服务君主和车辆报酬，却将解释反转：</p><table tabindex="0"><thead><tr><th>曹商的尺度</th><th>庄子的反讽</th></tr></thead><tbody><tr><td>车多证明高明</td><td>车多也可能伴随更深自辱</td></tr><tr><td>君主喜欢，证明有本领</td><td>君主喜欢什么，仍须追问</td></tr><tr><td>厚赏压倒贫困者</td><td>报酬不能遮蔽行为代价</td></tr></tbody></table><p><strong>庄子不是争夺同一尺度下的胜出，而是在检验尺度本身。</strong></p><h3 id="五、愈下与愈多-反讽不等于医疗贬低" tabindex="-1">五、愈下与愈多：反讽不等于医疗贬低 <a class="header-anchor" href="#五、愈下与愈多-反讽不等于医疗贬低" aria-label="Permalink to &quot;五、愈下与愈多：反讽不等于医疗贬低&quot;">​</a></h3><blockquote><p>所治愈下，得车愈多。</p></blockquote><p>“下”首先联系身体部位，借“舐痔”的极端形象又带出屈身自辱。</p><p>这种卑下意味来自整段讽刺，尤其是“舐”的行为，不应泛化为对身体部位或正规医疗工作的贬低。</p><h3 id="六、反问不是已经查明的行为" tabindex="-1">六、反问不是已经查明的行为 <a class="header-anchor" href="#六、反问不是已经查明的行为" aria-label="Permalink to &quot;六、反问不是已经查明的行为&quot;">​</a></h3><blockquote><p>子岂治其痔邪？何得车之多也？</p></blockquote><p>这不是平静调查医疗经历，而是将厚赏自证推向荒诞。</p><table tabindex="0"><thead><tr><th>文本所做</th><th>不能据此认定</th></tr></thead><tbody><tr><td>攻击曹商的自夸</td><td>已查明其具体取悦方式</td></tr><tr><td>揭露报酬尺度的问题</td><td>所有获赏者都有相同行为</td></tr><tr><td>使车多失去自证效力</td><td>使秦的全部经过已经清楚</td></tr></tbody></table><p><strong>讽刺有力，不等于事实证据完整。</strong></p><h3 id="七、逐客-拒绝尺度-未写出悔悟" tabindex="-1">七、逐客：拒绝尺度，未写出悔悟 <a class="header-anchor" href="#七、逐客-拒绝尺度-未写出悔悟" aria-label="Permalink to &quot;七、逐客：拒绝尺度，未写出悔悟&quot;">​</a></h3><p>“子行矣”终止交谈。故事没有写曹商反驳、悔悟或改变生活。</p><p>与《渔父》中持续追问的结构不同，此处呈现庄子拒绝参与这套高下比较，不是已完成对曹商的教化。</p><h3 id="八、与前文及后续的联系" tabindex="-1">八、与前文及后续的联系 <a class="header-anchor" href="#八、与前文及后续的联系" aria-label="Permalink to &quot;八、与前文及后续的联系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对读对象</th><th>共同问题</th><th>不同重点</th></tr></thead><tbody><tr><td>列子先馈</td><td>受到重视如何解释？</td><td>列子警觉，曹商自夸</td></tr><tr><td>郑人缓</td><td>是否以差异轻人？</td><td>学派亲属与君赏贫困不同</td></tr><tr><td>屠龙者</td><td>局部成功能否自证价值？</td><td>技成无用与厚赏自辱不同</td></tr></tbody></table><p>后续得车与骊龙之珠可继续检验安全风险；本段先检验取得方式与尊严代价。这里仅保留阅读线索，不提前替后文作结论。</p><h3 id="九、现代引申-认可、报酬与具体指控" tabindex="-1">九、现代引申：认可、报酬与具体指控 <a class="header-anchor" href="#九、现代引申-认可、报酬与具体指控" aria-label="Permalink to &quot;九、现代引申：认可、报酬与具体指控&quot;">​</a></h3><p>以下为现代引申：</p><ul><li>被有权者欣赏，不自动证明诚实或行为合宜。</li><li>丰厚报酬可能来自正当贡献，也可能伴随不合宜代价，须具体辨认。</li><li>不以自己的成功羞辱他人的困顿。</li><li>指控现实中的具体行为需要证据，不能仅凭所得高便推定其自辱。</li></ul><h3 id="本份·核心对照-3" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-3" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>出使</td><td>为宋王使秦</td><td>使者身份</td><td>已知全部经过</td></tr><tr><td>获赏</td><td>王说之，益车百乘</td><td>认可与所得</td><td>必然证明高尚</td></tr><tr><td>贬低</td><td>商之所短也</td><td>借困顿建立高下</td><td>只是自谦</td></tr><tr><td>自夸</td><td>商之所长也</td><td>以君赏自证</td><td>受赏即值得受赏</td></tr><tr><td>譬喻</td><td>秦王有病召医</td><td>反转报酬意义</td><td>贬低所有医疗</td></tr><tr><td>枢纽</td><td>所治愈下，得车愈多</td><td>厚赏可能伴随自辱</td><td>厚赏必然卑下</td></tr><tr><td>反问</td><td>子岂治其痔邪</td><td>切断所得自证</td><td>已确认实际行事</td></tr><tr><td>逐客</td><td>子行矣</td><td>拒绝原有尺度</td><td>曹商已悔悟</td></tr><tr><td>全段</td><td>所得与取得代价</td><td>结果之外须检验</td><td>贫者皆贤、富者皆恶</td></tr></tbody></table><h3 id="本份收束-3" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-3" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>曹商的推论是：</p><p><strong>君主喜欢 → 得车很多 → 自己高明，庄子不如自己。</strong></p><p>庄子的反讽切断它：厚赏能说明受赏，却不能独自说明尊贵，还须问取悦方式与取得代价。</p><p>本段不是否定一切所得，而是拒绝让外在报酬直接充当人格高下的证明。</p><h2 id="五、颜阖论仲尼·离实学伪·内外之刑" tabindex="-1">五、颜阖论仲尼·离实学伪·内外之刑 <a class="header-anchor" href="#五、颜阖论仲尼·离实学伪·内外之刑" aria-label="Permalink to &quot;五、颜阖论仲尼·离实学伪·内外之刑&quot;">​</a></h2>',44)),a(l,{title:"以治理与施惠为名，是否已经合宜？",summary:"从用人治国进入形式与真实，再检验施惠是否执功，以及没有外部刑罚是否仍可能发生内在耗损。"}),t[35]||(t[35]=i('<h3 id="本份范围-4" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-4" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“鲁哀公问乎颜阖曰……”</li><li><strong>止于</strong>：“夫免乎外内之刑者，唯真人能之。”</li><li><strong>连续脉络</strong>：用人设想 → 修饰与忍性 → 离实学伪 → 劝停 → 施惠记功 → 内外之刑 → 真人参照。</li></ul><h3 id="原文·连续阅读-4" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-4" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(U),glossary:y,"default-mode":"classic","aria-label":"列御寇·第5份 原文"},null,8,["sections"]),t[36]||(t[36]=d("p",null,[d("strong",null,"文字说明")],-1)),t[37]||(t[37]=d("p",null,"“施于人而不忘”以下作为相邻议论处理，不未经说明全部归入颜阖继续发言。",-1)),t[38]||(t[38]=d("p",null,"“殆哉圾乎”“以支为旨”“而不知不信”“彼宜女与予颐与，误而可矣”等处疑难，不强作逐字定译。",-1)),t[39]||(t[39]=d("p",null,"颜阖对仲尼的批评属于人物话语，不直接等于对历史孔子全部思想与实践的事实裁定。",-1)),t[40]||(t[40]=d("h3",{id:"关键词卡片-4",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-4","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(W)},null,8,["items"]),t[41]||(t[41]=d("h3",{id:"逐句导读-4",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-4","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:_}),t[42]||(t[42]=d("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:z}),t[43]||(t[43]=i('<h3 id="一、以人为主干-以国家为病者" tabindex="-1">一、以人为主干，以国家为病者 <a class="header-anchor" href="#一、以人为主干-以国家为病者" aria-label="Permalink to &quot;一、以人为主干，以国家为病者&quot;">​</a></h3><blockquote><p>吾以仲尼为贞幹，国其有瘳乎？</p></blockquote><p>鲁哀公设想以仲尼支撑治理，使国家弊病改善。</p><p>问题不只是私人品格，还涉及能否任事、办法是否合宜、国家与百姓能否受益。</p><p>因而，颜阖批评的主要是将这种实践方式推广为治理根据可能造成什么。</p><h3 id="二、修饰与枝节-形式是否反客为主" tabindex="-1">二、修饰与枝节：形式是否反客为主？ <a class="header-anchor" href="#二、修饰与枝节-形式是否反客为主" aria-label="Permalink to &quot;二、修饰与枝节：形式是否反客为主？&quot;">​</a></h3><blockquote><p>饰羽而画，从事华辞。以支为旨。</p></blockquote><p>羽毛绘饰与华辞连接外在呈现，“支”与“旨”常联系枝节、根本的倒置。</p><p>可理解为形式原应服务内容，却成为首要目标。</p><p>但不能由此断定优美语言必然虚假、一切装饰都错，或孔子全部礼学都是枝末。</p><p><strong>受到检验的是修饰是否遮蔽、取代实际内容。</strong></p><h3 id="三、忍性与心神-范式可能怎样耗损人" tabindex="-1">三、忍性与心神：范式可能怎样耗损人？ <a class="header-anchor" href="#三、忍性与心神-范式可能怎样耗损人" aria-label="Permalink to &quot;三、忍性与心神：范式可能怎样耗损人？&quot;">​</a></h3><p>“忍性以视民”常联系以压抑本性的方式示范、教示百姓。</p><p>一旦成为治理范式，损耗可能不止发生在教化者自身，还可能要求众人按同一失真样式呈现自己。</p><p>“受乎心，宰乎神”通常联系心智经营支配精神，句法仍有讨论空间。</p><p>**必要的自我克制与损性强作不可混同。**节制伤害他人的冲动、履行正当责任，不因需要克制就成为伪。</p><p>此处也不作现代心理诊断。</p><h3 id="四、疑难句不强译-明确批评不遗漏" tabindex="-1">四、疑难句不强译，明确批评不遗漏 <a class="header-anchor" href="#四、疑难句不强译-明确批评不遗漏" aria-label="Permalink to &quot;四、疑难句不强译，明确批评不遗漏&quot;">​</a></h3><p>“彼宜女与予颐与，误而可矣”难以据现有材料定出唯一译法。</p><p>可先保留前后方向：</p><ul><li>前文质疑足以居于民上。</li><li>后文明说使民离实学伪。</li><li>末尾劝停眼前安排。</li></ul><p>局部不确定不等于整段没有主线，也不应为了译文顺畅而补写确定含义。</p><h3 id="五、离实学伪-治理可能传播失真的方式" tabindex="-1">五、离实学伪：治理可能传播失真的方式 <a class="header-anchor" href="#五、离实学伪-治理可能传播失真的方式" aria-label="Permalink to &quot;五、离实学伪：治理可能传播失真的方式&quot;">​</a></h3><blockquote><p>今使民离实学伪，非所以视民也。</p></blockquote><p>这将修饰、华辞与忍性收拢为教化方式的问题。</p><p>不只某个人不够真诚，而是百姓被引向以应有的样子替代真实生活。</p><p><strong>现代帮助理解的检验</strong>：整齐、统一、便于展示的成果，是否真正相应于人的生活与内在根据？</p><p>“为后世虑，不若休之”将影响延伸到后来。劝停首先针对所批评的用人安排与做法，不扩大为取消一切治理、教育和制度。</p><h3 id="六、施惠后不忘-善行是否变成索报凭据" tabindex="-1">六、施惠后不忘：善行是否变成索报凭据？ <a class="header-anchor" href="#六、施惠后不忘-善行是否变成索报凭据" aria-label="Permalink to &quot;六、施惠后不忘：善行是否变成索报凭据？&quot;">​</a></h3><blockquote><p>施于人而不忘，非天布也。</p></blockquote><p>给予已经发生，仍须问给予之后怎样对待它。</p><p><strong>引申上的展开</strong>：若持续要求对方记功、回应、承认施惠者更高，善行便可能夹杂交易与控制。</p><p>但“不忘”不按字面理解为有记忆即失德。必要记录、核对责任，不自动等于执功索报。</p><h3 id="七、商贾与神者-办成事情还不是全部标准" tabindex="-1">七、商贾与神者：办成事情还不是全部标准 <a class="header-anchor" href="#七、商贾与神者-办成事情还不是全部标准" aria-label="Permalink to &quot;七、商贾与神者：办成事情还不是全部标准&quot;">​</a></h3><p>“商贾不齿”是尖锐对照，不必读成商业活动全都不真，或商人天然低下。</p><blockquote><p>虽以事齿之，神者弗齿。</p></blockquote><table tabindex="0"><thead><tr><th>事务层面</th><th>精神、修养层面</th></tr></thead><tbody><tr><td>可能办成事情</td><td>是否仍执功计报？</td></tr><tr><td>可能帮助别人</td><td>是否借此自高、控制关系？</td></tr><tr><td>可认可实际作用</td><td>不由此确认已与真相应</td></tr></tbody></table><p>与前文相接：</p><ul><li>技巧练成，仍问其用。</li><li>厚赏到手，仍问行为。</li><li>施惠有效，仍问内在方式。</li></ul><p><strong>一层面的成功，不能替代其他层面的检验。</strong></p><h3 id="八、内外之刑-伤害有不同来源" tabindex="-1">八、内外之刑：伤害有不同来源 <a class="header-anchor" href="#八、内外之刑-伤害有不同来源" aria-label="Permalink to &quot;八、内外之刑：伤害有不同来源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>外刑</th><th>内刑</th></tr></thead><tbody><tr><td>金木等外部刑具</td><td>动与过</td></tr><tr><td>从外施加</td><td>自身活动与失当形成的耗损</td></tr><tr><td>较易被看见</td><td>未必立即显露</td></tr></tbody></table><p>不能说所有活动都会伤身、静止便全无患，或一切痛苦都是个人过错。</p><p>内外并列，恰恰要求分辨不同来源。<strong>自我检省不取消外部责任。</strong></p><p>“阴阳食之”体现古代生命、精神与阴阳关系的理解，不直接对应某种现代疾病或医学诊断。</p><h3 id="九、真人-修养参照-不是免灾保证" tabindex="-1">九、真人：修养参照，不是免灾保证 <a class="header-anchor" href="#九、真人-修养参照-不是免灾保证" aria-label="Permalink to &quot;九、真人：修养参照，不是免灾保证&quot;">​</a></h3><blockquote><p>夫免乎外内之刑者，唯真人能之。</p></blockquote><p>真人是高度理想参照，本段未完整定义其境界。</p><p>不能保证有修养者现实中绝不受迫害、绝不生病，更不能由遭遇伤害反推其不真。</p><p>与《渔父》的精诚、守真可以联系，但不强定两篇每处“真”都已完全同义。</p><h3 id="十、三层议论的共同方向" tabindex="-1">十、三层议论的共同方向 <a class="header-anchor" href="#十、三层议论的共同方向" aria-label="Permalink to &quot;十、三层议论的共同方向&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层次</th><th>要检验的问题</th></tr></thead><tbody><tr><td>治理、教化</td><td>是否使人离实学伪？</td></tr><tr><td>施惠</td><td>是否将善行据为己功？</td></tr><tr><td>无外患</td><td>是否仍有内在耗损？</td></tr></tbody></table><p>三层都不让名义、结果与外部评价自证合宜，而要求回看内容、根据与人我后果。</p><p>与《渔父》对读时须保留差异：那里孔子在场并持续求教，此处仲尼不在场，没有写出回应；不能借另一篇结尾替他补答。</p><h3 id="本份·核心对照-4" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-4" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>用人</td><td>以仲尼为贞幹</td><td>治理与改善</td><td>只问私人品格</td></tr><tr><td>修饰</td><td>饰羽而画，从事华辞</td><td>形式与内容</td><td>优美表达必然假</td></tr><tr><td>根本</td><td>以支为旨</td><td>枝节反客为主</td><td>否定全部礼学</td></tr><tr><td>本性</td><td>忍性以视民</td><td>强作范式</td><td>一切自制皆错</td></tr><tr><td>核心</td><td>离实学伪</td><td>教化传播失真</td><td>伪只指撒谎</td></tr><tr><td>劝停</td><td>不若休之</td><td>停止所批评安排</td><td>取消所有治理</td></tr><tr><td>施惠</td><td>施于人而不忘</td><td>执功与计报</td><td>记得帮助即失德</td></tr><tr><td>评价</td><td>以事齿之，神者弗齿</td><td>作用与修养不同</td><td>有效果即全合宜</td></tr><tr><td>外刑</td><td>金与木</td><td>外部刑害</td><td>痛苦全由自身</td></tr><tr><td>内刑</td><td>动与过</td><td>失当活动的耗损</td><td>所有行动都伤身</td></tr><tr><td>生命</td><td>阴阳食之</td><td>无外罚仍可耗损</td><td>可作医学诊断</td></tr><tr><td>真人</td><td>唯真人能之</td><td>理想修养参照</td><td>有德者绝不受害</td></tr></tbody></table><h3 id="本份收束-4" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-4" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>治理有其名，不等于百姓真受益；施惠有其效，不等于没有执功；没有外部处罚，不等于没有内在耗损。</p><p>评价一种实践，需要同时问：</p><p><strong>以什么为名 → 做成什么 → 从何种根据出发 → 给他人与自身带来什么。</strong></p><h2 id="六、人心与九徵·正考父·自好之德" tabindex="-1">六、人心与九徵·正考父·自好之德 <a class="header-anchor" href="#六、人心与九徵·正考父·自好之德" aria-label="Permalink to &quot;六、人心与九徵·正考父·自好之德&quot;">​</a></h2>',61)),a(l,{title:"识人者也须检验自己",summary:"九徵将识人放回不同处境，受命与德行的议论则反过来检验评价者是否自高、自赏，并以自己的方式贬低他人。"}),t[44]||(t[44]=i('<h3 id="本份范围-5" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-5" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“孔子曰：‘凡人心险于山川，难于知天。’”</li><li><strong>止于</strong>：“中德也者，有以自好也而吡其所不为者也。”</li><li><strong>连续脉络</strong>：人心难知 → 表里与变化 → 九徵 → 受命谦退与骄张 → 德有心 → 自好轻人。</li></ul><h3 id="原文·连续阅读-5" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-5" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r($),glossary:y,"default-mode":"classic","aria-label":"列御寇·第6份 原文"},null,8,["sections"]),t[45]||(t[45]=d("p",null,[d("strong",null,"文字说明")],-1)),t[46]||(t[46]=d("p",null,"本份依此次提供文字整理，调整标点与分段，未另行完成版本对勘。",-1)),t[47]||(t[47]=d("p",null,"“貌愿而益”等对照句、“吕钜”“心有睫”“中德”等有训释差异，区分可把握的方向与未强定的逐字解释。",-1)),t[48]||(t[48]=d("p",null,"“孔子曰”的引语止于九徵之说。正考父、自好之德作为相邻单元，不全部归作孔子继续发言。",-1)),t[49]||(t[49]=d("h3",{id:"关键词卡片-5",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-5","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(F)},null,8,["items"]),t[50]||(t[50]=d("h3",{id:"逐句导读-5",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-5","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:S}),t[51]||(t[51]=d("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:j}),t[52]||(t[52]=i('<h3 id="一、人心与天时-不能凭眼前表现过快对应" tabindex="-1">一、人心与天时：不能凭眼前表现过快对应 <a class="header-anchor" href="#一、人心与天时-不能凭眼前表现过快对应" aria-label="Permalink to &quot;一、人心与天时：不能凭眼前表现过快对应&quot;">​</a></h3><p>天时尚有春夏秋冬与旦暮之期，人却可能外貌有遮蔽、实情深藏。</p><p>不宜说自然全部容易认识，而应把握：识人不能只凭外观推定。</p><p>看起来诚恳、严肃、随和，或说话动听，都只是线索，不自动证明可靠、操守或能力。</p><h3 id="二、表里不一致-也可能是观察者误读" tabindex="-1">二、表里不一致：也可能是观察者误读 <a class="header-anchor" href="#二、表里不一致-也可能是观察者误读" aria-label="Permalink to &quot;二、表里不一致：也可能是观察者误读&quot;">​</a></h3><p>各组对照字句不都易确定，主线是外在呈现与实际状态未必一致。</p><p>不一致不必全是蓄意欺骗，也可能涉及不同处境、真实能力未按预期显现，或观察者误读。</p><p><strong>不仅看起来好的人可能不好，看起来不符合期待的人也未必没有长处。</strong></p><p>识人不能变成寻找固定的贤者外貌。</p><h3 id="三、就义若渴-去义若热-强烈态度未必稳定" tabindex="-1">三、就义若渴，去义若热：强烈态度未必稳定 <a class="header-anchor" href="#三、就义若渴-去义若热-强烈态度未必稳定" aria-label="Permalink to &quot;三、就义若渴，去义若热：强烈态度未必稳定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>一时表现</th><th>尚待观察</th></tr></thead><tbody><tr><td>当下坚决</td><td>情境变化后是否坚持？</td></tr><tr><td>热切赞同</td><td>涉及自身利益时是否实行？</td></tr><tr><td>积极投入</td><td>遇到困难时是否立即背离？</td></tr></tbody></table><p>不是所有热切行义者都不可信，而是不能仅凭趋赴之急便认为已看清其人。</p><h3 id="四、九徵-将评价放回实际处境" tabindex="-1">四、九徵：将评价放回实际处境 <a class="header-anchor" href="#四、九徵-将评价放回实际处境" aria-label="Permalink to &quot;四、九徵：将评价放回实际处境&quot;">​</a></h3><table tabindex="0"><thead><tr><th>处境</th><th>所观</th><th>帮助理解的问题</th></tr></thead><tbody><tr><td>远使之</td><td>忠</td><td>离开近处监督，是否尽所托？</td></tr><tr><td>近使之</td><td>敬</td><td>日常熟悉之后，是否仍认真有分寸？</td></tr><tr><td>烦使之</td><td>能</td><td>繁杂事务中能否处理？</td></tr><tr><td>卒然问焉</td><td>知</td><td>突然被问，能否辨明、应对？</td></tr><tr><td>急与之期</td><td>信</td><td>紧迫期限下是否可靠？</td></tr><tr><td>委之以财</td><td>仁</td><td>怎样处置财物与人我利益？</td></tr><tr><td>告之以危</td><td>节</td><td>风险压力下如何守持？</td></tr><tr><td>醉之以酒</td><td>则</td><td>常态控制松动后是否仍有分寸？</td></tr><tr><td>杂之以处</td><td>色</td><td>复杂交往中呈现什么态度与行为？</td></tr></tbody></table><p>表中问题是帮助理解的展开，不是逐字翻译。</p><p>远近、繁杂与突然、利益与风险、酒与杂处，构成多方向观察，不是九个彼此无关的小测试。</p><p>“不肖人得矣”表达征验的信心，却不能转为百分之百测知人心的现代保证。</p><h3 id="五、现代应用-观察合作-不制造伤害" tabindex="-1">五、现代应用：观察合作，不制造伤害 <a class="header-anchor" href="#五、现代应用-观察合作-不制造伤害" aria-label="Permalink to &quot;五、现代应用：观察合作，不制造伤害&quot;">​</a></h3><p>原文有饮酒、危难等征验表达，不据此建议现实中：</p><ul><li>故意灌醉他人。</li><li>制造危险考验忠诚。</li><li>设局诱使人犯错。</li><li>侵犯隐私证明人性。</li></ul><p>可以引申保留的原则，是在真实、必要、合宜的共同事务中持续观察：守约、资源透明、压力下诚实沟通、分歧时尊重他人。</p><p><strong>还须检验任务、资源与处境是否合理公平，不能把不合理安排造成的失败全归为人格缺陷。</strong></p><h3 id="六、正考父与凡夫-所得地位是否变成轻慢" tabindex="-1">六、正考父与凡夫：所得地位是否变成轻慢？ <a class="header-anchor" href="#六、正考父与凡夫-所得地位是否变成轻慢" aria-label="Permalink to &quot;六、正考父与凡夫：所得地位是否变成轻慢？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>受命层次</th><th>正考父</th><th>相对照者</th></tr></thead><tbody><tr><td>一命</td><td>伛</td><td>吕钜，骄张</td></tr><tr><td>再命</td><td>偻</td><td>于车上舞</td></tr><tr><td>三命</td><td>俯</td><td>名诸父</td></tr></tbody></table><p>正考父受命愈高，姿态愈低，沿墙而行；另一类人则随地位增加而骄张，直呼父辈之名。</p><p>与前文照应：</p><ul><li>缓凭所学轻亲。</li><li>曹商凭君赏轻人。</li><li>此处凭受命增位轻慢。</li></ul><p>但弯身不独自证明谦德。前文已经警惕表里不一，应在整体叙事中理解正考父的形象。</p><p>唐、许作为理想人物参照，也不必转成古人的统一历史排名。</p><h3 id="七、德有心-德行也能成为经营自我的资源" tabindex="-1">七、德有心：德行也能成为经营自我的资源 <a class="header-anchor" href="#七、德有心-德行也能成为经营自我的资源" aria-label="Permalink to &quot;七、德有心：德行也能成为经营自我的资源&quot;">​</a></h3><blockquote><p>贼莫大乎德有心。</p></blockquote><p>危险不只来自财富地位，德也可能被据为自己的优越凭据。</p><p><strong>解读上的展开</strong>：更正直、更谦让、不做某些事，可能被用来要求他人承认自己更高。</p><p>但有意识改过、学习、行善不自动为错。</p><p>受到批评的是将德据为己有，转成自赏、计较和轻人。</p><h3 id="八、内视而败-区分检省与自赏" tabindex="-1">八、内视而败：区分检省与自赏 <a class="header-anchor" href="#八、内视而败-区分检省与自赏" aria-label="Permalink to &quot;八、内视而败：区分检省与自赏&quot;">​</a></h3><p>“心有睫”是疑难譬喻，结合“自好”可把握一种读法：回看自身之德，沉入欣赏，反而损德。</p><table tabindex="0"><thead><tr><th>检省</th><th>自赏</th></tr></thead><tbody><tr><td>我是否判断过快？</td><td>我果然比别人高明</td></tr><tr><td>我是否伤害他人？</td><td>我的德行无可指摘</td></tr><tr><td>我是否仍有执著？</td><td>我连不执著都胜过别人</td></tr><tr><td>是否需要修正？</td><td>别人应承认我的优越</td></tr></tbody></table><p><strong>“内视而败”不扩大为反对一切内省、反思与改过。</strong></p><h3 id="九、中德-以下文说明为入口" tabindex="-1">九、中德：以下文说明为入口 <a class="header-anchor" href="#九、中德-以下文说明为入口" aria-label="Permalink to &quot;九、中德：以下文说明为入口&quot;">​</a></h3><p>原文说凶德有五，却未在这里列出完整五项，不另补清单。</p><p>“中德”不能按现代中等品德或折中之德理解，最可靠入口是：</p><blockquote><p>有以自好也而吡其所不为者也。</p></blockquote><p>自满于自己的做法，进而贬斥自己不采用的做法。</p><p><strong>现代帮助理解的例子</strong>：尚俭便贬低所有不同消费，擅言便轻视不善表达，退隐便断定任事者逐利，任事便断定退处者无能。</p><p>这些不是原文列举，也不意味着任何不同做法都同样合宜。</p><p>坚持选择不等于以选择作为唯一德行尺度；不轻人也不等于取消善恶判断。</p><h3 id="十、双向检验-识人者不能自免" tabindex="-1">十、双向检验：识人者不能自免 <a class="header-anchor" href="#十、双向检验-识人者不能自免" aria-label="Permalink to &quot;十、双向检验：识人者不能自免&quot;">​</a></h3><table tabindex="0"><thead><tr><th>向外观察</th><th>向内检省</th></tr></thead><tbody><tr><td>他人表现是否稳定？</td><td>我的判断是否自是？</td></tr><tr><td>言行是否相应？</td><td>是否以所长轻人？</td></tr><tr><td>不同处境怎样行动？</td><td>是否把德行据为优越？</td></tr></tbody></table><p>九徵与后文可以形成这一主题联系，但不强说后文已全面反驳九徵方法。</p><p>上一份颜阖批评仲尼，此处又引孔子言，说明不能预设孔子在每个单元中都被全盘肯定或否定。</p><p><strong>先辨谁说、针对什么、引语到哪里，再讨论各单元的照应与张力。</strong></p><h3 id="本份·核心对照-5" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-5" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>难知</td><td>险于山川，难于知天</td><td>不凭外貌定内情</td><td>人人蓄意欺骗</td></tr><tr><td>表里</td><td>厚貌深情</td><td>呈现未必相应</td><td>固定贤者外貌</td></tr><tr><td>变化</td><td>就义若渴，去义若热</td><td>热切未必稳定</td><td>热切者都不可信</td></tr><tr><td>九徵</td><td>九徵至</td><td>多处境观察</td><td>九次必能读心</td></tr><tr><td>应用</td><td>以处境观其行</td><td>合宜合作中的观察</td><td>灌酒、设险、侵犯隐私</td></tr><tr><td>谦退</td><td>一命而伛</td><td>地位不转成自大</td><td>弯身自证德行</td></tr><tr><td>骄张</td><td>三命而名诸父</td><td>增位转成轻慢</td><td>任职者必骄</td></tr><tr><td>德心</td><td>德有心</td><td>德也可能被执取</td><td>有意行善皆错</td></tr><tr><td>内视</td><td>内视而败</td><td>警惕自赏</td><td>停止一切反思</td></tr><tr><td>中德</td><td>中德为首</td><td>由下文理解术语</td><td>中等或折中之德</td></tr><tr><td>结尾</td><td>自好而吡其所不为</td><td>不以己之选择轻人</td><td>取消善恶判断</td></tr></tbody></table><h3 id="本份收束-5" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-5" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>本份先问他人的外貌、言辞与一时表现能否代表实际状态，再问自己的地位、德行与判断是否也被拿来建立优越。</p><p><strong>九徵回到处境 → 正考父检验增位后的姿态 → 自好之德检验评价者自身。</strong></p><p>它不只教人看穿别人，也要求识人者检查自己的评价根据。</p><p>下一批将继续处理八极、三必、得车与骊龙之珠等后续内容，待材料齐全后再统一收束全篇。</p><h2 id="七、八极与三必·骊龙之珠·所得与危险" tabindex="-1">七、八极与三必·骊龙之珠·所得与危险 <a class="header-anchor" href="#七、八极与三必·骊龙之珠·所得与危险" aria-label="Permalink to &quot;七、八极与三必·骊龙之珠·所得与危险&quot;">​</a></h2>',60)),a(l,{title:"危险尚未发动，不等于危险不存在",summary:"从出众条件与穷达的反转，进入匿名得车者的自夸。珍贵所得真实存在，却不能证明风险已经受到控制。"}),t[53]||(t[53]=i('<h3 id="本份范围-6" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-6" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“穷有八极，达有三必，形有六府。”</li><li><strong>止于</strong>：“使宋王而寤，子为齑粉夫！”</li><li><strong>连续脉络</strong>：出众与致穷 → 三种处世状态 → 智勇仁义的负担 → 生知与大小命 → 得车自夸 → 骊龙得珠 → 权势危险。</li></ul><h3 id="原文·连续阅读-6" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-6" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(H),glossary:y,"default-mode":"classic","aria-label":"列御寇·第7份 原文"},null,8,["sections"]),t[54]||(t[54]=d("p",null,[d("strong",null,"文字说明")],-1)),t[55]||(t[55]=d("p",null,"依据此次提供文字整理，调整标点与分段，未另作逐字版本对勘。",-1)),t[56]||(t[56]=d("p",null,"“缘循”“偃佒”“形有六府”“傀”“肖”“大小命”等处有解释差异，以下优先说明上下文关系。",-1)),t[57]||(t[57]=d("p",null,"本段得车者没有姓名，所见君主、所得车数也与曹商不同，不能直接认定为同一人。",-1)),t[58]||(t[58]=d("h3",{id:"关键词卡片-6",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-6","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(M)},null,8,["items"]),t[59]||(t[59]=d("h3",{id:"逐句导读-6",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-6","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:A}),t[60]||(t[60]=d("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:w}),t[61]||(t[61]=i('<h3 id="一、过人为什么反而可能致穷" tabindex="-1">一、过人为什么反而可能致穷？ <a class="header-anchor" href="#一、过人为什么反而可能致穷" aria-label="Permalink to &quot;一、过人为什么反而可能致穷？&quot;">​</a></h3><blockquote><p>八者俱过人也，因以是穷。</p></blockquote><p>文本有意反转容貌、体格与勇力越出众便越有利的判断。</p><p><strong>帮助理解的可能机制</strong>：出众可能引来关注、利用、期待、竞争与冲突。这些不是原文逐项说明的因果。</p><p>明确的提醒是：优势不能自动转成安稳；不能反向建立所有出众者必然受困的公式。</p><p>容貌、身形等也可能天然显著，不能将风险全归咎于当事人爱表现。</p><h3 id="二、三必-不强胜-不是表演无能" tabindex="-1">二、三必：不强胜，不是表演无能 <a class="header-anchor" href="#二、三必-不强胜-不是表演无能" aria-label="Permalink to &quot;二、三必：不强胜，不是表演无能&quot;">​</a></h3><p>“缘循、偃佒、困畏不若人”训释疑难，常联系随顺、不矜张、不逞强争先。</p><p>与八极对读，可先把握：不将压过他人作为处世中心，可能少受牵累。</p><p>但不应据此建议装无能、遇事退缩、逃避责任，或以谦弱表演换安全。</p><p><strong>若不争也被用作求胜技巧，仍可能回到自我经营。</strong></p><h3 id="三、智勇仁义进入关系后-也可能有负担" tabindex="-1">三、智勇仁义进入关系后，也可能有负担 <a class="header-anchor" href="#三、智勇仁义进入关系后-也可能有负担" aria-label="Permalink to &quot;三、智勇仁义进入关系后，也可能有负担&quot;">​</a></h3><blockquote><p>知慧外通，勇动多怨，仁义多责。</p></blockquote><p>三句不强译为同一结构。可辨明的是：能力与德行向外施用，会产生相应关系和后果。</p><p>例如能者被加派事务、凭勇者形成冲突、承担仁义者面对责求，属于现实引申，不是逐字释义。</p><p>文本没有证明智慧、勇敢与仁义无价值，而是要求连同负担一起考察。</p><h3 id="四、生知与大小命-不以局部认识、具体得失代表全部" tabindex="-1">四、生知与大小命：不以局部认识、具体得失代表全部 <a class="header-anchor" href="#四、生知与大小命-不以局部认识、具体得失代表全部" aria-label="Permalink to &quot;四、生知与大小命：不以局部认识、具体得失代表全部&quot;">​</a></h3><p>“达生之情者傀，达于知者肖”常联系广大与狭小的对照，与第三份毫毛、大宁相接：智识精熟未必等于生命安顿。</p><p>“大命、小命”不直接对应长寿短寿或大人物小人物。结合随、遭，可联系根本命限与具体际遇的层次。</p><p>**眼前一次成败不足以代表生命全部。**随顺也不等于所有改变都无意义。</p><h3 id="五、第二位得车者-相似自夸-不同检验" tabindex="-1">五、第二位得车者：相似自夸，不同检验 <a class="header-anchor" href="#五、第二位得车者-相似自夸-不同检验" aria-label="Permalink to &quot;五、第二位得车者：相似自夸，不同检验&quot;">​</a></h3><table tabindex="0"><thead><tr><th>曹商段</th><th>本段</th></tr></thead><tbody><tr><td>有姓名</td><td>匿名</td></tr><tr><td>为宋王使秦</td><td>见宋王</td></tr><tr><td>秦王益车百乘</td><td>宋王锡车十乘</td></tr><tr><td>舐痔反讽</td><td>骊龙之珠警告</td></tr><tr><td>检验尊严代价</td><td>检验安全条件</td></tr></tbody></table><p>两段都不否认所得，分别切断“厚赏即尊贵”和“得赏即可安”的推论。</p><h3 id="六、贫家得珠-先问来源-不只问价值" tabindex="-1">六、贫家得珠：先问来源，不只问价值 <a class="header-anchor" href="#六、贫家得珠-先问来源-不只问价值" aria-label="Permalink to &quot;六、贫家得珠：先问来源，不只问价值&quot;">​</a></h3><p>珠子确实珍贵，已经被取得，对贫家意义重大。譬喻不是靠否认价值成立。</p><p>父亲却命“取石来锻之”，将注意力由收益转到取得的危险。</p><p>这一命令表现拒绝和警惕，但原文没有证明击碎珍珠能消除全部后患，不补成毁掉所得必能消灾。</p><h3 id="七、必遭其睡-成功不等于控制风险" tabindex="-1">七、必遭其睡：成功不等于控制风险 <a class="header-anchor" href="#七、必遭其睡-成功不等于控制风险" aria-label="Permalink to &quot;七、必遭其睡：成功不等于控制风险&quot;">​</a></h3><p>得珠在父亲解释中依赖骊龙暂睡，而不证明潜水者胜过骊龙、深渊已安全，或此后可以重复取得。</p><p><strong>一次顺利完成，与掌握可持续的安全条件不同。</strong></p><p>这属于寓言判断，不能据此将现实中每次成功都说成侥幸。</p><p>若龙醒来，生命可能毁灭。珠子的价值不能抵消力量关系的悬殊。</p><h3 id="八、宋王之寤-悦纳不等于保障" tabindex="-1">八、宋王之寤：悦纳不等于保障 <a class="header-anchor" href="#八、宋王之寤-悦纳不等于保障" aria-label="Permalink to &quot;八、宋王之寤：悦纳不等于保障&quot;">​</a></h3><p>深渊对应政治深险，骊龙对应君主强力。</p><p>“睡”“寤”回指宋王时是譬喻，强调目前宽容、悦纳不保证以后仍如此，不是睡中赐车的记录。</p><table tabindex="0"><thead><tr><th>已成立的事</th><th>尚不能自动证明</th></tr></thead><tbody><tr><td>对方现在喜欢我</td><td>能持续预测对方</td></tr><tr><td>对方现在给资源</td><td>态度变化后仍有保障</td></tr><tr><td>已得十乘</td><td>已摆脱力量上的受制</td></tr></tbody></table><p>不是普遍定罪所有组织或合作，而是警告权势悬殊中以受赏自满轻人的判断。</p><h3 id="本份·核心对照-6" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-6" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>八极</td><td>俱过人，因以是穷</td><td>优势可能反成牵累</td><td>出众必然受困</td></tr><tr><td>三必</td><td>三者俱通达</td><td>不矜张、不强胜</td><td>装无能、逃责任</td></tr><tr><td>智勇仁义</td><td>多怨、多责</td><td>长处与关系负担</td><td>全部应废弃</td></tr><tr><td>生知</td><td>达生之情者傀</td><td>知识与生命通达不同</td><td>知识无价值</td></tr><tr><td>大小命</td><td>达大命者随</td><td>根本与际遇的层次</td><td>只指寿命</td></tr><tr><td>得车</td><td>十乘骄稚庄子</td><td>君赏与自高</td><td>此人就是曹商</td></tr><tr><td>父命</td><td>取石来锻之</td><td>来源与危险</td><td>毁财必消灾</td></tr><tr><td>龙睡</td><td>必遭其睡也</td><td>未发动不等于受控</td><td>成功全是侥幸</td></tr><tr><td>宋王</td><td>使宋王而寤</td><td>悦纳不保安全</td><td>睡中赐车的事实</td></tr><tr><td>全段</td><td>所得与危险</td><td>好处不等于脱离受制</td><td>拒绝全部合作</td></tr></tbody></table><h3 id="本份收束-6" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-6" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>过人不一定更安，得赏不一定更安全。</p><p>评价所得要同时问：价值是什么、如何取得、依赖什么条件、条件改变后是否仍有保障。</p><p><strong>不能把危险尚未发动，当成危险已经不存在。</strong></p><h2 id="八、聘庄子·牺牛之喻·礼遇与受制" tabindex="-1">八、聘庄子·牺牛之喻·礼遇与受制 <a class="header-anchor" href="#八、聘庄子·牺牛之喻·礼遇与受制" aria-label="Permalink to &quot;八、聘庄子·牺牛之喻·礼遇与受制&quot;">​</a></h2>',44)),a(l,{title:"款待最终把生命带向哪里？",summary:"聘请直接来到庄子面前。文绣与供养并不虚假，但必须连同用途、去向及退出可能一起考察。"}),t[62]||(t[62]=i('<h3 id="本份范围-7" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-7" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“或聘于庄子。”</li><li><strong>止于</strong>：“虽欲为孤犊，其可得乎！”</li><li><strong>连续脉络</strong>：聘请 → 牺牛 → 华美供养 → 被牵入庙 → 不能退为孤犊。</li></ul><h3 id="原文·连续阅读-7" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-7" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(Q),glossary:y,"default-mode":"classic","aria-label":"列御寇·第8份 原文"},null,8,["sections"]),t[63]||(t[63]=d("p",null,[d("strong",null,"文字说明")],-1)),t[64]||(t[64]=d("p",null,"原文未交代聘请者姓名、国别、职位与待遇，不补入其他篇章或传记细节。",-1)),t[65]||(t[65]=d("p",null,"“刍菽”及“大庙”的字形与解释依所提供材料保留说明，未作版本对勘。",-1)),t[66]||(t[66]=d("h3",{id:"关键词卡片-7",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-7","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(X)},null,8,["items"]),t[67]||(t[67]=d("h3",{id:"逐句导读-7",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-7","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:V}),t[68]||(t[68]=d("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:C}),t[69]||(t[69]=i('<h3 id="一、自己的选择-先问身份-不先问待遇" tabindex="-1">一、自己的选择：先问身份，不先问待遇 <a class="header-anchor" href="#一、自己的选择-先问身份-不先问待遇" aria-label="Permalink to &quot;一、自己的选择：先问身份，不先问待遇&quot;">​</a></h3><p>前文是受赏者来夸耀，本段是庄子面对自己的聘请。</p><p>“牺牛”从开始便标明祭祀用途，因此文绣、刍菽不是与最终用途无关的好处。</p><p>譬喻清楚呈现警惕与拒绝意味，但没有完整的辞谢过程。</p><h3 id="二、礼遇真实-不证明自己是安排的中心" tabindex="-1">二、礼遇真实，不证明自己是安排的中心 <a class="header-anchor" href="#二、礼遇真实-不证明自己是安排的中心" aria-label="Permalink to &quot;二、礼遇真实，不证明自己是安排的中心&quot;">​</a></h3><p>牛确实被装饰、供养。问题不是待遇虚假，而是这些条件服务于谁的目的。</p><p><strong>受到照料不自动证明自己的利益是整个安排的中心。</strong></p><p>不由此推断所有照料都有恶意；需要具体检查礼遇与用途的关系。</p><h3 id="三、牵而入-谁决定最后去向" tabindex="-1">三、牵而入：谁决定最后去向？ <a class="header-anchor" href="#三、牵而入-谁决定最后去向" aria-label="Permalink to &quot;三、牵而入：谁决定最后去向？&quot;">​</a></h3><p>前文写牛得到什么，“牵”转向牛被带往哪里。</p><p>进入程序后，行动与最后去向可能由他者决定。太庙的庄严不取消牺牲者的代价。</p><p>本段借祭祀处境回应聘请，不是对全部祭祀或公共事业作完整否定。</p><h3 id="四、孤犊与退出-更高待遇不是解决办法" tabindex="-1">四、孤犊与退出：更高待遇不是解决办法 <a class="header-anchor" href="#四、孤犊与退出-更高待遇不是解决办法" aria-label="Permalink to &quot;四、孤犊与退出：更高待遇不是解决办法&quot;">​</a></h3><p>牺牛想退回的不是更华美、更受宠的生活，而是未被选作牺牲的普通处境。</p><table tabindex="0"><thead><tr><th>牺牛</th><th>孤犊</th></tr></thead><tbody><tr><td>特别装饰与供养</td><td>没有显赫礼遇</td></tr><tr><td>承担祭祀用途</td><td>不在这一用途之中</td></tr><tr><td>去向被牵定</td><td>对照中保留更多余地</td></tr></tbody></table><p>孤犊不保证全无危险依赖。反问的重点是：进入之后，可能连恢复普通处境也不可得。</p><h3 id="五、三段任用故事-不能合成富贵一概不好" tabindex="-1">五、三段任用故事：不能合成富贵一概不好 <a class="header-anchor" href="#五、三段任用故事-不能合成富贵一概不好" aria-label="Permalink to &quot;五、三段任用故事：不能合成富贵一概不好&quot;">​</a></h3><table tabindex="0"><thead><tr><th>故事</th><th>所问</th></tr></thead><tbody><tr><td>曹商得车</td><td>为取得厚赏做了什么？</td></tr><tr><td>骊龙之珠</td><td>危险条件是否受到控制？</td></tr><tr><td>牺牛之喻</td><td>礼遇将生命纳入什么用途？</td></tr></tbody></table><p>骊龙突出条件变化；牺牛则说明即使原计划不变，也可能推进到不愿承担的结局。</p><p>与“不系之舟”可作意象对照：不系保留流动，被牵表现去向受定。但不强说两段理论完全相同。</p><h3 id="六、现代引申-看待遇-也看自主与退出" tabindex="-1">六、现代引申：看待遇，也看自主与退出 <a class="header-anchor" href="#六、现代引申-看待遇-也看自主与退出" aria-label="Permalink to &quot;六、现代引申：看待遇，也看自主与退出&quot;">​</a></h3><p>接受任用、合作、支持时，可以问：</p><ul><li>对方提供条件的目的与需要是什么？</li><li>任务、风险、责任是否清楚？</li><li>自己能否参与目标与方式的选择？</li><li>后续要求能否协商？</li><li>不适合时，能否合宜退出？</li></ul><p>这不要求拒绝所有合作。好的安排可以兼顾资源、责任与自主。</p><h3 id="本份·核心对照-7" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-7" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>聘请</td><td>或聘于庄子</td><td>自己的任用选择</td><td>擅补姓名职位</td></tr><tr><td>身份</td><td>牺牛</td><td>礼遇已有用途</td><td>只看受宠</td></tr><tr><td>装饰</td><td>衣以文绣</td><td>华美不自证受益</td><td>衣饰都错</td></tr><tr><td>供养</td><td>食以刍菽</td><td>供养与他者目的</td><td>照料必有恶意</td></tr><tr><td>去向</td><td>牵而入于大庙</td><td>自主与安排</td><td>只反对奢华</td></tr><tr><td>愿望</td><td>为孤犊</td><td>普通处境与余地</td><td>孤犊绝对无险</td></tr><tr><td>反问</td><td>其可得乎</td><td>退出可能丧失</td><td>只是事后后悔</td></tr><tr><td>全段</td><td>礼遇与受制</td><td>看用途与限制</td><td>拒绝所有任用</td></tr></tbody></table><h3 id="本份收束-7" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-7" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>不只问如何被款待，还要问款待为何而设、最终去向由谁决定、进入后是否还能退出。</p><p>牺牛不是未受重视，而是受郑重对待仍不能保全自己的去向。</p><h2 id="九、庄子将死·天地为棺椁·厚葬与偏私" tabindex="-1">九、庄子将死·天地为棺椁·厚葬与偏私 <a class="header-anchor" href="#九、庄子将死·天地为棺椁·厚葬与偏私" aria-label="Permalink to &quot;九、庄子将死·天地为棺椁·厚葬与偏私&quot;">​</a></h2>',30)),a(l,{title:"敬爱不必由形式的丰厚证明",summary:"弟子欲保护老师的身体，庄子则将完备与身体去向放回天地变化，检验关怀中的增添与偏向。"}),t[70]||(t[70]=i('<h3 id="本份范围-8" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-8" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“庄子将死，弟子欲厚葬之。”</li><li><strong>止于</strong>：“夺彼与此，何其偏也！”</li><li><strong>连续脉络</strong>：厚葬心意 → 天地葬具 → 增添之问 → 乌鸢担忧 → 蝼蚁对照 → 偏向之问。</li></ul><h3 id="原文·连续阅读-8" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-8" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(Y),glossary:y,"default-mode":"classic","aria-label":"列御寇·第9份 原文"},null,8,["sections"]),t[71]||(t[71]=d("p",null,[d("strong",null,"文字说明")],-1)),t[72]||(t[72]=d("p",null,"这是临终对话，未接着叙述实际葬法。“天地为棺椁”是尺度转换的譬喻，不直接作为丧葬操作方案。",-1)),t[73]||(t[73]=d("p",null,"下接篇末议论另作第十份，不全部归入庄子的临终引语。",-1)),t[74]||(t[74]=d("h3",{id:"关键词卡片-8",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-8","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(Z)},null,8,["items"]),t[75]||(t[75]=d("h3",{id:"逐句导读-8",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-8","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:R}),t[76]||(t[76]=d("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:I}),t[77]||(t[77]=i('<h3 id="一、心意与方式-不先判弟子虚伪" tabindex="-1">一、心意与方式：不先判弟子虚伪 <a class="header-anchor" href="#一、心意与方式-不先判弟子虚伪" aria-label="Permalink to &quot;一、心意与方式：不先判弟子虚伪&quot;">​</a></h3><p>后文担忧显示弟子至少有保护老师身体的心意，原文未说牟利逐名。</p><p>但敬爱与厚葬须分开：理解心意，不等于表达方式无须检验。</p><p>本段首先动摇“敬爱必然要求厚葬”，不是取消敬爱。</p><h3 id="二、天地葬具-不是只说越少越好" tabindex="-1">二、天地葬具：不是只说越少越好 <a class="header-anchor" href="#二、天地葬具-不是只说越少越好" aria-label="Permalink to &quot;二、天地葬具：不是只说越少越好&quot;">​</a></h3><table tabindex="0"><thead><tr><th>人为葬具的名称</th><th>自然存在</th></tr></thead><tbody><tr><td>棺椁</td><td>天地</td></tr><tr><td>连璧</td><td>日月</td></tr><tr><td>珠玑</td><td>星辰</td></tr><tr><td>赍送</td><td>万物</td></tr></tbody></table><p>这是一种广大而非匮乏的表达，将容纳身体的尺度转向天地。</p><p>不按字面理解为天体进入墓中，也不据此论证灵魂不灭或完整的来世学说。</p><p><strong>死亡仍在天地变化之中，不必只以人工隔绝来理解归宿。</strong></p><h3 id="三、完备与增添-更多未必补足根本" tabindex="-1">三、完备与增添：更多未必补足根本 <a class="header-anchor" href="#三、完备与增添-更多未必补足根本" aria-label="Permalink to &quot;三、完备与增添：更多未必补足根本&quot;">​</a></h3><p>弟子设想更多器物才足够郑重，庄子却问天地容纳是否已经完备，还能增加什么。</p><p>不只是省钱，而是检验人工增添真正补足了什么。</p><p>与前文照应：车多不自证高明，供养厚不自证自主，葬具丰也不自证送别合宜。</p><p>但不取消所有现实丧葬安排。</p><h3 id="四、乌鸢与蝼蚁-埋葬不取消变化" tabindex="-1">四、乌鸢与蝼蚁：埋葬不取消变化 <a class="header-anchor" href="#四、乌鸢与蝼蚁-埋葬不取消变化" aria-label="Permalink to &quot;四、乌鸢与蝼蚁：埋葬不取消变化&quot;">​</a></h3><p>弟子的担忧具体而非单纯排场：不能接受鸟类取食老师身体。</p><p>庄子补出地下小虫，将完全保护的设想转为两种去向的比较。</p><table tabindex="0"><thead><tr><th>地上</th><th>地下</th></tr></thead><tbody><tr><td>乌鸢取食</td><td>蝼蚁取食</td></tr><tr><td>较容易被看见</td><td>较不容易被看见</td></tr><tr><td>被弟子明确担忧</td><td>未在其前一句提及</td></tr></tbody></table><p>人为安排能改变具体条件，不等于取消身体消解与变化。这里也不是完整现代生物学说明。</p><h3 id="五、夺彼与此-关怀也可能夹带偏好" tabindex="-1">五、夺彼与此：关怀也可能夹带偏好 <a class="header-anchor" href="#五、夺彼与此-关怀也可能夹带偏好" aria-label="Permalink to &quot;五、夺彼与此：关怀也可能夹带偏好&quot;">​</a></h3><p>庄子将不给乌鸢改写成转给蝼蚁，指出厚此薄彼。</p><p>不是否认感情，而是检验安排者是否把自己的难以接受直接当成被安排者的需要。</p><p>不抹去葬法在卫生、法律、文化与亲属需要上的实际差别，也不取消一切亲疏和选择。</p><h3 id="六、对读与现代边界" tabindex="-1">六、对读与现代边界 <a class="header-anchor" href="#六、对读与现代边界" aria-label="Permalink to &quot;六、对读与现代边界&quot;">​</a></h3><p>牺牛与厚葬都有郑重安排，前者检验受制与自主，后者检验死亡归宿与偏向，不能等同。</p><p>与《渔父》可共同检验形式与精诚：表达不必越贵越多越真，但都不能简化为废除礼仪。</p><p>现代安排应尊重当事人意愿、家属沟通及法律卫生条件，不把寓言照搬成未说明的葬法。</p><p>原文未写最后葬礼、弟子接受程度及是否暴露遗体，不补成葬事记录。</p><h3 id="本份·核心对照-8" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-8" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>心意</td><td>弟子欲厚葬之</td><td>敬爱与方式分开</td><td>一定虚伪逐名</td></tr><tr><td>尺度</td><td>天地为棺椁</td><td>自然容纳</td><td>具体葬法</td></tr><tr><td>完备</td><td>葬具岂不备邪</td><td>不以人工多寡定完备</td><td>丧葬都无必要</td></tr><tr><td>增添</td><td>何以加此</td><td>更多未必更合宜</td><td>只是省钱</td></tr><tr><td>担忧</td><td>恐乌鸢之食夫子</td><td>具体身体去向</td><td>只求排场</td></tr><tr><td>上下</td><td>乌鸢、蝼蚁</td><td>变化不能全取消</td><td>完整医学说明</td></tr><tr><td>改写</td><td>夺彼与此</td><td>去向间的偏好</td><td>葬法全无区别</td></tr><tr><td>偏向</td><td>何其偏也</td><td>关怀也须检省</td><td>人不应有感情</td></tr><tr><td>边界</td><td>临终对话</td><td>态度与判断转换</td><td>已知最终葬法</td></tr></tbody></table><h3 id="本份收束-8" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-8" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>庄子不取消敬爱，而是问：天地是否已能容纳、增添补足什么、阻止一种去向是否仅偏向另一种。</p><p><strong>敬爱不能只凭厚重形式自证，也不能把自己的偏好认成自然变化的唯一正确安排。</strong></p><h2 id="十、不平与不徵·明与神·恃其所见" tabindex="-1">十、不平与不徵·明与神·恃其所见 <a class="header-anchor" href="#十、不平与不徵·明与神·恃其所见" aria-label="Permalink to &quot;十、不平与不徵·明与神·恃其所见&quot;">​</a></h2>',34)),a(l,{title:"那个判断他人的人，也需要接受检验",summary:"篇末从平正与征验的依据，进入明察的限度，以及有限认识如何被过度授权为干预他人的凭据。"}),t[78]||(t[78]=i('<h3 id="本份范围-9" tabindex="-1">本份范围 <a class="header-anchor" href="#本份范围-9" aria-label="Permalink to &quot;本份范围&quot;">​</a></h3><ul><li><strong>起于</strong>：“以不平平，其平也不平。”</li><li><strong>止于</strong>：“其功外也，不亦悲乎！”</li><li><strong>连续脉络</strong>：尺度 → 征验 → 明与神 → 恃见 → 入于人 → 功外 → 悲叹。</li></ul><h3 id="原文·连续阅读-9" tabindex="-1">原文·连续阅读 <a class="header-anchor" href="#原文·连续阅读-9" aria-label="Permalink to &quot;原文·连续阅读&quot;">​</a></h3>',3)),a(s,{sections:r(tt),glossary:y,"default-mode":"classic","aria-label":"列御寇·第10份 原文"},null,8,["sections"]),t[79]||(t[79]=d("p",null,[d("strong",null,"文字说明")],-1)),t[80]||(t[80]=d("p",null,"本段作为篇末议论，不放入临终对话的引号。",-1)),t[81]||(t[81]=d("p",null,"“平”“徵”兼有不同用法；“明者唯为之使，神者徵之”“其功外也”有训释差异，说明主要结构，不强定唯一译文。",-1)),t[82]||(t[82]=d("h3",{id:"关键词卡片-9",tabindex:"-1"},[e("关键词卡片 "),d("a",{class:"header-anchor",href:"#关键词卡片-9","aria-label":'Permalink to "关键词卡片"'},"​")],-1)),a(o,{items:r(dt)},null,8,["items"]),t[83]||(t[83]=d("h3",{id:"逐句导读-9",tabindex:"-1"},[e("逐句导读 "),d("a",{class:"header-anchor",href:"#逐句导读-9","aria-label":'Permalink to "逐句导读"'},"​")],-1)),a(n,{lines:N}),t[84]||(t[84]=d("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),d("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(n,{lines:D}),t[85]||(t[85]=i('<h3 id="一、不平之平-判断形式不自证尺度可靠" tabindex="-1">一、不平之平：判断形式不自证尺度可靠 <a class="header-anchor" href="#一、不平之平-判断形式不自证尺度可靠" aria-label="Permalink to &quot;一、不平之平：判断形式不自证尺度可靠&quot;">​</a></h3><p>可以借衡器理解：器具不平，经过衡量也不会自动得到平正结果。</p><p><strong>现代帮助理解的问题</strong>：是否先有偏好再找理由，是否以己处境、所长和预定高下作通用标准？</p><p>不是宣布不能判断，而是要求先检验判断所凭。</p><p>可回照曹商以车数、缓以所学、自好者以所为、弟子以厚葬建立的尺度；不强说每句只为某故事作注。</p><h3 id="二、不徵之徵-凭据不能仅靠自己担保" tabindex="-1">二、不徵之徵：凭据不能仅靠自己担保 <a class="header-anchor" href="#二、不徵之徵-凭据不能仅靠自己担保" aria-label="Permalink to &quot;二、不徵之徵：凭据不能仅靠自己担保&quot;">​</a></h3><p>若所凭未经可靠确证，不能据此完成可靠征验。</p><p>君主喜欢、自认有德、一次成功，都可能需要继续检验，不能循环地担保所有结论。</p><p>这是现代证据思考的启发，不将完整逻辑学与证据理论写成原文明言。</p><h3 id="三、明与神-有用不等于全部通达" tabindex="-1">三、明与神：有用不等于全部通达 <a class="header-anchor" href="#三、明与神-有用不等于全部通达" aria-label="Permalink to &quot;三、明与神：有用不等于全部通达&quot;">​</a></h3><p>“明”常联系辨别明察，“使”涉及工具与役使关系；“神”常联系不局限于显见分别的神妙通达，具体句法仍有差异。</p><p>可先把握局部辨识与整体通达的层次，不把工具理解为无用。</p><p>不直接套成理性与迷信、科学与玄学、思考与不思考的对立。</p><p>**也不能以神妙体验或直觉压倒检验。**若以特殊认识要求服从，同样可能落入恃其所见。</p><h3 id="四、恃见入人-部分事实被扩大成支配资格" tabindex="-1">四、恃见入人：部分事实被扩大成支配资格 <a class="header-anchor" href="#四、恃见入人-部分事实被扩大成支配资格" aria-label="Permalink to &quot;四、恃见入人：部分事实被扩大成支配资格&quot;">​</a></h3><p>所见未必全错，可能确有部分事实、办法、成功与观察。</p><p>“恃”把有限所见变成足够、稳固、无需再验的凭据，继而推入他人的生活。</p><p>可联系自学轻亲、君赏轻人、离实学伪、自好贬斥。</p><p>不取消分享与教学，而要求辨认分享认识和强将所见推给他人的差别：能否质疑、是否承认限度、是否尊重具体处境？</p><h3 id="五、功外-善于纠正他人-也要返己" tabindex="-1">五、功外：善于纠正他人，也要返己 <a class="header-anchor" href="#五、功外-善于纠正他人-也要返己" aria-label="Permalink to &quot;五、功外：善于纠正他人，也要返己&quot;">​</a></h3><p>“其功外也”常联系向外用力、未检省自身所凭。</p><p><strong>引申例子</strong>：指出别人偏见却不查己尺度，教人谦让却自高，批评执著却执著于自己无执，善安排别人却不问为何必须安排。</p><p>不由此否定公共工作与助人，而是警惕向外施用和自身检省失衡。</p><p>结尾悲叹不是仅因认识有限，而是有限却自信地干预他人，欲平人却所凭仍不平。</p><h3 id="六、九徵与篇末-不撤销识人-也不让识人者自免" tabindex="-1">六、九徵与篇末：不撤销识人，也不让识人者自免 <a class="header-anchor" href="#六、九徵与篇末-不撤销识人-也不让识人者自免" aria-label="Permalink to &quot;六、九徵与篇末：不撤销识人，也不让识人者自免&quot;">​</a></h3><table tabindex="0"><thead><tr><th>认识他人</th><th>检验自身</th></tr></thead><tbody><tr><td>不只看外貌</td><td>不只信自己所见</td></tr><tr><td>观察实际行动</td><td>检查所用尺度</td></tr><tr><td>使用征验</td><td>检查征验依据</td></tr><tr><td>作出判断</td><td>不自居不受质疑的权威</td></tr></tbody></table><p>篇末没有直接宣布九徵无效，可以理解为识人方法也需要在不自是的态度中使用。</p><h3 id="本份·核心对照-9" tabindex="-1">本份·核心对照 <a class="header-anchor" href="#本份·核心对照-9" aria-label="Permalink to &quot;本份·核心对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>核心句</th><th>主题</th><th>应避免的误读</th></tr></thead><tbody><tr><td>衡量</td><td>以不平平</td><td>检验尺度</td><td>永远不能判断</td></tr><tr><td>征验</td><td>以不徵徵</td><td>检验依据</td><td>已有完整证据理论</td></tr><tr><td>明察</td><td>明者唯为之使</td><td>作用与限度</td><td>明察无用</td></tr><tr><td>神妙</td><td>神者徵之</td><td>超出局部显见</td><td>直觉神灵绝对正确</td></tr><tr><td>对照</td><td>明之不胜神</td><td>局部与整体</td><td>理性迷信二分</td></tr><tr><td>执持</td><td>恃其所见</td><td>有限认识被放大</td><td>所见全部错误</td></tr><tr><td>他人</td><td>入于人</td><td>警惕强加所见</td><td>取消教学劝告</td></tr><tr><td>功用</td><td>其功外也</td><td>向外也须返己</td><td>助人与公共事务无意义</td></tr><tr><td>悲叹</td><td>不亦悲乎</td><td>评价者须受检验</td><td>只有他人须修正</td></tr></tbody></table><h3 id="本份收束-9" tabindex="-1">本份收束 <a class="header-anchor" href="#本份收束-9" aria-label="Permalink to &quot;本份收束&quot;">​</a></h3><p>衡量前检验尺度，征验前检验依据，运用所知时承认限度，向外施用时不忘返己。</p><p>从列子惊惧到曹商自夸，从牺牛礼遇到弟子厚葬，看似有利、郑重和正确的事不断重受检验。</p><p><strong>最后，检验回到那个自以为已经看清的人。</strong></p><h2 id="全篇脉络·十份阅读地图" tabindex="-1">全篇脉络·十份阅读地图 <a class="header-anchor" href="#全篇脉络·十份阅读地图" aria-label="Permalink to &quot;全篇脉络·十份阅读地图&quot;">​</a></h2>',34)),a(l,{title:"一项长处、一次成功，不足以结束整体判断",summary:"十个单元从显露与依附、身份与自是，推进到技艺、君赏、治理、识人及生命去向。篇末将判断本身重新放回检验。"}),t[86]||(t[86]=i('<h3 id="整理说明" tabindex="-1">整理说明 <a class="header-anchor" href="#整理说明" aria-label="Permalink to &quot;整理说明&quot;">​</a></h3><p>本篇由不同故事与议论组成，不强编为连续发生的单一故事，也不预设每个人物在各段中功能完全一致。</p><p>阅读持续区分：</p><ul><li><strong>原文叙事</strong>：实际写出什么行动与结果？</li><li><strong>人物判断</strong>：谁提出解释，针对什么？</li><li><strong>整理归纳</strong>：不同单元可形成哪些联系？</li><li><strong>现代引申</strong>：哪些启发需要另加现实条件？</li></ul><h2 id="行动线与检验线" tabindex="-1">行动线与检验线 <a class="header-anchor" href="#行动线与检验线" aria-label="Permalink to &quot;行动线与检验线&quot;">​</a></h2><h4 id="十个单元的推进" tabindex="-1">十个单元的推进 <a class="header-anchor" href="#十个单元的推进" aria-label="Permalink to &quot;十个单元的推进&quot;">​</a></h4><table tabindex="0"><thead><tr><th>单元</th><th>主要问题</th></tr></thead><tbody><tr><td>列子惊返</td><td>能察风险，是否已止息招引？</td></tr><tr><td>郑人缓</td><td>所学是否成为自高轻亲的凭据？</td></tr><tr><td>知言与屠龙</td><td>精熟、言说与所求是否通向安顿？</td></tr><tr><td>曹商得车</td><td>厚赏能否自证高明与尊严？</td></tr><tr><td>颜阖与内外刑</td><td>治理、施惠是否仍会失真耗损？</td></tr><tr><td>九徵与自好</td><td>怎样观察他人，又怎样检查自己？</td></tr><tr><td>八极与骊龙</td><td>优势、所得是否足以证明可安？</td></tr><tr><td>牺牛之聘</td><td>礼遇是否保留自主与退出？</td></tr><tr><td>庄子厚葬</td><td>敬爱是否夹带未经检省的偏向？</td></tr><tr><td>不平与不徵</td><td>评价者的尺度与依据是否可靠？</td></tr></tbody></table><h4 id="四条反复出现的检验线" tabindex="-1">四条反复出现的检验线 <a class="header-anchor" href="#四条反复出现的检验线" aria-label="Permalink to &quot;四条反复出现的检验线&quot;">​</a></h4><p><strong>所能</strong>：能力、知识、条件出众 → 未必免于劳忧与牵累。</p><p><strong>所得</strong>：受赏、珍珠、待遇丰厚 → 未必证明尊贵、安全与自主。</p><p><strong>所为</strong>：治理、施惠、厚葬 → 未必仅凭美名和效果就合宜。</p><p><strong>所见</strong>：识人、判断、明察 → 未必足以授权自己规范他人。</p><p>这是总读归纳，不是原文严格列出的四阶段体系。</p><h4 id="从外部成功回到自身根据" tabindex="-1">从外部成功回到自身根据 <a class="header-anchor" href="#从外部成功回到自身根据" aria-label="Permalink to &quot;从外部成功回到自身根据&quot;">​</a></h4><p>显露与关注 → 身份与优越 → 技巧与功用 → 君赏与代价 → 礼遇与受制 → 判断与自是。</p><p>这种主题递进不意味着所有单元只表达同一个答案。取得方式、安全条件、自主余地和认识限度仍须分别讨论。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h4 id="第一问-为什么优势、才能与厚赏反而需要警觉" tabindex="-1">第一问：为什么优势、才能与厚赏反而需要警觉？ <a class="header-anchor" href="#第一问-为什么优势、才能与厚赏反而需要警觉" aria-label="Permalink to &quot;第一问：为什么优势、才能与厚赏反而需要警觉？&quot;">​</a></h4><p><strong>因为它们是真实好处，也可能同时带来关系、条件与代价。</strong></p><p>列子能观察先馈背后的任用风险，却仍招引依附；八极提醒过人条件不必然使人安稳；屠龙写技成却无所用。</p><p>君赏的三个故事分别检验：</p><table tabindex="0"><thead><tr><th>故事</th><th>厚赏未能证明什么？</th></tr></thead><tbody><tr><td>曹商</td><td>行为尊贵</td></tr><tr><td>骊龙</td><td>风险已受控制</td></tr><tr><td>牺牛</td><td>自主与退出仍在</td></tr></tbody></table><p>因而，不是把一切成就判为虚假，而是不将一项优势当成完整处境。</p><p><strong>需要问：如何形成、怎样使用、依赖谁、承担什么、还能否改变去向？</strong></p><p>也不能反向将风险都归责于个人：天然出众、他人依附、权势压迫各有不同来源。</p><h4 id="第二问-本篇是否反对知识、仁义、治理与礼仪" tabindex="-1">第二问：本篇是否反对知识、仁义、治理与礼仪？ <a class="header-anchor" href="#第二问-本篇是否反对知识、仁义、治理与礼仪" aria-label="Permalink to &quot;第二问：本篇是否反对知识、仁义、治理与礼仪？&quot;">​</a></h4><p><strong>存在鲜明批评，但不能概括成全部取消。</strong></p><p>所批评的重点包括：</p><ul><li>知识转成显示与自我担保。</li><li>技巧精熟脱离实际处境。</li><li>仁义、教化成为形式与强作。</li><li>施惠转成执功索报。</li><li>德行转成自赏轻人。</li><li>厚葬将关怀等同于形式增添。</li></ul><p>“勿言”“忍性”“德有心”“内视”等词须放在语境中，不能一律解释为禁止表达、自制、行善与内省。</p><p>本篇也确有理想化与古代生命观的表达，如无能、真人、明神、阴阳之刑；既保留文本力度，也不直接转成现代行动、医学或结果保证。</p><p><strong>形式可以有作用，但不能替代内容；知识可以有价值，但不能独占全部通达。</strong></p><h4 id="第三问-既然判断有限-还能否识人、劝人和参与事务" tabindex="-1">第三问：既然判断有限，还能否识人、劝人和参与事务？ <a class="header-anchor" href="#第三问-既然判断有限-还能否识人、劝人和参与事务" aria-label="Permalink to &quot;第三问：既然判断有限，还能否识人、劝人和参与事务？&quot;">​</a></h4><p><strong>能够判断，不等于可以不检验自己的判断。</strong></p><p>九徵将观察放回多种处境，篇末则检验征验本身的依据。</p><p>可以归纳为：</p><ol><li>不只凭外貌与一时态度。</li><li>不把任务失败全等同于人格缺陷。</li><li>不以自身选择为唯一德行尺度。</li><li>不以有限所见强迫他人。</li><li>让判断保留修正、质疑与反馈的空间。</li></ol><p>本篇没有提供现代的完整证据体系，也未全面撤销九徵。</p><p>可取的方向是：<strong>识人须伴随自省，施教须承认限度，向外有功也不能忘记返己。</strong></p><h2 id="阅读辨析与疑难校正" tabindex="-1">阅读辨析与疑难校正 <a class="header-anchor" href="#阅读辨析与疑难校正" aria-label="Permalink to &quot;阅读辨析与疑难校正&quot;">​</a></h2><h4 id="不言与教诲" tabindex="-1">不言与教诲 <a class="header-anchor" href="#不言与教诲" aria-label="Permalink to &quot;不言与教诲&quot;">​</a></h4><p>文本赞许勿言，却通过问答、故事与反讽教诲。不能简单化为一句不说。</p><p>可理解为警惕以言说显示、争强与推广自身，但原文没有完成所有应言情境的系统划分。</p><h4 id="无能与识人能力" tabindex="-1">无能与识人能力 <a class="header-anchor" href="#无能与识人能力" aria-label="Permalink to &quot;无能与识人能力&quot;">​</a></h4><p>无能、无所求受到赞许，九徵又细察能、知、信等。这不是同一层次的机械矛盾，也不能全部抹平。</p><p>前者涉及不以显能求取，后者涉及实际观察；不同单元的力度与功能仍须分别看。</p><h4 id="内刑与外刑" tabindex="-1">内刑与外刑 <a class="header-anchor" href="#内刑与外刑" aria-label="Permalink to &quot;内刑与外刑&quot;">​</a></h4><p>自身失当可能耗损生命，但外部刑害同时存在。</p><p>不能借修身要求否认迫害、环境与他人的责任，更不能以疾病、死亡反推修养不足。</p><h4 id="批评仲尼与引用孔子" tabindex="-1">批评仲尼与引用孔子 <a class="header-anchor" href="#批评仲尼与引用孔子" aria-label="Permalink to &quot;批评仲尼与引用孔子&quot;">​</a></h4><p>颜阖评议仲尼，九徵又由孔子发言。应辨人物在各单元承担什么功能，不设定全篇对孔子单一、无差别的立场。</p><h4 id="敬爱与偏向" tabindex="-1">敬爱与偏向 <a class="header-anchor" href="#敬爱与偏向" aria-label="Permalink to &quot;敬爱与偏向&quot;">​</a></h4><p>厚葬有爱护心意，却仍被检验。心意与方式不必同时被肯定或否定。</p><p>尊重感情，也不将感情自动提升为安排他人去向的充分理由。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><blockquote><p>以下为现代引申，不直接视为原文确定含义，也不照搬古代征验、生命观或礼制。</p></blockquote><h4 id="评价成功时-不只看数量与排场" tabindex="-1">评价成功时，不只看数量与排场 <a class="header-anchor" href="#评价成功时-不只看数量与排场" aria-label="Permalink to &quot;评价成功时，不只看数量与排场&quot;">​</a></h4><p>报酬、职位、资源与认可各有意义，但须另问取得方式、贡献、代价和风险。</p><p>不以自己的成功羞辱他人的贫困，也不反向将贫困浪漫化为天然高尚。</p><h4 id="接受机会时-检查用途与退出" tabindex="-1">接受机会时，检查用途与退出 <a class="header-anchor" href="#接受机会时-检查用途与退出" aria-label="Permalink to &quot;接受机会时，检查用途与退出&quot;">​</a></h4><p>明确任务、责任、风险、决定权与协商机制。</p><p>不把眼前优待当成长期安全；也不因有风险就拒绝所有合宜合作。</p><h4 id="学习时-检验能力与生活的联系" tabindex="-1">学习时，检验能力与生活的联系 <a class="header-anchor" href="#学习时-检验能力与生活的联系" aria-label="Permalink to &quot;学习时，检验能力与生活的联系&quot;">​</a></h4><p>所学是否有实际对象，投入是否可承受，是否值得长期维持？</p><p>不将价值缩成即时赚钱，也不以热爱免除代价与适用性的检验。</p><h4 id="相处时-不把差异变成高下" tabindex="-1">相处时，不把差异变成高下 <a class="header-anchor" href="#相处时-不把差异变成高下" aria-label="Permalink to &quot;相处时，不把差异变成高下&quot;">​</a></h4><p>可坚持自己的选择，仍承认他人有不同处境与善处。</p><p>需要批评的行为，以具体根据说明，不仅以“我不如此”作为否定理由。</p><h4 id="识人时-观察真实合作而不制造陷阱" tabindex="-1">识人时，观察真实合作而不制造陷阱 <a class="header-anchor" href="#识人时-观察真实合作而不制造陷阱" aria-label="Permalink to &quot;识人时，观察真实合作而不制造陷阱&quot;">​</a></h4><p>看持续守约、资源处理、压力下沟通和分歧中的尊重。</p><p>不灌酒设险、不侵犯隐私；先检验任务与条件是否合理。</p><h4 id="助人时-不把给予变成长期索取" tabindex="-1">助人时，不把给予变成长期索取 <a class="header-anchor" href="#助人时-不把给予变成长期索取" aria-label="Permalink to &quot;助人时，不把给予变成长期索取&quot;">​</a></h4><p>对实际作用可以承认，对必要记录可以保留；同时检省是否借善行要求服从、感激和自我优越。</p><h4 id="面对去向安排-区分当事人意愿与自己的不安" tabindex="-1">面对去向安排，区分当事人意愿与自己的不安 <a class="header-anchor" href="#面对去向安排-区分当事人意愿与自己的不安" aria-label="Permalink to &quot;面对去向安排，区分当事人意愿与自己的不安&quot;">​</a></h4><p>任用、照料、丧葬等安排要沟通，不只展示郑重。</p><p>现实丧葬仍遵守法律、公共卫生和可行条件，不以天地葬具譬喻作操作指令。</p><h4 id="作判断时-让尺度也接受检验" tabindex="-1">作判断时，让尺度也接受检验 <a class="header-anchor" href="#作判断时-让尺度也接受检验" aria-label="Permalink to &quot;作判断时，让尺度也接受检验&quot;">​</a></h4><p>我所凭是否充分？是否以一次成功担保全部？是否允许反证？是否把认识限度推广成他人的义务？</p><p><strong>真正需要警惕的，不只是知道得少，而是知道有限却认为已经足够支配。</strong></p><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关键词</th><th>阅读定位</th><th>主要问题</th></tr></thead><tbody><tr><td>中返、先馈</td><td>第一份</td><td>优待为何引出警觉？</td></tr><tr><td>内诚、成光</td><td>第一份</td><td>非蓄意显露是否仍会招引？</td></tr><tr><td>任事、效功</td><td>第一份</td><td>重视如何转成劳忧？</td></tr><tr><td>保汝、感豫出异</td><td>第一份</td><td>依附与相感怎样牵动自身？</td></tr><tr><td>发药</td><td>第一份</td><td>求教与领悟有何距离？</td></tr><tr><td>巧者、知者、无能</td><td>第一份</td><td>能力与求取如何相连？</td></tr><tr><td>不系之舟、虚</td><td>第一份</td><td>松开拘系而非取消关系</td></tr><tr><td>为儒、弟墨</td><td>第二份</td><td>学习影响与认同差异</td></tr><tr><td>人之天、造物</td><td>第二份</td><td>人是否只由身份定义？</td></tr><tr><td>自异、贱亲</td><td>第二份</td><td>差异怎样变成轻人？</td></tr><tr><td>遁天之刑、所安</td><td>第二份</td><td>执持的伤害与安定根据</td></tr><tr><td>知道、勿言、天而不人</td><td>第三份</td><td>如何对待所知与表达？</td></tr><tr><td>屠龙、技成、无所用</td><td>第三份</td><td>精熟怎样联系处境？</td></tr><tr><td>必、不必、兵、求</td><td>第三份</td><td>强作必然与争竞</td></tr><tr><td>苞苴、竿牍、蹇浅</td><td>第三份</td><td>局促往来如何耗神？</td></tr><tr><td>太初、无始、无何有</td><td>第三份</td><td>固定形迹之外的根本表达</td></tr><tr><td>毫毛、大宁</td><td>第三份</td><td>细节与整体安顿</td></tr><tr><td>所短、所长、百乘</td><td>第四份</td><td>君赏与贫困能否定高下？</td></tr><tr><td>愈下愈多</td><td>第四份</td><td>报酬与取得代价</td></tr><tr><td>贞幹、有瘳</td><td>第五份</td><td>名望与治理效果</td></tr><tr><td>饰羽、华辞、以支为旨</td><td>第五份</td><td>形式是否替代根本？</td></tr><tr><td>忍性、离实学伪</td><td>第五份</td><td>强作范式是否损性？</td></tr><tr><td>施惠、不忘、天布</td><td>第五份</td><td>给予是否成为执功？</td></tr><tr><td>内刑、外刑、真人</td><td>第五份</td><td>不同来源的伤害与理想</td></tr><tr><td>厚貌深情、九徵</td><td>第六份</td><td>如何观察而不只信表象？</td></tr><tr><td>正考父、受命</td><td>第六份</td><td>地位是否转成轻慢？</td></tr><tr><td>德有心、内视</td><td>第六份</td><td>检省与自赏的区别</td></tr><tr><td>中德、自好、吡</td><td>第六份</td><td>不以自己的做法轻人</td></tr><tr><td>八极、三必、六府</td><td>第七份</td><td>条件与穷达的疑难关系</td></tr><tr><td>达生、达知、大小命</td><td>第七份</td><td>认识与生命际遇的层次</td></tr><tr><td>骊龙、珠、睡寤</td><td>第七份</td><td>成功与危险条件</td></tr><tr><td>牺牛、文绣、刍菽</td><td>第八份</td><td>优待与用途</td></tr><tr><td>牵、大庙、孤犊</td><td>第八份</td><td>去向与退出余地</td></tr><tr><td>厚葬、天地棺椁</td><td>第九份</td><td>敬爱与葬具尺度</td></tr><tr><td>乌鸢、蝼蚁、偏</td><td>第九份</td><td>安排中的自然去向与偏好</td></tr><tr><td>平、徵</td><td>第十份</td><td>衡量与凭据也须检验</td></tr><tr><td>明、神</td><td>第十份</td><td>局部辨识与通达的层次</td></tr><tr><td>恃见、入人、功外</td><td>第十份</td><td>判断权与自身检省</td></tr></tbody></table><h2 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>核心句</th><th>所在部分</th><th>阅读提示</th></tr></thead><tbody><tr><td>列御寇之齐，中道而反。</td><td>第一份</td><td>已警觉，不等于已解除牵累</td></tr><tr><td>彼将任我以事，而效我以功。</td><td>第一份</td><td>优待可能转成任用责求</td></tr><tr><td>人将保汝矣！</td><td>第一份</td><td>留下仍可能招引依附</td></tr><tr><td>巧者劳而知者忧。</td><td>第一份</td><td>能力与关系负担</td></tr><tr><td>汎若不系之舟，虚而敖游者也！</td><td>第一份</td><td>松开求取与执持</td></tr><tr><td>以己为有以异于人，以贱其亲。</td><td>第二份</td><td>不将差异变成高下</td></tr><tr><td>古者谓之遁天之刑。</td><td>第二份</td><td>执持可能构成伤害</td></tr><tr><td>圣人安其所安，不安其所不安。</td><td>第二份</td><td>检验安定的根据</td></tr><tr><td>知道易，勿言难。</td><td>第三份</td><td>所知之后仍需克制</td></tr><tr><td>三年技成而无所用其巧。</td><td>第三份</td><td>技成不能自证意义</td></tr><tr><td>众人以不必必之。</td><td>第三份</td><td>强作非如此不可</td></tr><tr><td>敝精神乎蹇浅。</td><td>第三份</td><td>小范围也能耗神</td></tr><tr><td>汝为知在毫毛而不知大宁。</td><td>第三份</td><td>精熟与整体安顿</td></tr><tr><td>商之所短也；……商之所长也。</td><td>第四份</td><td>借长短自述建立高下</td></tr><tr><td>所治愈下，得车愈多。</td><td>第四份</td><td>厚赏可能伴随自辱</td></tr><tr><td>子行矣！</td><td>第四份</td><td>逐客未证明悔悟</td></tr><tr><td>今使民离实学伪，非所以视民也。</td><td>第五份</td><td>教化方式须检验</td></tr><tr><td>施于人而不忘，非天布也。</td><td>第五份</td><td>施惠之后是否执功？</td></tr><tr><td>虽以事齿之，神者弗齿。</td><td>第五份</td><td>作用不等于修养</td></tr><tr><td>为外刑者，金与木也；为内刑者，动与过也。</td><td>第五份</td><td>伤害来源不同</td></tr><tr><td>人者厚貌深情。</td><td>第六份</td><td>不凭外貌断内情</td></tr><tr><td>九徵至，不肖人得矣。</td><td>第六份</td><td>多处境观察，不作读心保证</td></tr><tr><td>一命而伛，再命而偻，三命而俯。</td><td>第六份</td><td>增位不自高</td></tr><tr><td>贼莫大乎德有心。</td><td>第六份</td><td>德也可能被执取</td></tr><tr><td>有以自好也而吡其所不为者也。</td><td>第六份</td><td>不以所为轻人</td></tr><tr><td>八者俱过人也，因以是穷。</td><td>第七份</td><td>优势未必更安</td></tr><tr><td>达生之情者傀，达于知者肖。</td><td>第七份</td><td>生知之别，保留训释</td></tr><tr><td>子能得珠者，必遭其睡也。</td><td>第七份</td><td>成功不自证风险受控</td></tr><tr><td>使宋王而寤，子为齑粉夫！</td><td>第七份</td><td>悦纳与安全不同</td></tr><tr><td>衣以文绣，食以刍菽。</td><td>第八份</td><td>优待须连同用途</td></tr><tr><td>虽欲为孤犊，其可得乎！</td><td>第八份</td><td>退出可能已失</td></tr><tr><td>吾以天地为棺椁。</td><td>第九份</td><td>转换归宿与完备尺度</td></tr><tr><td>吾葬具岂不备邪？何以加此！</td><td>第九份</td><td>增添未必补足根本</td></tr><tr><td>夺彼与此，何其偏也！</td><td>第九份</td><td>关怀中的偏向</td></tr><tr><td>以不平平，其平也不平。</td><td>第十份</td><td>尺度也须检验</td></tr><tr><td>以不徵徵，其徵也不徵。</td><td>第十份</td><td>凭据不能自证</td></tr><tr><td>愚者恃其所见入于人。</td><td>第十份</td><td>有限认识的过度授权</td></tr><tr><td>其功外也，不亦悲乎！</td><td>第十份</td><td>向外施用不忘返己</td></tr></tbody></table><h2 id="全篇核心总表" tabindex="-1">全篇核心总表 <a class="header-anchor" href="#全篇核心总表" aria-label="Permalink to &quot;全篇核心总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>全篇提醒</th><th>应避免的误读</th></tr></thead><tbody><tr><td>显露</td><td>不故意炫耀仍可能招引</td><td>一切依附皆是本人过错</td></tr><tr><td>所学</td><td>身份不能成为轻人凭据</td><td>学习和差异都应取消</td></tr><tr><td>技巧</td><td>技成还须检验代价与处境</td><td>只按即时收益评价知识</td></tr><tr><td>所求</td><td>不强作所有事非如此不可</td><td>所有事情都无所谓</td></tr><tr><td>厚赏</td><td>分别检验尊严、安全、自主</td><td>富贵全恶、贫困全贤</td></tr><tr><td>治理</td><td>美名不担保实际合宜</td><td>一切教育规范都伤真</td></tr><tr><td>施惠</td><td>作用与执功须分开</td><td>记得助人便失德</td></tr><tr><td>刑害</td><td>内外来源同时辨明</td><td>疾病受害全因修养不足</td></tr><tr><td>识人</td><td>多处境观察也要反省己</td><td>设险灌酒必能验人</td></tr><tr><td>德行</td><td>不将善行据为自高</td><td>有意行善与内省皆错</td></tr><tr><td>优势</td><td>过人不等于可安</td><td>出众者必然受困</td></tr><tr><td>礼遇</td><td>看用途、决定权与退出</td><td>拒绝所有合作</td></tr><tr><td>厚葬</td><td>心意与形式、偏好分开</td><td>无须现实葬法与法规</td></tr><tr><td>明神</td><td>局部辨识不等于全部通达</td><td>迷信或直觉绝对正确</td></tr><tr><td>判断</td><td>所凭尺度也须检验</td><td>永远不能判断</td></tr><tr><td>篇末</td><td>评价者不自免于修正</td><td>只有别人需要受教</td></tr></tbody></table><h2 id="十份·一句话回顾" tabindex="-1">十份·一句话回顾 <a class="header-anchor" href="#十份·一句话回顾" aria-label="Permalink to &quot;十份·一句话回顾&quot;">​</a></h2><ol><li><strong>惊返与先馈</strong>：受优待不是安全信号，列子因此中途折返。</li><li><strong>郑人缓</strong>：儒墨之争与亲情相缠，遁天之刑由自己招来。</li><li><strong>知道与不言</strong>：屠龙之巧无用于世，知道者未必能言。</li><li><strong>曹商得车</strong>：厚赏不证明手段正当，庄子逐客而自守。</li><li><strong>颜阖论仲尼</strong>：离实学伪，内刑与外刑都从失真开始。</li><li><strong>人心与九徵</strong>：识人要靠征验，而征验的尺度也要受检验。</li><li><strong>八极与三必</strong>：骊龙之珠得之不易，所得与危险同源。</li><li><strong>聘庄子</strong>：牺牛之喻——礼遇越隆重，受制可能越深。</li><li><strong>庄子将死</strong>：天地为棺椁，厚葬之请照出的是活人的偏私。</li><li><strong>不平与不徵</strong>：以不平平、以不徵徵，最后把检验放回判断者自己。</li></ol><h2 id="一句话读懂《列御寇》" tabindex="-1">一句话读懂《列御寇》 <a class="header-anchor" href="#一句话读懂《列御寇》" aria-label="Permalink to &quot;一句话读懂《列御寇》&quot;">​</a></h2><blockquote><p><strong>「以不平平，其平也不平；以不徵徵，其徵也不徵。」</strong></p></blockquote><p>这句是全篇的收口：用什么去衡量，就决定了衡量能给出什么。所以《列御寇》既讲「怎样识人」，也一直追问「凭什么识」——受优待者要警觉，得厚赏者要问手段，识人者要接受同一把尺子的检验。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><h4 id="本次实际依据" tabindex="-1">本次实际依据 <a class="header-anchor" href="#本次实际依据" aria-label="Permalink to &quot;本次实际依据&quot;">​</a></h4><ul><li>《庄子·杂篇·列御寇》：以用户分三批提供的原文为工作底本。</li><li>用户提供的十份分段释义、辨析与对读材料。</li><li>前篇《渔父》及相关《说剑》整理中已提出的对读方向。</li></ul><h4 id="后续校核可参考" tabindex="-1">后续校核可参考 <a class="header-anchor" href="#后续校核可参考" aria-label="Permalink to &quot;后续校核可参考&quot;">​</a></h4><p>以下书目可用于核对字词、句读及不同解释，本次未逐条查核或引用其具体注释：</p><ul><li>郭庆藩《庄子集释》。</li><li>王先谦《庄子集解》。</li><li>陈鼓应《庄子今注今译》。</li></ul><p><strong>引用边界</strong>：疑难语句的保留说明不等于已完成版本对勘。寓言、梦境、反讽和人物判断不直接作为历史事实；现代启发不等同于原文确定含义。</p><h2 id="全篇最后一问" tabindex="-1">全篇最后一问 <a class="header-anchor" href="#全篇最后一问" aria-label="Permalink to &quot;全篇最后一问&quot;">​</a></h2><p>第一节先是一个警觉：</p><p><strong>「吾惊焉。」</strong></p><p>末节落到一个反问：</p><p><strong>「愚者恃其所见入于人，其功外也，不亦悲乎！」</strong></p><p>从「被优待而惊」到「恃所见而悲」，中间十个单元反复检验同一件事。于是最后可以这样问自己：</p><p><strong>我得到的好处，是谁在为什么付账？</strong></p><p><strong>我所擅长的，和当下的处境相称吗？</strong></p><p><strong>我用来衡量别人的那把尺子，量过我自己吗？</strong></p><p><strong>我以为已经看清的事，还留着继续看清的余地吗？</strong></p><h2 id="全篇收束·少一点显能-多一点自检" tabindex="-1">全篇收束·少一点显能，多一点自检 <a class="header-anchor" href="#全篇收束·少一点显能-多一点自检" aria-label="Permalink to &quot;全篇收束·少一点显能，多一点自检&quot;">​</a></h2><p>《列御寇》不让一项长处、一种美名或一次成功独自结束整体判断。</p><p><strong>所能</strong>须问怎样使用，<br><strong>所得</strong>须问怎样取得、依赖什么，<br><strong>所为</strong>须问内容、根据与人我后果，<br><strong>所见</strong>须问凭据、限度及如何对待他人。</p><p>从不系之舟到被牵的牺牛，从得车自夸到天地为葬具，文本不断转换惯常的高下与利害尺度。</p><p>最后，问题回到判断者：</p><blockquote><p>我是否以自己的所长轻人？<br> 是否把一次成功当成处境安全的证明？<br> 是否用郑重形式替代实际内容？<br> 是否把有限所见，当成替他人决定的充分资格？</p></blockquote><p>本篇要求的不只是少一点显能、强求和自赏，也包括更多对条件、后果与自身根据的检验。</p><p><strong>那个以为自己已经看清的人，也需要保留继续看清的可能。</strong></p>',115))])}}});export{ot as __pageData,st as default};
